template <typename T>
bool take_bounded_log_slot(std::atomic<T>& counter, uint64_t limit) {
    if (!g_config.logging_enabled) {
        return false;
    }
    const T bounded_limit = static_cast<T>(limit);
    T current = counter.load(std::memory_order_relaxed);
    while (current < bounded_limit) {
        if (counter.compare_exchange_weak(
                current, static_cast<T>(current + 1),
                std::memory_order_relaxed, std::memory_order_relaxed)) {
            return true;
        }
    }
    return false;
}

bool temporal_backend_is_taau() {
    return g_config.temporal_backend == TemporalBackend::Taau;
}

bool temporal_backend_is_dlss() {
    return g_config.temporal_backend == TemporalBackend::Dlss;
}

// [FIX:NATIVE-DLSS-OWNER-ISOLATION V1416 1/8] Native Mode-3 DLSS keeps the
// validated public Streamline completion owner from V1409. Private direct NGX
// belongs exclusively to the explicitly enabled OptiScaler backend.
bool native_dlss_public_streamline_owner_active() {
    return temporal_backend_is_dlss() && !g_config.optiscaler_enabled &&
        g_config.openxr_enabled && g_config.openxr_mode == 3;
}

bool optiscaler_private_ngx_owner_active() {
    return temporal_backend_is_dlss() && g_config.optiscaler_enabled;
}

bool high_frequency_runtime_diagnostics_active() {
    // This feeds the periodic render-fingerprint line in witcher3vr.log.
    return g_config.runtime_diagnostics;
}

bool engine_view_runtime_probe_active() {
    // The detour emits bounded EngineViewConstants samples into the main log.
    return g_config.runtime_diagnostics;
}

bool present_pacing_runtime_diagnostics_active() {
    // These samples feed the 300-Present pacing line in witcher3vr.log.
    return g_config.runtime_diagnostics;
}

bool taau_resolve_runtime_diagnostics_active() {
    // Resolve health, identity and private-history lines are text diagnostics.
    return g_config.runtime_diagnostics;
}

bool retained_hud_runtime_audit_active() {
    // The counters are consumed by the periodic retained-HUD audit file.
    return g_config.logging_enabled || g_config.runtime_diagnostics;
}

bool mode3_aer_afw_post_hud_gameplay_active();
bool mode3_aer_afw_baked_hud_cinema_active();
bool mode3_aer_cinema_sequential_present_source_active();
bool mode3_aer_sequential_full_vr_retained_hud_active();
extern std::atomic<bool> g_automatic_full_vr_camera_active;
bool stereo_icon_policy_transport_active();
bool mode3_aer_presentation_active();

bool geometry_stereo_transport_active() {
    return g_config.openxr_mode == kOpenXrModeStereo;
}

bool dlss_sequential_mode_active() {
    return g_config.openxr_mode == 3 &&
        g_config.temporal_backend == TemporalBackend::Dlss;
}

// [FIX:MODE3-TAAU-NATIVE-FULL-MOTION V14000 1/8] AER and strict Stereo are
// presentation policies inside the same Mode-3 producer. Keep one temporal
// motion contract for both and leave Modes 1/2/4 plus every other backend
// unchanged.
bool mode3_taau_native_full_motion_active() {
    return g_config.openxr_enabled && g_config.openxr_mode == 3 &&
        g_config.temporal_backend == TemporalBackend::Taau;
}

bool engine_native_per_eye_temporal_history_active() {
    return dlss_sequential_mode_active() ||
        mode3_taau_native_full_motion_active();
}

bool dlss_submitted_cache_route_active() {
    // [FIX:UNIFIED-MODE3-TRANSPORT V1234 1/6] The final
    // backbuffer belongs to the DLSS producer actually accepted by the game
    // queue, not to DXGI Present parity or a projection-specific cache. Both
    // symmetric and asymmetric Mode-3 DLSS publish this exact producer.
    return w3vr::mode3_transport::dlss_submission_route_active(
        mode3_aer_presentation_active(),
        g_config.temporal_backend == TemporalBackend::Dlss
            ? w3vr::mode3_transport::TemporalAdapter::Dlss
            : (g_config.temporal_backend == TemporalBackend::Taau
                ? w3vr::mode3_transport::TemporalAdapter::Taau
                : w3vr::mode3_transport::TemporalAdapter::None));
}

bool mode3_stereo_transport_active() {
    // [FIX:COMMON-MODE3-TRANSPORT 1/8] Mode 3 is the accepted stereo
    // presentation transport for every AA backend. Temporal work remains
    // backend-specific, but scene/HUD separation and completed-pair camera
    // authority must not disappear merely because NGX is not selected.
    return g_config.openxr_mode == kOpenXrModeStereo;
}

bool mode3_aer_presentation_active() {
    return mode3_stereo_transport_active() &&
        g_config.mode3_aer_presentation;
}

bool mode3_aer_sequential_retained_hud_configured() {
    const bool supported_backend =
        g_config.temporal_backend == TemporalBackend::None ||
        g_config.temporal_backend == TemporalBackend::Taau ||
        g_config.temporal_backend == TemporalBackend::Dlss;
    return mode3_aer_presentation_active() && supported_backend;
}

bool puredark_afw_mode3_aer_taau_route_configured() {
    // [FEATURE:PUREDARK-AFW-MODE3-TAAU V12055 1/8] TAAU exposes the exact
    // Depth, motion-vector and CB10 identity on one native resolve command
    // list. Keep this producer route independent from the No-AA resource
    // discovery trial and from the legacy AER/DLSS integration.
    return g_config.openxr_enabled && g_config.puredark_afw_enabled &&
        mode3_aer_presentation_active() &&
        g_config.temporal_backend == TemporalBackend::Taau &&
        g_config.hmd_freelook &&
        std::fabs(g_config.engine_factory_stereo_offset) > 0.00001f;
}

bool puredark_afw_mode3_aer_dlss_route_configured() {
    // [FEATURE:PUREDARK-AFW-MODE3-DLSS-POSITIVE-CONTROL V12061 1/8]
    // Port the validated V12016 AER producer contract without routing
    // DLSS through the native No-AA/TAAU discovery path. NGX supplies the
    // exact Depth/MVec/camera bundle and OpenXR records the generated peer.
    // V1158 keeps this exact producer contract for both projections. The
    // V1222 gives both projections the same post-render contract: the exact
    // NGX output is copied into the immutable bundle on its producer list.
    // Symmetric/asymmetric differences therefore end before this transport.
    return g_config.openxr_enabled && g_config.puredark_afw_enabled &&
        mode3_aer_presentation_active() &&
        g_config.temporal_backend == TemporalBackend::Dlss &&
        g_config.hmd_freelook &&
        std::fabs(g_config.engine_factory_stereo_offset) > 0.00001f;
}

bool puredark_afw_mode3_aer_common_transport_configured() {
    // [REFACTOR:PUREDARK-AFW-COMMON-TRANSPORT V12104 2/8] Producers are
    // backend-specific; command-list publication, the immutable FIFO,
    // cross-queue ordering, one-Present selection, Evaluate and OpenXR
    // publication are not. No AA has no validated producer and stays out.
    return puredark_afw_mode3_aer_dlss_route_configured() ||
        puredark_afw_mode3_aer_taau_route_configured();
}

bool puredark_afw_mode3_aer_natural_clock_configured() {
    // [FIX:PUREDARK-AFW-MODE3-TAAU-NATURAL-CLOCK V12122 1/4] The producer
    // clock is a property of Mode-3 AER + AFW, not of NGX. TAAU can also
    // record fewer or more auxiliary factories than DXGI Presents under load;
    // advance its identity only at the same canonical gameplay builder that
    // already gives DLSS strict natural-eye alternation.
    return puredark_afw_mode3_aer_common_transport_configured();
}

bool puredark_afw_mode3_aer_any_route_configured() {
    return puredark_afw_mode3_aer_common_transport_configured();
}

bool rt_per_eye_temporal_history_active() {
    // [REFACTOR:COMMON-TEMPORAL-AFW-TRANSACTION V1226 1/8] RTX is upstream
    // of the temporal backend. Its eye-indexed AO, shadow and reflection
    // histories therefore use the same natural render identity for DLSS and
    // TAAU; only the downstream temporal adapter differs.
    const bool supported_temporal_backend =
        g_config.temporal_backend == TemporalBackend::Dlss ||
        g_config.temporal_backend == TemporalBackend::Taau;
    return g_config.raytracing_enabled && g_config.openxr_enabled &&
        mode3_aer_presentation_active() &&
        supported_temporal_backend && g_config.hmd_freelook;
}

// Keep the historical symbol local while the surrounding hook names are
// retired incrementally; its policy is now backend-independent.
bool rt_symmetric_dlss_per_eye_ao_history_active() {
    return rt_per_eye_temporal_history_active();
}

bool rt_temporal_history_descriptor_format(DXGI_FORMAT format) {
    // [FIX:RT-RELEASE-METADATA-OWNERSHIP V1175 1/8] AO, SIGMA and REBLUR
    // resolve their stable public history inputs through descriptor metadata.
    // Keep the release route narrow: these are exactly the five typed formats
    // accepted later by the three private-history allocators.
    switch (format) {
    case DXGI_FORMAT_R32_UINT:
    case DXGI_FORMAT_R16_FLOAT:
    case DXGI_FORMAT_R32_FLOAT:
    case DXGI_FORMAT_R8_UNORM:
    case DXGI_FORMAT_R16G16B16A16_FLOAT:
        return true;
    default:
        return false;
    }
}

bool mode3_aer_final_present_source_active() {
    // [FIX:UNIFIED-MODE3-TRANSPORT V1234 2/6] AER's final post-processed
    // backbuffer cache is the common No-AA/DLSS presentation source. Camera,
    // FOV and shader preparation may differ before rendering; cache selection
    // and publication may not differ by projection afterwards.
    const auto backend = g_config.temporal_backend == TemporalBackend::Dlss
        ? w3vr::mode3_transport::TemporalAdapter::Dlss
        : (g_config.temporal_backend == TemporalBackend::Taau
            ? w3vr::mode3_transport::TemporalAdapter::Taau
            : w3vr::mode3_transport::TemporalAdapter::None);
    return w3vr::mode3_transport::final_backbuffer_route_active(
        mode3_aer_presentation_active(), backend);
}

bool puredark_afw_mode3_aer_dlss_final_source_active() {
    // [FIX:UNIFIED-MODE3-TRANSPORT V1234 3/6] AFW consumes the same final
    // post-processed DLSS transaction for both projections.
    return puredark_afw_mode3_aer_dlss_route_configured() &&
        mode3_aer_final_present_source_active();
}

bool retained_hud_projection_route_active() {
    // [FIX:STRICT-STEREO-GAMEPLAY-RETAINED-HUD V1495 2/3] Strict Stereo uses
    // one retained owner after bootstrap in gameplay and cutscenes. V1494's
    // accepted-predecessor join supplies the exact eye/pair identity.
    return (mode3_stereo_transport_active() &&
            !mode3_aer_final_present_source_active() &&
            !mode3_aer_afw_baked_hud_cinema_active()) ||
        mode3_aer_afw_post_hud_gameplay_active() ||
        mode3_aer_sequential_full_vr_retained_hud_active();
}

bool retained_hud_projection_route_configured() {
    return (mode3_stereo_transport_active() &&
            !mode3_aer_final_present_source_active()) ||
        puredark_afw_mode3_aer_common_transport_configured() ||
        mode3_aer_sequential_retained_hud_configured();
}

bool mode3_submitted_hud_join_route_configured() {
    const auto backend = temporal_backend_is_dlss()
        ? w3vr::mode3_transport::TemporalAdapter::Dlss
        : (temporal_backend_is_taau()
            ? w3vr::mode3_transport::TemporalAdapter::Taau
            : w3vr::mode3_transport::TemporalAdapter::None);
    return w3vr::mode3_transport::submitted_hud_join_route_active(
        mode3_stereo_transport_active(),
        mode3_aer_presentation_active(),
        puredark_afw_mode3_aer_common_transport_configured() ||
            mode3_aer_sequential_retained_hud_configured(),
        backend);
}

bool mode3_strict_stereo_submitted_hud_join_active() {
    return mode3_submitted_hud_join_route_configured() &&
        !mode3_aer_presentation_active() &&
        retained_hud_projection_route_active();
}

bool mode3_aer_submitted_hud_join_active() {
    return mode3_aer_presentation_active() &&
        (mode3_aer_afw_post_hud_gameplay_active() ||
            mode3_aer_sequential_full_vr_retained_hud_active());
}

bool mode3_taau_afw_final_source_active() {
    // [FIX:PUREDARK-AFW-TAAU-FINAL-SOURCE V12114 1/9] Keep the exact TAAU
    // producer bundle, but join it directly to the final post-processed DXGI
    // backbuffer. This is the validated sequential-source contract used by
    // AER TAAU and V13043 DLSS; the scene-only packed capture is not a
    // presentation or AFW color authority on this isolated route.
    return puredark_afw_mode3_aer_taau_route_configured() &&
        g_config.openxr_mode == 3 &&
        g_config.mode3_aer_presentation;
}

bool taau_submitted_resolve_route_active() {
    return mode3_taau_afw_final_source_active();
}

enum class Mode3AfwTemporalBackend : uint8_t {
    None,
    Dlss,
    Taau,
};

Mode3AfwTemporalBackend mode3_afw_exact_final_source_backend() {
    // [REFACTOR:COMMON-TEMPORAL-AFW-TRANSACTION V1226 2/8] From the exact
    // temporal producer tag onward, DLSS and TAAU enter one final-color join.
    // Backend-specific capture and motion normalization have already finished.
    const auto backend = w3vr::mode3_transport::exact_afw_backend(
        puredark_afw_mode3_aer_dlss_final_source_active(),
        mode3_taau_afw_final_source_active());
    return backend == w3vr::mode3_transport::TemporalAdapter::Dlss
        ? Mode3AfwTemporalBackend::Dlss
        : (backend == w3vr::mode3_transport::TemporalAdapter::Taau
            ? Mode3AfwTemporalBackend::Taau
            : Mode3AfwTemporalBackend::None);
}

bool mode3_afw_exact_final_source_active() {
    return mode3_afw_exact_final_source_backend() !=
        Mode3AfwTemporalBackend::None;
}

Mode3AfwTemporalBackend mode3_final_color_submission_backend() {
    const auto backend =
        w3vr::mode3_transport::final_color_submission_backend(
            dlss_submitted_cache_route_active(),
            mode3_taau_afw_final_source_active());
    return backend == w3vr::mode3_transport::TemporalAdapter::Dlss
        ? Mode3AfwTemporalBackend::Dlss
        : (backend == w3vr::mode3_transport::TemporalAdapter::Taau
            ? Mode3AfwTemporalBackend::Taau
            : Mode3AfwTemporalBackend::None);
}

bool taau_stereo_route_active() {
    // [FIX:AER-TAAU-SUBMITTED-RESOLVE-AUTHORITY V12023 2/9] AER has the
    // same per-eye temporal-history requirement as the same-tick transports.
    // Its late identity is recovered from the resolve's own CB10 matrix below.
    return temporal_backend_is_taau() &&
        g_config.openxr_mode == 3;
}

bool taau_drop_diagnostics_active() {
    return g_config.taau_drop_diagnostics &&
        taau_stereo_route_active();
}

bool reverse_diagnostic_hooks_requested() {
    // Diagnostic Logging is the sole master for legacy reverse hooks. This
    // prevents stale per-probe INI values from changing renderer timing in a
    // normal run. Functional renderer hooks have dedicated predicates.
    return g_config.runtime_diagnostics;
}

bool native_asymmetric_noaa_route_active();
bool automatic_focus_projection_route_configured();
bool native_asymmetric_transparent_center_route_active();

// Prepare only the descriptor and graphics-binding state needed by the
// supported Mode-3 family. The GPU intervention remains ASYM-only, so SYM and
// every non-Mode-3 route are rendering-identical to V1443.
bool witcher_sense_history_suppression_route_configured() {
    return g_config.openxr_enabled &&
        g_config.openxr_mode == 3 &&
        (g_config.temporal_backend == TemporalBackend::None ||
            g_config.temporal_backend == TemporalBackend::Taau ||
            g_config.temporal_backend == TemporalBackend::Dlss) &&
        g_config.hmd_freelook;
}

bool witcher_sense_history_suppression_route_active() {
    return witcher_sense_history_suppression_route_configured() &&
        native_asymmetric_transparent_center_route_active();
}

// The tiled-light correction is release behavior for the validated native
// asymmetric No-AA route. It is deliberately independent of diagnostics.
bool asymmetric_tiled_culling_fix_needed() {
    return native_asymmetric_noaa_route_active();
}

// [FIX:ASYMMETRIC-FOCUS-FUNCTIONAL-METADATA V1081 1/5] Reading the global
// b12 projection is functional renderer state for automatic focus correction.
// It must not disappear when launcher diagnostics are disabled.
bool focus_projection_metadata_hooks_needed() {
    return automatic_focus_projection_route_configured();
}

bool focus_projection_shader_registry_enabled() {
    return g_config.runtime_diagnostics &&
        (g_config.focus_projection_shader_registry ||
            g_config.logging_enabled);
}

// [FIX:REAL-SMOKE-RELEASE-ROUTE V1070] The V1065-V1069 center correction is
// rendering behavior, not a diagnostic probe. Keep the minimal CBV/upload
// metadata authority alive for the native asymmetric route even when the
// launcher disables Diagnostic Logging. V1124 extends this authority to TAAU;
// V1136 adds only sequential Stereo DLSS and still excludes Packed DLSS.
bool real_smoke_center_fix_route_configured() {
    return g_config.openxr_enabled &&
        g_config.openxr_mode == 3 &&
        (g_config.temporal_backend == TemporalBackend::None ||
            g_config.temporal_backend == TemporalBackend::Taau ||
            g_config.temporal_backend == TemporalBackend::Dlss) &&
        g_config.hmd_freelook;
}

bool real_smoke_world_up_route_active() {
    return g_config.openxr_enabled &&
        supported_projection_transport_active() &&
        g_config.hmd_freelook;
}

bool foliage_bound_basis_route_active() {
    return w3vr::foliage_native_snapshot::route_active(
        g_config.openxr_enabled, g_config.hmd_freelook);
}

bool real_smoke_world_up_binding_route_active() {
    // [FIX:WORLD-UP-BINDING-CENTER-SPLIT V1156 1/3] The V1080 world-up
    // replacement consumes heap/root-table/CBV state independently from the
    // older V1065 off-axis centering correction. Keep that state for every
    // supported sequential Mode-3 backend, including symmetric No AA where
    // the optical-centre selector may be inactive. Packed DLSS
    // remains excluded exactly as in the historical smoke route.
    return real_smoke_world_up_route_active() &&
        (g_config.temporal_backend == TemporalBackend::None ||
            g_config.temporal_backend == TemporalBackend::Taau ||
            g_config.temporal_backend == TemporalBackend::Dlss);
}

bool taau_functional_hooks_needed() {
    // Functional metadata and compute interception follows the selected TAAU
    // backend directly. DLSS and No AA never inherit this route.
    return temporal_backend_is_taau();
}

bool taau_metadata_hooks_needed() {
    return taau_functional_hooks_needed() ||
        reverse_diagnostic_hooks_requested();
}

bool mode3_hud_descriptor_hooks_needed() {
    // The retained projection HUD resolves REDengine's native t1 SRV from the
    // graphics binding snapshot. This descriptor metadata is functional HUD
    // state, not TAAU/reverse diagnostic state.
    return retained_hud_projection_route_configured();
}

bool native_temporal_terrain_motion_route_active();

bool descriptor_metadata_hooks_needed() {
    return taau_metadata_hooks_needed() ||
        mode3_hud_descriptor_hooks_needed() ||
        real_smoke_world_up_binding_route_active() ||
        foliage_bound_basis_route_active() ||
        focus_projection_metadata_hooks_needed() ||
        asymmetric_tiled_culling_fix_needed() ||
        native_temporal_terrain_motion_route_active() ||
        rt_symmetric_dlss_per_eye_ao_history_active();
}

bool graphics_binding_hooks_needed() {
    return temporal_backend_is_dlss() || taau_metadata_hooks_needed() ||
        witcher_sense_history_suppression_route_configured() ||
        mode3_hud_descriptor_hooks_needed() ||
        real_smoke_world_up_binding_route_active() ||
        foliage_bound_basis_route_active() ||
        asymmetric_tiled_culling_fix_needed();
}

bool temporal_compute_hooks_needed() {
    // DLSS keeps only its dedicated compute-PSO identification. The TAAU
    // command-list interception is selected separately below.
    return temporal_backend_is_dlss() || taau_metadata_hooks_needed() ||
        asymmetric_tiled_culling_fix_needed() ||
        rt_symmetric_dlss_per_eye_ao_history_active();
}

bool taau_compute_hooks_needed() {
    return taau_functional_hooks_needed() ||
        reverse_diagnostic_hooks_requested() ||
        asymmetric_tiled_culling_fix_needed();
}

bool common_renderer_pipeline_hooks_needed() {
    return supported_projection_transport_active();
}

bool renderer_hook_installation_needed() {
    return common_renderer_pipeline_hooks_needed() ||
        witcher_sense_history_suppression_route_configured() ||
        descriptor_metadata_hooks_needed() || graphics_binding_hooks_needed() ||
        temporal_compute_hooks_needed();
}

const char* temporal_backend_name() {
    switch (g_config.temporal_backend) {
    case TemporalBackend::Taau:
        return "taau";
    case TemporalBackend::Dlss:
        return "dlss";
    default:
        return "none";
    }
}

