bool native_asymmetric_noaa_route_active() {
    // [TRIAL:NATIVE-STEREO-DLSS V1136] Reuse the validated native-asymmetric
    // geometry ledger with sequential Stereo DLSS. Packed DLSS remains a
    // separate atlas/replay renderer and is deliberately excluded.
    return kNativeAsymmetricNoAaTrialBuild &&
        native_stereo_runtime_enabled() &&
        g_config.openxr_mode == 3 &&
        (g_config.temporal_backend == TemporalBackend::None ||
            g_config.temporal_backend == TemporalBackend::Taau ||
            g_config.temporal_backend == TemporalBackend::Dlss) &&
        g_config.hmd_freelook;
}

bool automatic_focus_projection_route_configured() {
    const bool supported_backend =
        g_config.temporal_backend == TemporalBackend::None ||
        g_config.temporal_backend == TemporalBackend::Taau ||
        g_config.temporal_backend == TemporalBackend::Dlss;
    return w3vr::mode3_transport::
        native_asymmetric_effect_preparation_configured(
            kNativeAsymmetricNoAaTrialBuild,
            g_config.openxr_mode == 3,
            supported_backend,
            g_config.hmd_freelook);
}

// [FIX:CINEMA-EFFECT-CENTER-GUARD V1135] A normal Cinema presentation renders
// a symmetric stereo camera into an anchored panel.  The native asymmetric
// center correction belongs only to headset projection; applying it to that
// panel makes automatic fire/smoke jump when mouse rotation changes the scene
// camera.  Manual F10 Cinema is always a panel, while automatic Full VR keeps
// the asymmetric correction.
bool native_asymmetric_cinema_panel_active() {
    return g_force_mono_cinema.load(std::memory_order_relaxed) ||
        (g_cinema_mode_active.load(std::memory_order_relaxed) &&
            !g_config.cinema_full_vr);
}

