bool native_asymmetric_transparent_center_route_active() {
    const bool full_vr_scene = native_asymmetric_full_vr_scene_active();
    // [FIX:FULL-VR-TRANSPARENT-FIX-ADMISSION V1484 2/3] V1199 suppressed the
    // whole Full-VR lifecycle. Preserve its centered-fallback protection, but
    // allow the established fix for a frame-local proven native-ASym source.
    return w3vr::mode3_transport::
        native_asymmetric_effect_center_application_active(
            automatic_focus_projection_route_configured(),
            native_stereo_runtime_enabled(),
            native_asymmetric_cinema_panel_active(),
            full_vr_scene,
            native_asymmetric_full_vr_effect_source_active());
}

NativeAsymmetricPairSlot* native_asymmetric_pair_slot(uint64_t pair_id) {
    if (pair_id == 0 || pair_id == UINT64_MAX) {
        return nullptr;
    }
    auto& slot = g_native_asymmetric_pair_slots[
        pair_id % kNativeAsymmetricPairSlotCount];
    return slot.pair_id.load(std::memory_order_acquire) == pair_id
        ? &slot
        : nullptr;
}

bool initialize_native_asymmetric_pair(uint64_t pair_id) {
    if (!native_asymmetric_noaa_route_active() ||
        !g_native_asymmetric_noaa_writer_seen.load(
            std::memory_order_acquire) ||
        !g_native_asymmetric_transport_ready.load(
            std::memory_order_acquire) ||
        !g_hmd_pose_valid.load(std::memory_order_acquire) ||
        g_xr_views.size() < 2 || pair_id == 0 || pair_id == UINT64_MAX) {
        return false;
    }
    // [TRIAL:STANDARD-PRODUCER-FOV-RESCALE V23038 2/5] Freeze the exact FOV
    // rendered by the native producer. Presentation Size scales its tangent
    // interval here so temporal, DLSS and AFW metadata follow the same camera.
    std::array<XrFovf, 2> producer_fovs{};
    const float presentation_scale = presentation_producer_scale();
    for (uint32_t eye = 0; eye < 2; ++eye) {
        w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor descriptor{};
        producer_fovs[eye] = g_xr_views[eye].fov;
        if (presentation_scale < 1.0f &&
            !w3vr::openxr_eye_geometry::scale_asymmetric_projection_fov(
                producer_fovs[eye], presentation_scale,
                producer_fovs[eye])) {
            return false;
        }
        if (!w3vr::openxr_eye_geometry::
                derive_asymmetric_projection_descriptor(
                    producer_fovs[eye], 1, 1, descriptor)) {
            return false;
        }
    }
    std::scoped_lock slot_lock{g_native_asymmetric_pair_slot_mutex};
    auto& slot = g_native_asymmetric_pair_slots[
        pair_id % kNativeAsymmetricPairSlotCount];
    slot.pair_id.store(UINT64_MAX, std::memory_order_release);
    slot.generation.store(
        g_streamline_capture_generation.load(std::memory_order_acquire),
        std::memory_order_relaxed);
    slot.factory_mask.store(0, std::memory_order_relaxed);
    slot.temporal_mask.store(0, std::memory_order_relaxed);
    slot.dlss_input_mask.store(0, std::memory_order_relaxed);
    slot.fov[0] = producer_fovs[0];
    slot.fov[1] = producer_fovs[1];
    slot.pair_id.store(pair_id, std::memory_order_release);
    return true;
}

bool snapshot_native_asymmetric_pair_fov(
    uint64_t pair_id,
    uint32_t eye,
    XrFovf& fov) {
    if (eye > 1 || pair_id == 0 || pair_id == UINT64_MAX) {
        return false;
    }
    std::scoped_lock slot_lock{g_native_asymmetric_pair_slot_mutex};
    auto& slot = g_native_asymmetric_pair_slots[
        pair_id % kNativeAsymmetricPairSlotCount];
    if (slot.pair_id.load(std::memory_order_acquire) != pair_id) {
        return false;
    }
    fov = slot.fov[eye];
    return slot.pair_id.load(std::memory_order_acquire) == pair_id;
}

bool native_asymmetric_source_eye_tagged(uint64_t pair_id, uint32_t eye) {
    if (eye > 1) {
        return false;
    }
    auto* slot = native_asymmetric_pair_slot(pair_id);
    if (slot == nullptr) {
        return false;
    }
    const uint8_t eye_bit = static_cast<uint8_t>(1u << eye);
    const bool tagged = (slot->factory_mask.load(
        std::memory_order_acquire) & eye_bit) != 0;
    return tagged && slot->pair_id.load(
        std::memory_order_acquire) == pair_id;
}

bool snapshot_shared_mode3_projection_fov(XrFovf& fov) {
    if (!g_hmd_render_fov_valid.load(std::memory_order_acquire)) {
        return false;
    }
    fov = {
        g_hmd_render_fov_left.load(std::memory_order_acquire),
        g_hmd_render_fov_right.load(std::memory_order_acquire),
        g_hmd_render_fov_up.load(std::memory_order_acquire),
        g_hmd_render_fov_down.load(std::memory_order_acquire)};
    w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor descriptor{};
    return w3vr::openxr_eye_geometry::derive_asymmetric_projection_descriptor(
        fov, 1, 1, descriptor);
}

// [FIX:OPENING-CUTSCENE-ASYM-FALLBACK-FOV V1418 1/2] Keep one publication
// owner for the centered projection actually rendered into a shared Mode-3
// source. The final asymmetric OpenXR submit uses this exact envelope to
// derive its reciprocal per-eye subimages.
bool publish_shared_mode3_projection_fov(
    float horizontal_span,
    float vertical_fov) {
    if (!std::isfinite(horizontal_span) ||
        !std::isfinite(vertical_fov) ||
        horizontal_span <= 0.1f || vertical_fov <= 0.1f) {
        return false;
    }
    const float horizontal_half = atanf(horizontal_span * 0.5f);
    const float vertical_half = vertical_fov * 0.5f;
    g_hmd_render_fov_left.store(-horizontal_half);
    g_hmd_render_fov_right.store(horizontal_half);
    g_hmd_render_fov_up.store(vertical_half);
    g_hmd_render_fov_down.store(-vertical_half);
    g_hmd_render_fov_valid.store(true);
    return true;
}

w3vr::mode3_transport::AfwPixelProjection
completed_engine_frame_pixel_projection(uint64_t pair_id, uint32_t eye) {
    using Projection = w3vr::mode3_transport::AfwPixelProjection;
    if (eye > 1 || pair_id == 0 || pair_id == UINT64_MAX) {
        return Projection::Invalid;
    }
    if (native_asymmetric_source_eye_tagged(pair_id, eye)) {
        return Projection::NativeAsymmetric;
    }
    if (!native_stereo_runtime_enabled()) {
        return Projection::SharedSymmetric;
    }
    // A current slot with no source-eye factory bit means the native rebuild
    // was attempted but did not survive verification. Never reinterpret those
    // pixels as SYM. No slot means the producer deliberately used its centered
    // bootstrap/Full-VR fallback and is genuinely shared.
    return native_asymmetric_pair_slot(pair_id) != nullptr
        ? Projection::Invalid
        : Projection::SharedSymmetric;
}

bool resolve_mode3_afw_pixel_projection(
    uint64_t pair_id,
    uint32_t generation,
    uint32_t source_eye,
    w3vr::mode3_transport::AfwPixelProjection actual_producer,
    const XrFovf& shared_fov,
    Mode3AfwPixelProjectionAuthority& authority) {
    authority = {};
    const uint32_t current_generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    const bool exact_identity_valid = source_eye <= 1 && pair_id != 0 &&
        pair_id != UINT64_MAX;

    bool pair_slot_valid{};
    uint32_t pair_generation{UINT32_MAX};
    uint8_t factory_mask{};
    std::array<XrFovf, 2> frozen_fovs{};
    {
        // Pair FOVs are immutable after pair_id is release-published. Keep the
        // lock while copying so ring reuse cannot splice two producer pairs.
        std::scoped_lock slot_lock{g_native_asymmetric_pair_slot_mutex};
        auto& slot = g_native_asymmetric_pair_slots[
            exact_identity_valid
                ? pair_id % kNativeAsymmetricPairSlotCount
                : 0];
        pair_slot_valid = exact_identity_valid &&
            slot.pair_id.load(std::memory_order_acquire) == pair_id;
        if (pair_slot_valid) {
            pair_generation = slot.generation.load(
                std::memory_order_acquire);
            factory_mask = slot.factory_mask.load(
                std::memory_order_acquire);
            frozen_fovs[0] = slot.fov[0];
            frozen_fovs[1] = slot.fov[1];
            pair_slot_valid =
                slot.pair_id.load(std::memory_order_acquire) == pair_id;
        }
    }

    const auto valid_fov = [](const XrFovf& candidate) {
        w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor descriptor{};
        return w3vr::openxr_eye_geometry::
            derive_asymmetric_projection_descriptor(
                candidate, 1, 1, descriptor);
    };
    const bool frozen_pair_fovs_valid = pair_slot_valid &&
        valid_fov(frozen_fovs[0]) && valid_fov(frozen_fovs[1]);
    const bool shared_fov_valid = valid_fov(shared_fov);
    const auto encoding =
        w3vr::mode3_transport::decide_afw_pixel_projection(
            actual_producer, exact_identity_valid, generation,
            current_generation, pair_slot_valid, pair_generation,
            factory_mask, source_eye, frozen_pair_fovs_valid,
            shared_fov_valid);
    if (encoding ==
        w3vr::mode3_transport::AfwPixelProjection::Invalid) {
        return false;
    }
    authority.encoding = encoding;
    authority.fovs = encoding ==
            w3vr::mode3_transport::AfwPixelProjection::NativeAsymmetric
        ? frozen_fovs
        : std::array<XrFovf, 2>{shared_fov, shared_fov};
    return true;
}

void reset_native_asymmetric_noaa_state() {
    g_native_asymmetric_noaa_writer_seen.store(
        false, std::memory_order_release);
    g_native_asymmetric_transport_ready.store(
        false, std::memory_order_release);
    {
        std::scoped_lock lock{g_native_asymmetric_writer_warmup_mutex};
        g_native_asymmetric_writer_warmup_pair = UINT64_MAX;
        g_native_asymmetric_writer_warmup_mask = 0;
    }
    {
        std::scoped_lock slot_lock{g_native_asymmetric_pair_slot_mutex};
        for (auto& slot : g_native_asymmetric_pair_slots) {
            slot.pair_id.store(UINT64_MAX, std::memory_order_release);
            slot.generation.store(UINT32_MAX, std::memory_order_relaxed);
            slot.factory_mask.store(0, std::memory_order_relaxed);
            slot.temporal_mask.store(0, std::memory_order_relaxed);
            slot.dlss_input_mask.store(0, std::memory_order_relaxed);
        }
    }
}
