struct DescriptorHeapInfo {
    D3D12_DESCRIPTOR_HEAP_TYPE type{};
    UINT num_descriptors{};
    UINT increment{};
    D3D12_CPU_DESCRIPTOR_HANDLE cpu_start{};
    D3D12_GPU_DESCRIPTOR_HANDLE gpu_start{};
    bool shader_visible{};
};

struct CbvDescriptorInfo {
    D3D12_GPU_VIRTUAL_ADDRESS gpu_va{};
    UINT size_in_bytes{};
};

constexpr size_t kCbvDescriptorShardCount = 64;
constexpr size_t kCbvDescriptorSlotCount = 1u << 20;
constexpr size_t kCbvDescriptorProbeCount = 64;
constexpr SIZE_T kCbvDescriptorClaimed = ~SIZE_T{};

struct CbvDescriptorSlot {
    std::atomic<SIZE_T> key{};
    std::atomic<uint64_t> gpu_va{};
    std::atomic<uint32_t> size_in_bytes{};
};

struct CbvDescriptorShard {
    std::mutex mutex{};
    std::unordered_map<SIZE_T, CbvDescriptorInfo> descriptors{};
};

std::array<CbvDescriptorSlot, kCbvDescriptorSlotCount> g_cbv_descriptor_slots{};
std::array<CbvDescriptorShard, kCbvDescriptorShardCount> g_cbv_descriptor_shards{};

size_t cbv_descriptor_slot_index(SIZE_T cpu_handle) {
    // Separate descriptor heaps often reuse the same low address pattern,
    // which overflowed the 64-slot lock-free probe run in an
    // initialization-order-dependent way. Smoke draws cannot wait on the
    // collision map, so hash the complete immutable CPU handle.
    return w3vr::cbv_descriptor_cache::
        slot_index<kCbvDescriptorSlotCount>(cpu_handle);
}

CbvDescriptorShard& cbv_descriptor_shard(SIZE_T cpu_handle) {
    return g_cbv_descriptor_shards[(cpu_handle >> 5) & (kCbvDescriptorShardCount - 1)];
}

void store_cbv_descriptor_fallback(SIZE_T cpu_handle, const CbvDescriptorInfo& info) {
    auto& shard = cbv_descriptor_shard(cpu_handle);
    std::scoped_lock lock{shard.mutex};
    shard.descriptors[cpu_handle] = info;
}

bool load_cbv_descriptor_fallback(SIZE_T cpu_handle, CbvDescriptorInfo& info) {
    auto& shard = cbv_descriptor_shard(cpu_handle);
    std::scoped_lock lock{shard.mutex};
    const auto it = shard.descriptors.find(cpu_handle);
    if (it == shard.descriptors.end()) {
        return false;
    }
    info = it->second;
    return true;
}

void store_cbv_descriptor(SIZE_T cpu_handle, const CbvDescriptorInfo& info) {
    const auto base = cbv_descriptor_slot_index(cpu_handle);
    for (size_t probe = 0; probe < kCbvDescriptorProbeCount; ++probe) {
        auto& slot = g_cbv_descriptor_slots[(base + probe) & (kCbvDescriptorSlotCount - 1)];
        auto key = slot.key.load(std::memory_order_acquire);
        if (key == 0) {
            SIZE_T expected{};
            if (slot.key.compare_exchange_strong(
                    expected, kCbvDescriptorClaimed, std::memory_order_acq_rel)) {
                slot.gpu_va.store(info.gpu_va, std::memory_order_relaxed);
                slot.size_in_bytes.store(info.size_in_bytes, std::memory_order_relaxed);
                slot.key.store(cpu_handle, std::memory_order_release);
                return;
            }
            key = expected;
        }
        if (key == kCbvDescriptorClaimed) {
            YieldProcessor();
            --probe;
            continue;
        }
        if (key != cpu_handle) {
            continue;
        }

        // REDengine rewrites the same descriptor from multiple render workers.
        // CBV size is stable for that slot, so publish it before the address and
        // let the newest address win without serializing all of those workers.
        slot.size_in_bytes.store(info.size_in_bytes, std::memory_order_relaxed);
        slot.gpu_va.store(info.gpu_va, std::memory_order_release);
        return;
    }
    store_cbv_descriptor_fallback(cpu_handle, info);
}

bool load_cbv_descriptor(SIZE_T cpu_handle, CbvDescriptorInfo& info) {
    const auto base = cbv_descriptor_slot_index(cpu_handle);
    for (size_t probe = 0; probe < kCbvDescriptorProbeCount; ++probe) {
        auto& slot = g_cbv_descriptor_slots[(base + probe) & (kCbvDescriptorSlotCount - 1)];
        const auto key = slot.key.load(std::memory_order_acquire);
        if (key == 0) {
            return load_cbv_descriptor_fallback(cpu_handle, info);
        }
        if (key == kCbvDescriptorClaimed) {
            YieldProcessor();
            --probe;
            continue;
        }
        if (key != cpu_handle) {
            continue;
        }

        const auto gpu_va = slot.gpu_va.load(std::memory_order_acquire);
        const auto size = slot.size_in_bytes.load(std::memory_order_relaxed);
        info = CbvDescriptorInfo{gpu_va, size};
        return true;
    }
    return load_cbv_descriptor_fallback(cpu_handle, info);
}

bool load_cbv_descriptor_smoke_nonblocking(
    SIZE_T cpu_handle, CbvDescriptorInfo& info) {
    const auto base = cbv_descriptor_slot_index(cpu_handle);
    for (size_t probe = 0; probe < kCbvDescriptorProbeCount; ++probe) {
        auto& slot = g_cbv_descriptor_slots[
            (base + probe) & (kCbvDescriptorSlotCount - 1)];
        const auto key = slot.key.load(std::memory_order_acquire);
        if (key == 0 || key == kCbvDescriptorClaimed) {
            return false;
        }
        if (key != cpu_handle) {
            continue;
        }
        info.gpu_va = slot.gpu_va.load(std::memory_order_acquire);
        info.size_in_bytes = slot.size_in_bytes.load(
            std::memory_order_relaxed);
        return info.gpu_va != 0;
    }
    return false;
}

struct ResourceDescriptorInfo {
    ID3D12Resource* resource{};
    D3D12_RESOURCE_DESC resource_desc{};
    D3D12_GPU_VIRTUAL_ADDRESS resource_gpu_va{};
    DXGI_FORMAT format{DXGI_FORMAT_UNKNOWN};
    D3D12_SRV_DIMENSION srv_dimension{D3D12_SRV_DIMENSION_UNKNOWN};
    UINT most_detailed_mip{};
    UINT mip_levels{};
    UINT first_array_slice{};
    UINT array_size{1};
    UINT64 first_element{};
    UINT num_elements{};
    UINT structure_byte_stride{};
    UINT buffer_flags{};
    bool buffer_view{};
    bool uav{};
};

// HUD SRV descriptors are rewritten by REDengine while command lists are being
// recorded. Keep a compact lock-free mirror so the final HUD draw never takes
// the global reverse-engineering mutex (V636 showed that hot-path locking can
// perturb the left DLSS history).
constexpr size_t kResourceDescriptorSlotCount = 1u << 18;
constexpr size_t kResourceDescriptorProbeCount = 64;
constexpr SIZE_T kResourceDescriptorClaimed = ~SIZE_T{};
struct ResourceDescriptorSlot {
    std::atomic<SIZE_T> key{};
    std::atomic<ID3D12Resource*> resource{};
    std::atomic<uint32_t> format{
        static_cast<uint32_t>(DXGI_FORMAT_UNKNOWN)};
};
std::array<ResourceDescriptorSlot, kResourceDescriptorSlotCount>
    g_resource_descriptor_slots{};

size_t resource_descriptor_slot_index(SIZE_T cpu_handle) {
    return static_cast<size_t>(cpu_handle >> 5) &
        (kResourceDescriptorSlotCount - 1);
}

void store_resource_descriptor_fast(
    SIZE_T cpu_handle,
    ID3D12Resource* resource,
    DXGI_FORMAT format) {
    if (cpu_handle == 0 || resource == nullptr) {
        return;
    }
    const auto base = resource_descriptor_slot_index(cpu_handle);
    for (size_t probe = 0; probe < kResourceDescriptorProbeCount; ++probe) {
        auto& slot = g_resource_descriptor_slots[
            (base + probe) & (kResourceDescriptorSlotCount - 1)];
        auto key = slot.key.load(std::memory_order_acquire);
        if (key == 0) {
            SIZE_T expected{};
            if (slot.key.compare_exchange_strong(
                    expected, kResourceDescriptorClaimed,
                    std::memory_order_acq_rel)) {
                slot.format.store(
                    static_cast<uint32_t>(format),
                    std::memory_order_relaxed);
                slot.resource.store(resource, std::memory_order_relaxed);
                slot.key.store(cpu_handle, std::memory_order_release);
                return;
            }
            key = expected;
        }
        if (key == kResourceDescriptorClaimed) {
            YieldProcessor();
            --probe;
            continue;
        }
        if (key != cpu_handle) {
            continue;
        }
        slot.format.store(
            static_cast<uint32_t>(format), std::memory_order_relaxed);
        slot.resource.store(resource, std::memory_order_release);
        return;
    }
}

bool load_resource_descriptor_fast(
    SIZE_T cpu_handle,
    ID3D12Resource*& resource_out,
    DXGI_FORMAT& format_out) {
    if (cpu_handle == 0) {
        return false;
    }
    const auto base = resource_descriptor_slot_index(cpu_handle);
    for (size_t probe = 0; probe < kResourceDescriptorProbeCount; ++probe) {
        auto& slot = g_resource_descriptor_slots[
            (base + probe) & (kResourceDescriptorSlotCount - 1)];
        const auto key = slot.key.load(std::memory_order_acquire);
        if (key == 0) {
            return false;
        }
        if (key == kResourceDescriptorClaimed) {
            YieldProcessor();
            --probe;
            continue;
        }
        if (key != cpu_handle) {
            continue;
        }
        resource_out = slot.resource.load(std::memory_order_acquire);
        format_out = static_cast<DXGI_FORMAT>(
            slot.format.load(std::memory_order_relaxed));
        return resource_out != nullptr;
    }
    return false;
}

// [PERF:WITCHER-SENSE-BOUNDED-DESCRIPTORS V1499 1/5] Keep only the three
// immutable inputs needed to admit the exact compositor. The old 65,536-slot,
// 32-probe registry retained every handle ever seen and made descriptor-copy
// cost grow throughout a run. This four-way cache is bounded, overwrites old
// generations, and never enters the generic descriptor mutex/map.
enum class WitcherSenseDescriptorKind : uint32_t {
    None,
    Scene,
    History,
    Auxiliary,
};

struct WitcherSenseDescriptorInfo {
    ID3D12Resource* resource{};
    UINT64 width{};
    UINT height{};
    WitcherSenseDescriptorKind kind{WitcherSenseDescriptorKind::None};
};

constexpr size_t kWitcherSenseDescriptorSetCount = 1u << 14;
constexpr size_t kWitcherSenseDescriptorWays = 6;
constexpr size_t kWitcherSenseHistoryWays = 2;
constexpr size_t kWitcherSenseSignatureWays =
    kWitcherSenseDescriptorWays - kWitcherSenseHistoryWays;
struct WitcherSenseDescriptorSlot {
    std::atomic<uint64_t> sequence{};
    std::atomic<SIZE_T> key{};
    std::atomic<ID3D12Resource*> resource{};
    std::atomic<UINT64> width{};
    std::atomic<UINT> height{};
    std::atomic<uint32_t> kind{};
};
struct WitcherSenseDescriptorSet {
    std::atomic_flag writer = ATOMIC_FLAG_INIT;
    uint32_t next_history_victim{};
    uint32_t next_signature_victim{};
    std::array<WitcherSenseDescriptorSlot,
        kWitcherSenseDescriptorWays> slots{};
};
std::array<WitcherSenseDescriptorSet,
    kWitcherSenseDescriptorSetCount> g_witcher_sense_descriptor_cache{};

WitcherSenseDescriptorKind classify_witcher_sense_descriptor(
    const D3D12_RESOURCE_DESC& resource_desc,
    DXGI_FORMAT view_format,
    D3D12_SRV_DIMENSION view_dimension) {
    if (resource_desc.Dimension != D3D12_RESOURCE_DIMENSION_TEXTURE2D ||
        resource_desc.DepthOrArraySize != 1 || resource_desc.MipLevels != 1 ||
        resource_desc.SampleDesc.Count != 1 ||
        (view_dimension != D3D12_SRV_DIMENSION_UNKNOWN &&
            view_dimension != D3D12_SRV_DIMENSION_TEXTURE2D)) {
        return WitcherSenseDescriptorKind::None;
    }
    if (view_format == DXGI_FORMAT_UNKNOWN) {
        view_format = resource_desc.Format;
    }
    if (view_format != resource_desc.Format) {
        return WitcherSenseDescriptorKind::None;
    }
    if (resource_desc.Format == DXGI_FORMAT_R16G16B16A16_FLOAT) {
        return WitcherSenseDescriptorKind::Scene;
    }
    if (resource_desc.Format == DXGI_FORMAT_R16G16_FLOAT &&
        resource_desc.Width == 512 && resource_desc.Height == 512 &&
        (resource_desc.Flags &
            D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET) != 0) {
        return WitcherSenseDescriptorKind::History;
    }
    if (resource_desc.Format == DXGI_FORMAT_R11G11B10_FLOAT) {
        return WitcherSenseDescriptorKind::Auxiliary;
    }
    return WitcherSenseDescriptorKind::None;
}

size_t witcher_sense_descriptor_set_index(SIZE_T cpu_handle) {
    size_t hash = static_cast<size_t>(cpu_handle >> 5);
    hash ^= hash >> 10;
    return hash & (kWitcherSenseDescriptorSetCount - 1);
}

void lock_witcher_sense_descriptor_set(WitcherSenseDescriptorSet& set) {
    while (set.writer.test_and_set(std::memory_order_acquire)) {
        YieldProcessor();
    }
}

void write_witcher_sense_descriptor_slot(
    WitcherSenseDescriptorSlot& slot,
    SIZE_T cpu_handle,
    const WitcherSenseDescriptorInfo& info) {
    const uint64_t sequence =
        slot.sequence.fetch_add(1, std::memory_order_acq_rel);
    slot.key.store(cpu_handle, std::memory_order_relaxed);
    slot.resource.store(info.resource, std::memory_order_relaxed);
    slot.width.store(info.width, std::memory_order_relaxed);
    slot.height.store(info.height, std::memory_order_relaxed);
    slot.kind.store(static_cast<uint32_t>(info.kind),
        std::memory_order_relaxed);
    slot.sequence.store(sequence + 2, std::memory_order_release);
}

void store_witcher_sense_descriptor_target(
    SIZE_T cpu_handle,
    const WitcherSenseDescriptorInfo& info) {
    if (cpu_handle == 0 || info.resource == nullptr ||
        info.kind == WitcherSenseDescriptorKind::None) {
        return;
    }
    auto& set = g_witcher_sense_descriptor_cache[
        witcher_sense_descriptor_set_index(cpu_handle)];
    lock_witcher_sense_descriptor_set(set);
    // [PERF:WITCHER-SENSE-EXPANDED-PARTITION-CACHE V1501 1/3] V1500's two
    // signature ways made initial t0/t3 admission disappear in both TAAU and
    // DLSS. Distribute handles over 16 times as many sets and restore four
    // signature ways while keeping the alternating RG16F t2 pair isolated in
    // ways 0-1. Entries remain recyclable and lookup stays bounded.
    const bool history =
        info.kind == WitcherSenseDescriptorKind::History;
    const size_t first_way = history ? 0 : kWitcherSenseHistoryWays;
    const size_t way_count = history
        ? kWitcherSenseHistoryWays : kWitcherSenseSignatureWays;
    size_t selected = kWitcherSenseDescriptorWays;
    for (size_t way = 0; way < kWitcherSenseDescriptorWays; ++way) {
        const auto key = set.slots[way].key.load(std::memory_order_relaxed);
        if (key == cpu_handle) {
            if (way >= first_way && way < first_way + way_count) {
                selected = way;
            } else {
                write_witcher_sense_descriptor_slot(
                    set.slots[way], 0, {});
            }
        }
    }
    if (selected == kWitcherSenseDescriptorWays) {
        for (size_t offset = 0; offset < way_count; ++offset) {
            const size_t way = first_way + offset;
            if (set.slots[way].key.load(std::memory_order_relaxed) == 0) {
                selected = way;
                break;
            }
        }
    }
    if (selected == kWitcherSenseDescriptorWays) {
        auto& next_victim = history
            ? set.next_history_victim : set.next_signature_victim;
        selected = first_way + next_victim++ % way_count;
    }
    write_witcher_sense_descriptor_slot(
        set.slots[selected], cpu_handle, info);
    set.writer.clear(std::memory_order_release);
}

void invalidate_witcher_sense_descriptor_target(SIZE_T cpu_handle) {
    if (cpu_handle == 0) {
        return;
    }
    auto& set = g_witcher_sense_descriptor_cache[
        witcher_sense_descriptor_set_index(cpu_handle)];
    bool present = false;
    for (auto& slot : set.slots) {
        if (slot.key.load(std::memory_order_acquire) == cpu_handle) {
            present = true;
            break;
        }
    }
    if (!present) {
        return;
    }
    lock_witcher_sense_descriptor_set(set);
    for (auto& slot : set.slots) {
        if (slot.key.load(std::memory_order_relaxed) != cpu_handle) {
            continue;
        }
        write_witcher_sense_descriptor_slot(slot, 0, {});
        break;
    }
    set.writer.clear(std::memory_order_release);
}

bool load_witcher_sense_descriptor_target(
    SIZE_T cpu_handle,
    WitcherSenseDescriptorInfo& info_out,
    WitcherSenseDescriptorKind expected_kind =
        WitcherSenseDescriptorKind::None) {
    if (cpu_handle == 0) {
        return false;
    }
    auto& set = g_witcher_sense_descriptor_cache[
        witcher_sense_descriptor_set_index(cpu_handle)];
    const bool expected_history =
        expected_kind == WitcherSenseDescriptorKind::History;
    const size_t first_way = expected_history
        ? 0 : (expected_kind == WitcherSenseDescriptorKind::None
            ? 0 : kWitcherSenseHistoryWays);
    const size_t way_count = expected_history
        ? kWitcherSenseHistoryWays
        : (expected_kind == WitcherSenseDescriptorKind::None
            ? kWitcherSenseDescriptorWays : kWitcherSenseSignatureWays);
    for (size_t offset = 0; offset < way_count; ++offset) {
        auto& slot = set.slots[first_way + offset];
        for (size_t attempt = 0; attempt < 3; ++attempt) {
            const uint64_t begin =
                slot.sequence.load(std::memory_order_acquire);
            if ((begin & 1u) != 0) {
                YieldProcessor();
                continue;
            }
            const auto key = slot.key.load(std::memory_order_relaxed);
            WitcherSenseDescriptorInfo snapshot{};
            snapshot.resource =
                slot.resource.load(std::memory_order_relaxed);
            snapshot.width = slot.width.load(std::memory_order_relaxed);
            snapshot.height = slot.height.load(std::memory_order_relaxed);
            snapshot.kind = static_cast<WitcherSenseDescriptorKind>(
                slot.kind.load(std::memory_order_relaxed));
            const uint64_t end =
                slot.sequence.load(std::memory_order_acquire);
            if (begin != end || (end & 1u) != 0) {
                continue;
            }
            if (key == cpu_handle && snapshot.resource != nullptr &&
                snapshot.kind != WitcherSenseDescriptorKind::None &&
                (expected_kind == WitcherSenseDescriptorKind::None ||
                    snapshot.kind == expected_kind)) {
                info_out = snapshot;
                return true;
            }
            break;
        }
    }
    return false;
}

void copy_witcher_sense_descriptor_target(
    SIZE_T dest_cpu, SIZE_T src_cpu) {
    WitcherSenseDescriptorInfo source{};
    if (load_witcher_sense_descriptor_target(src_cpu, source)) {
        store_witcher_sense_descriptor_target(dest_cpu, source);
    } else {
        invalidate_witcher_sense_descriptor_target(dest_cpu);
    }
}

