// [DIAG:ROUTE-FLIGHT-F3 V1310] One timestamp per Present. Hot route sites
// append compact POD events only when the independent INI switch is enabled.
std::atomic<int64_t> g_route_flight_present_qpc{};

void update_route_flight_present_clock() {
    if (!w3vr::route_flight::enabled()) {
        return;
    }
    LARGE_INTEGER now{};
    if (QueryPerformanceCounter(&now)) {
        g_route_flight_present_qpc.store(
            now.QuadPart, std::memory_order_relaxed);
    }
}

void record_route_flight(
    w3vr::route_flight::EventCode code,
    int32_t eye = -1,
    uint64_t pair_id = 0,
    uint64_t previous_pair_id = 0,
    uint32_t generation = UINT32_MAX,
    uint16_t stage = 0,
    uint32_t flags = 0,
    uint32_t detail0 = 0,
    uint32_t detail1 = 0,
    uint32_t detail2 = 0,
    uint32_t detail3 = 0) {
    if (!w3vr::route_flight::enabled()) {
        return;
    }
    w3vr::route_flight::Event event{};
    event.qpc = g_route_flight_present_qpc.load(
        std::memory_order_relaxed);
    event.present = g_present_count.load(std::memory_order_relaxed);
    event.pair_id = pair_id;
    event.previous_pair_id = previous_pair_id;
    event.generation = generation == UINT32_MAX
        ? g_streamline_capture_generation.load(std::memory_order_relaxed)
        : generation;
    event.eye = eye;
    event.thread_id = GetCurrentThreadId();
    event.code = code;
    event.stage = stage;
    event.flags = flags;
    event.detail0 = detail0;
    event.detail1 = detail1;
    event.detail2 = detail2;
    event.detail3 = detail3;
    w3vr::route_flight::record(event);
}

uint32_t route_flight_float_bits(float value) {
    uint32_t bits{};
    static_assert(sizeof(bits) == sizeof(value));
    memcpy(&bits, &value, sizeof(bits));
    return bits;
}

void record_real_smoke_selection(
    const RealSmokeSelectionTrace& trace,
    uint16_t final_stage,
    uint32_t final_variant,
    bool asymmetric_center,
    bool variant_drawn) {
    const uint32_t flags =
        (variant_drawn ? 0x01u : 0u) |
        (final_variant <= 1 ? 0x02u : 0u) |
        (asymmetric_center ? 0x04u : 0u) |
        (final_variant >= 2 ? 0x08u : 0u);
    record_route_flight(
        w3vr::route_flight::EventCode::SmokeSelect,
        trace.eye,
        trace.pair_id,
        g_engine_completed_pair_id.load(std::memory_order_relaxed),
        UINT32_MAX,
        final_stage,
        flags,
        static_cast<uint32_t>(trace.reason),
        final_variant,
        route_flight_float_bits(trace.selected_distance),
        route_flight_float_bits(trace.separation_margin));
}

class TaauRouteFlightScope {
public:
    TaauRouteFlightScope(UINT x, UINT y, UINT z)
        : x_(x), y_(y), z_(z) {
        record_route_flight(
            w3vr::route_flight::EventCode::TaauResolve,
            -1, 0, 0, UINT32_MAX, 0, 0, x_, y_, z_, 0);
    }

    ~TaauRouteFlightScope() {
        record_route_flight(
            w3vr::route_flight::EventCode::TaauResolve,
            eye_, pair_id_, previous_pair_id_, generation_, stage_, flags_,
            x_, y_, detail2_, detail3_);
    }

    void set_identity(
        int eye, uint64_t pair_id, uint32_t generation, bool recovered) {
        eye_ = eye;
        pair_id_ = pair_id;
        generation_ = generation;
        stage_ = std::max<uint16_t>(stage_, 3);
        if (recovered) {
            flags_ |= 0x02u;
        }
    }

    void set_history(uint64_t previous_pair_id, uint64_t matched_previous) {
        previous_pair_id_ = previous_pair_id;
        detail2_ = static_cast<uint32_t>(matched_previous);
        stage_ = std::max<uint16_t>(stage_, 5);
    }

    void mark_afw(bool requested, bool captured) {
        if (requested) flags_ |= 0x04u;
        if (captured) flags_ |= 0x40u;
        stage_ = std::max<uint16_t>(stage_, 6);
    }

    void advance(uint16_t stage, uint32_t flags = 0, uint32_t detail = 0) {
        stage_ = std::max(stage_, stage);
        flags_ |= flags;
        detail3_ = detail;
    }

    void succeed(uint16_t stage, uint32_t flags = 0) {
        advance(stage, flags | 0x01u);
    }

private:
    UINT x_{};
    UINT y_{};
    UINT z_{};
    int32_t eye_{-1};
    uint64_t pair_id_{};
    uint64_t previous_pair_id_{};
    uint32_t generation_{UINT32_MAX};
    uint16_t stage_{1};
    uint32_t flags_{};
    uint32_t detail2_{};
    uint32_t detail3_{};
};

class RouteFlightOutcomeScope {
public:
    RouteFlightOutcomeScope(
        w3vr::route_flight::EventCode code,
        int32_t eye,
        uint64_t pair_id,
        uint32_t generation,
        uint32_t detail0 = 0)
        : code_(code), eye_(eye), pair_id_(pair_id),
          generation_(generation), detail0_(detail0) {
        record_route_flight(
            code_, eye_, pair_id_, 0, generation_, 0, 0,
            detail0_, 0, 0, 0);
    }

    ~RouteFlightOutcomeScope() {
        record_route_flight(
            code_, eye_, pair_id_, previous_pair_id_, generation_,
            stage_, flags_, detail0_, detail1_, detail2_, detail3_);
    }

    void advance(
        uint16_t stage,
        uint32_t flags = 0,
        uint32_t detail1 = 0,
        uint32_t detail2 = 0,
        uint32_t detail3 = 0) {
        stage_ = std::max(stage_, stage);
        flags_ |= flags;
        detail1_ = detail1;
        detail2_ = detail2;
        detail3_ = detail3;
    }

    void set_previous(uint64_t previous_pair_id) {
        previous_pair_id_ = previous_pair_id;
    }

    void succeed(uint16_t stage, uint32_t flags = 0) {
        advance(stage, flags | 0x01u, detail1_, detail2_, detail3_);
    }

private:
    w3vr::route_flight::EventCode code_{};
    int32_t eye_{-1};
    uint64_t pair_id_{};
    uint64_t previous_pair_id_{};
    uint32_t generation_{UINT32_MAX};
    uint16_t stage_{1};
    uint32_t flags_{};
    uint32_t detail0_{};
    uint32_t detail1_{};
    uint32_t detail2_{};
    uint32_t detail3_{};
};

bool taau_matrix_warmup_ready(uint64_t present) {
    uint32_t recent_samples[2]{};
    std::scoped_lock lock{g_engine_temporal_matrix_mutex};
    for (const auto& pair : g_engine_temporal_matrix_ring) {
        if (!pair.corrected_valid || pair.eye < 0 || pair.eye > 1 ||
            pair.present > present || present - pair.present > 16) {
            continue;
        }
        ++recent_samples[pair.eye];
    }
    if (clean_mono_transport_active()) {
        return recent_samples[0] >= 2;
    }
    return recent_samples[0] >= 2 && recent_samples[1] >= 2;
}

void update_taau_auto_activation(uint64_t present) {
    // [PERF:DLSS-SEQUENTIAL 1/1] Mode 3 corrects the DLSS motion input in the
    // Streamline evaluate route. The native TAAU resolve fallback can isolate
    // history only in mono and in the native TAAU stereo routes. Sequential
    // DLSS Mode 3 performs its correction in Streamline, restores the original
    // motion texture, and then runs the native resolve anyway. Do not arm that
    // inapplicable DLSS compute-hook path.
    if (dlss_sequential_mode_active()) {
        return;
    }
    if ((!temporal_backend_is_taau() && !temporal_backend_is_dlss()) ||
        g_taau_auto_activated.load(std::memory_order_relaxed) ||
        g_taau_auto_activation_pending.load(std::memory_order_relaxed)) {
        return;
    }
    const auto last_seen =
        g_taau_native_last_seen_present.load(std::memory_order_relaxed);
    const bool taau_recent = last_seen != UINT64_MAX &&
        present >= last_seen && present - last_seen <= 4;
    const bool render_route_ready = clean_mono_transport_active() ||
        g_engine_dual_render_active.load(std::memory_order_relaxed);
    const bool renderer_ready = taau_recent && render_route_ready &&
        g_hmd_pose_valid.load(std::memory_order_relaxed) &&
        g_engine_menu_state.load(std::memory_order_relaxed) == 0;
    if (!renderer_ready) {
        g_taau_auto_candidate_start_present.store(
            UINT64_MAX, std::memory_order_relaxed);
        g_taau_matrix_warmup_active.store(false, std::memory_order_relaxed);
        g_taau_matrix_warmup_start_present.store(
            UINT64_MAX, std::memory_order_relaxed);
        g_taau_matrix_ready_start_present.store(
            UINT64_MAX, std::memory_order_relaxed);
        return;
    }

    auto start = g_taau_auto_candidate_start_present.load(std::memory_order_relaxed);
    if (start == UINT64_MAX) {
        g_taau_auto_candidate_start_present.store(present, std::memory_order_relaxed);
        return;
    }
    const auto activation_delay = static_cast<uint64_t>(
        g_config.engine_taau_activation_delay_frames);
    if (present - start < activation_delay) {
        return;
    }

    if (!g_taau_matrix_warmup_active.exchange(true, std::memory_order_relaxed)) {
        g_taau_matrix_warmup_start_present.store(present, std::memory_order_relaxed);
        log_line("TAAU matrix warmup started present=%llu",
            static_cast<unsigned long long>(present));
        return;
    }
    if (!taau_matrix_warmup_ready(present)) {
        g_taau_matrix_ready_start_present.store(
            UINT64_MAX, std::memory_order_relaxed);
        return;
    }
    auto matrix_ready_start = g_taau_matrix_ready_start_present.load(
        std::memory_order_relaxed);
    if (matrix_ready_start == UINT64_MAX) {
        g_taau_matrix_ready_start_present.store(present, std::memory_order_relaxed);
        return;
    }
    constexpr uint64_t kTaauMatrixReadySettleFrames = 30;
    if (present - matrix_ready_start < kTaauMatrixReadySettleFrames) {
        return;
    }

    g_taau_auto_activation_pending.store(true, std::memory_order_relaxed);
    wait_for_xr_gpu();
    g_taau_force_matrix_fallback.store(true, std::memory_order_relaxed);
    g_taau_differential_activation_present.store(UINT64_MAX, std::memory_order_relaxed);
    g_taau_override_log_count.store(0, std::memory_order_relaxed);
    g_taau_auto_activated.store(true, std::memory_order_relaxed);
    g_taau_auto_activation_pending.store(false, std::memory_order_relaxed);
    log_line("TAAU correction auto-activated present=%llu first_seen=%llu stable=%llu",
        static_cast<unsigned long long>(present),
        static_cast<unsigned long long>(last_seen),
        static_cast<unsigned long long>(present - start));
}

void log_taau_health(uint64_t present) {
    const bool targeted = taau_drop_diagnostics_active();
    if ((!g_config.runtime_diagnostics && !targeted) ||
        !g_taau_force_matrix_fallback.load(std::memory_order_relaxed) ||
        present == 0 || present % 1800 != 0) {
        return;
    }
    log_taau_trace_line("TAAU health present=%llu total=%llu corrected=%llu descriptor_fail=%llu resource_fail=%llu cb10_fail=%llu matrix_fail=%llu compose_fail=%llu history_fallback=%llu",
        static_cast<unsigned long long>(present),
        static_cast<unsigned long long>(g_taau_health_total.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_corrected.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_descriptor_fail.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_resource_fail.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_cb10_fail.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_matrix_fail.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_compose_fail.load(std::memory_order_relaxed)),
        static_cast<unsigned long long>(g_taau_health_history_fallback.load(std::memory_order_relaxed)));
}

void log_taau_early_failure(const char* category, uint64_t count) {
    // A sustained failure used to emit one synchronous file open/write/close
    // per resolve.  That diagnostic load can itself starve the stereo producer
    // and turn the event being observed into a dropped pair.  Keep the first
    // samples and a periodic progress marker without perturbing cadence.
    if (count <= 4 ||
        (taau_drop_diagnostics_active() && count % 120 == 0)) {
        log_taau_trace_line("TAAU health early failure category=%s count=%llu total=%llu present=%llu",
            category,
            static_cast<unsigned long long>(count),
            static_cast<unsigned long long>(g_taau_health_total.load(std::memory_order_relaxed)),
            static_cast<unsigned long long>(g_present_count.load(std::memory_order_relaxed)));
    }
}

void update_taau_hot_hook_state() {
    const bool route_enabled = taau_compute_hooks_needed();
    const bool taau_core_needed = route_enabled &&
        (taau_runtime_tracking_active() ||
            g_taau_packed_core_prearmed.load(std::memory_order_relaxed));
    const bool taau_probe_needed = route_enabled &&
        g_compute_probe_active.load(std::memory_order_relaxed);
    const bool core_needed = taau_core_needed ||
        asymmetric_tiled_culling_fix_needed() ||
        // Dispatch and compute-table tracking are functional for the RT route.
        rt_symmetric_dlss_per_eye_ao_history_active();
    const bool probe_needed = taau_probe_needed;
    auto set_hook = [](void* target, bool enabled) {
        if (target == nullptr) {
            return;
        }
        if (enabled) {
            MH_EnableHook(target);
        } else {
            MH_DisableHook(target);
        }
    };

    if (core_needed != g_taau_core_hooks_enabled) {
        if (core_needed) {
            set_hook(g_compute_table_hook_target, true);
            set_hook(g_compute_signature_hook_target, true);
            set_hook(g_dispatch_hook_target, true);
        } else {
            set_hook(g_dispatch_hook_target, false);
            set_hook(g_compute_signature_hook_target, false);
            set_hook(g_compute_table_hook_target, false);
        }
        g_taau_core_hooks_enabled = core_needed;
        log_line("TAAU core hooks enabled=%u", core_needed ? 1u : 0u);
    }
    if (probe_needed != g_taau_probe_hooks_enabled) {
        set_hook(g_compute_cbv_hook_target, probe_needed);
        set_hook(g_om_render_targets_hook_target,
            taau_core_needed || taau_probe_needed);
        g_taau_probe_hooks_enabled = probe_needed;
        log_line("TAAU probe-only hooks enabled=%u", probe_needed ? 1u : 0u);
    }
    const bool constants_needed = taau_probe_needed;
    if (constants_needed != g_taau_constant_hooks_enabled) {
        set_hook(g_compute_constant_hook_target, constants_needed);
        set_hook(g_compute_constants_hook_target, constants_needed);
        g_taau_constant_hooks_enabled = constants_needed;
    }
}

