// [PERF:LOG-FILE-HANDLE 1/1] A diagnostic has to observe the frame without
// reshaping it. Re-deriving the path and reopening plus closing the file for
// every record turned each line into a synchronous filesystem metadata
// operation, taken while holding this mutex, so the frames that emit a burst
// of records paid a periodic cost that the capture then blamed on the
// renderer. Hold the handle open and flush per line instead: the bytes still
// reach the OS on every line, so a crashed process keeps its log tail.
void write_log_line_v(const char* fmt, va_list args) {
    if (!g_config.runtime_diagnostics) {
        return;
    }
    std::scoped_lock lock{g_log_mutex};

    static FILE* file{};
    if (file == nullptr) {
        char module_path[MAX_PATH]{};
        GetModuleFileNameA(nullptr, module_path, sizeof(module_path));

        char* slash = strrchr(module_path, '\\');
        if (slash != nullptr) {
            slash[1] = '\0';
        }

        strcat_s(module_path, "witcher3vr.log");

        if (fopen_s(&file, module_path, "a") != 0 || file == nullptr) {
            file = nullptr;
            return;
        }
    }

    SYSTEMTIME st{};
    GetLocalTime(&st);
    fprintf(file, "[%02u:%02u:%02u.%03u] ", st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
    vfprintf(file, fmt, args);

    fprintf(file, "\n");
    fflush(file);
}

void log_line(const char* fmt, ...) {
    if (!g_config.logging_enabled || !g_config.runtime_diagnostics) {
        return;
    }
    va_list args{};
    va_start(args, fmt);
    write_log_line_v(fmt, args);
    va_end(args);
}

bool is_reshade_immediate_command_list(
    ID3D12GraphicsCommandList* command_list) {
    if (command_list == nullptr || g_reshade_secondary_module == nullptr) {
        return false;
    }
    if (command_list == g_reshade_last_internal_command_list) {
        return true;
    }

    {
        std::scoped_lock lock{
            g_reshade_command_list_classification_mutex};
        const auto found =
            g_reshade_command_list_classification.find(command_list);
        if (found != g_reshade_command_list_classification.end()) {
            g_reshade_last_internal_command_list = command_list;
            return true;
        }
    }

    wchar_t object_name[64]{};
    UINT object_name_size = sizeof(object_name);
    const HRESULT name_result = command_list->GetPrivateData(
        WKPDID_D3DDebugObjectNameW, &object_name_size, object_name);
    const bool is_internal = SUCCEEDED(name_result) &&
        wcscmp(object_name, L"ReShade immediate command list") == 0;
    if (!is_internal) {
        // The name can be published later. Do not turn this transient miss
        // into a permanent classification for this raw COM identity.
        return false;
    }

    bool inserted{};
    {
        std::scoped_lock lock{
            g_reshade_command_list_classification_mutex};
        inserted =
            g_reshade_command_list_classification.insert(command_list).second;
    }
    g_reshade_last_internal_command_list = command_list;
    if (inserted) {
        const uint32_t detection =
            g_reshade_immediate_command_list_detection_count.fetch_add(
                1, std::memory_order_relaxed) + 1;
        log_line(
            "V23033 ReShade immediate command list isolated list=%p "
            "detection=%u gpu_submission=unchanged "
            "w3vr_tracking=disabled classification=positive_only",
            command_list, detection);
    }
    return true;
}

// [DEBUG:RENDERDOC-DLSS-CAPTURE V12102 1/3] Bind the official in-application
// API. Prefer an injected module, otherwise load an explicit renderdoc.dll
// beside the game executable. initialize_real_dxgi_exports() runs first so
// RenderDoc cannot redirect this proxy's forwarding lookup back into its own
// CreateDXGIFactory hook. The NVIDIA option is still set before D3D12/NGX
// capability queries so DLSS remains available.
RENDERDOC_API_1_6_0* initialize_renderdoc_capture_api() {
    std::scoped_lock lock{g_renderdoc_api_mutex};
    if (g_renderdoc_api != nullptr) {
        return g_renderdoc_api;
    }
    if (!g_config.renderdoc_capture_enabled) {
        return nullptr;
    }
    g_renderdoc_api_attempted = true;

    HMODULE module = GetModuleHandleW(L"renderdoc.dll");
    if (module == nullptr) {
        wchar_t module_path[MAX_PATH]{};
        const DWORD length = GetModuleFileNameW(
            nullptr, module_path, static_cast<DWORD>(std::size(module_path)));
        if (length != 0 && length < std::size(module_path)) {
            wchar_t* slash = wcsrchr(module_path, L'\\');
            if (slash != nullptr) {
                const size_t prefix_length =
                    static_cast<size_t>(slash + 1 - module_path);
                if (wcscpy_s(
                        slash + 1, std::size(module_path) - prefix_length,
                        L"renderdoc.dll") == 0 &&
                    GetFileAttributesW(module_path) != INVALID_FILE_ATTRIBUTES) {
                    module = LoadLibraryExW(
                        module_path, nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);
                    g_renderdoc_loaded_from_game_directory = module != nullptr;
                }
            }
        }
    }
    if (module == nullptr) {
        return nullptr;
    }

    const auto get_api = reinterpret_cast<pRENDERDOC_GetAPI>(
        GetProcAddress(module, "RENDERDOC_GetAPI"));
    if (get_api == nullptr) {
        return nullptr;
    }
    RENDERDOC_API_1_6_0* api{};
    if (get_api(
            eRENDERDOC_API_Version_1_6_0,
            reinterpret_cast<void**>(&api)) != 1 || api == nullptr) {
        return nullptr;
    }

    g_renderdoc_module = module;
    g_renderdoc_api = api;
    g_renderdoc_nvidia_extension_result = api->SetCaptureOptionU32(
        eRENDERDOC_Option_AllowUnsupportedVendorExtensions, 0x10DEu);
    api->GetAPIVersion(
        &g_renderdoc_api_major, &g_renderdoc_api_minor,
        &g_renderdoc_api_patch);
    return api;
}

void log_renderdoc_capture_api_status() {
    std::scoped_lock lock{g_renderdoc_api_mutex};
    log_line(
        "V1286 RenderDoc integration configured=%u streamline_bridge=%u attempted=%u "
        "available=%u source=%s "
        "api=%d.%d.%d allow_nvidia_0x10DE=%d hotkey=F3",
        g_config.renderdoc_capture_enabled ? 1u : 0u,
        g_config.renderdoc_streamline_device_bridge ? 1u : 0u,
        g_renderdoc_api_attempted ? 1u : 0u,
        g_renderdoc_api != nullptr ? 1u : 0u,
        !g_config.renderdoc_capture_enabled
            ? "disabled"
            : g_renderdoc_api != nullptr
            ? (g_renderdoc_loaded_from_game_directory
                ? "game_directory" : "injected")
            : "none",
        g_renderdoc_api_major, g_renderdoc_api_minor,
        g_renderdoc_api_patch, g_renderdoc_nvidia_extension_result);
}

// [DEBUG:RENDERDOC-DLSS-CAPTURE V12102 2/3] TriggerCapture asks RenderDoc to
// capture the next presented frame. Select the current D3D12 device/window when
// possible so the desktop DXGI boundary owns the capture while all queues on
// the same device, including NGX and OpenXR work, remain visible.
void trigger_renderdoc_capture(IDXGISwapChain* swapchain) {
    auto* api = initialize_renderdoc_capture_api();
    const uint64_t request = g_renderdoc_capture_requests.fetch_add(
        1, std::memory_order_relaxed) + 1;
    if (api == nullptr) {
        log_line(
            "V1271 RenderDoc capture unavailable configured=%u "
            "request=%llu module=%p",
            g_config.renderdoc_capture_enabled ? 1u : 0u,
            static_cast<unsigned long long>(request), g_renderdoc_module);
        return;
    }

    DXGI_SWAP_CHAIN_DESC desc{};
    const bool window_valid = swapchain != nullptr &&
        SUCCEEDED(swapchain->GetDesc(&desc)) && desc.OutputWindow != nullptr;
    if (g_d3d12_device != nullptr && window_valid) {
        api->SetActiveWindow(
            static_cast<RENDERDOC_DevicePointer>(g_d3d12_device),
            reinterpret_cast<RENDERDOC_WindowHandle>(desc.OutputWindow));
    }
    api->TriggerCapture();
    log_line(
        "V1271 RenderDoc capture requested request=%llu present=%llu "
        "device=%p window=%p nvidia_option=%d",
        static_cast<unsigned long long>(request),
        static_cast<unsigned long long>(
            g_present_count.load(std::memory_order_relaxed)),
        g_d3d12_device, window_valid ? desc.OutputWindow : nullptr,
        g_renderdoc_nvidia_extension_result);
}

bool puredark_afw_dlss_route_active() {
    return puredark_afw_mode3_aer_dlss_route_configured();
}

std::wstring puredark_afw_plugin_path() {
    wchar_t executable_path[MAX_PATH]{};
    const DWORD length = GetModuleFileNameW(
        nullptr, executable_path,
        static_cast<DWORD>(std::size(executable_path)));
    if (length == 0 || length >= std::size(executable_path)) {
        return {};
    }
    wchar_t* slash = wcsrchr(executable_path, L'\\');
    if (slash == nullptr) {
        return {};
    }
    slash[1] = L'\0';
    constexpr wchar_t plugin_name[] = L"PDAFWPlugin.dll";
    if (wcslen(executable_path) + std::size(plugin_name) >
        std::size(executable_path)) {
        return {};
    }
    wcscat_s(executable_path, plugin_name);
    return executable_path;
}

void log_puredark_afw_failure(const char* stage, const std::wstring& error) {
    if (take_bounded_log_slot(g_puredark_afw_failure_logs, 24)) {
        log_line(
            "PureDark AFW fallback stage=%s present=%llu error=%ls",
            stage,
            static_cast<unsigned long long>(
                g_present_count.load(std::memory_order_relaxed)),
            error.c_str());
    }
}

bool ensure_puredark_afw_device_locked(std::wstring& error) {
    if (g_puredark_afw_device_initialized &&
        g_puredark_afw_bridge != nullptr) {
        error.clear();
        return true;
    }
    if (g_puredark_afw_load_attempted || g_d3d12_device == nullptr ||
        g_command_queue == nullptr) {
        error = g_puredark_afw_load_attempted
            ? L"PureDark initialization was already rejected"
            : L"D3D12 device or command queue is unavailable";
        return false;
    }

    g_puredark_afw_load_attempted = true;
    const std::wstring plugin_path = puredark_afw_plugin_path();
    auto* bridge = new w3vr::puredark_afw::Bridge();
    if (!bridge->load(plugin_path, error)) {
        delete bridge;
        return false;
    }
    w3vr::puredark_afw::DeviceParams device_params{};
    device_params.d3d12_device = g_d3d12_device;
    device_params.d3d12_queue = g_command_queue;
    if (!bridge->initialize_device(device_params, error)) {
        delete bridge;
        return false;
    }
    // Keep the plugin resident through process shutdown. Destroying a global
    // bridge would call FreeLibrary while the Windows loader lock is held.
    g_puredark_afw_bridge = bridge;
    g_puredark_afw_device_initialized = true;
    if (take_bounded_log_slot(g_puredark_afw_present_logs, 1)) {
        log_line(
            "PureDark AFW device initialized plugin=%ls device=%p queue=%p",
            plugin_path.c_str(), g_d3d12_device, g_command_queue);
    }
    error.clear();
    return true;
}

bool ensure_puredark_afw_capture_texture_locked(
    const D3D12_RESOURCE_DESC& source_desc,
    w3vr::puredark_afw::TextureDesc& destination,
    std::wstring& error) {
    if (source_desc.Dimension != D3D12_RESOURCE_DIMENSION_TEXTURE2D ||
        source_desc.Width == 0 || source_desc.Width > INT_MAX ||
        source_desc.Height == 0 || source_desc.Height > INT_MAX ||
        source_desc.SampleDesc.Count != 1 ||
        source_desc.Format == DXGI_FORMAT_UNKNOWN) {
        error = L"DLSS AFW input texture descriptor is unsupported";
        return false;
    }
    if (destination.texture != nullptr) {
        const auto destination_desc = destination.texture->GetDesc();
        if (destination_desc.Width == source_desc.Width &&
            destination_desc.Height == source_desc.Height &&
            destination_desc.Format == source_desc.Format) {
            error.clear();
            return true;
        }
    }

    w3vr::puredark_afw::TextureDesc created{};
    if (!g_puredark_afw_bridge->create_texture(
            static_cast<int>(source_desc.Width),
            static_cast<int>(source_desc.Height), source_desc.Format,
            D3D12_RESOURCE_STATE_ALL_SHADER_RESOURCE,
            created, true, error)) {
        return false;
    }
    // Old resources are intentionally retained across the rare resolution
    // transition: the preceding game command list may still reference them.
    destination = created;
    return true;
}

bool current_puredark_afw_direct_route_tag(
    uint32_t routed_eye,
    EngineFrameTag& route_tag) {
    route_tag = {};
    if (g_streamline_dlss_route_tag_valid) {
        route_tag = g_streamline_dlss_route_tag;
    } else if (g_engine_render_tag_frame_lookup_exact &&
        g_engine_render_eye >= 0 && g_engine_render_eye <= 1) {
        // slSetConstants may be issued by the exact gameplay task immediately
        // before its DLSS emitter. That scope owns the same immutable factory
        // tag even though the deferred command TLS has not started yet.
        route_tag.eye = static_cast<uint32_t>(g_engine_render_eye);
        route_tag.generation = g_engine_render_generation;
        route_tag.pair_id = g_engine_render_pair_id;
        route_tag.render_view = g_engine_render_view;
        route_tag.render_view_valid = g_engine_render_view_valid;
        route_tag.pixel_projection = g_engine_render_pixel_projection;
        route_tag.hmd_pose = g_engine_render_hmd_pose;
        route_tag.task_provenance_valid = true;
    } else {
        return false;
    }
    const uint32_t capture_generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    return route_tag.task_provenance_valid &&
        route_tag.render_view_valid && route_tag.eye == routed_eye &&
        route_tag.eye <= 1 && route_tag.pair_id != 0 &&
        route_tag.pair_id != UINT64_MAX &&
        route_tag.generation == capture_generation;
}

bool same_streamline_dlss_callback_identity(
    const EngineFrameTag& lhs,
    const EngineFrameTag& rhs) {
    return lhs.task_provenance_valid && rhs.task_provenance_valid &&
        lhs.eye == rhs.eye && lhs.generation == rhs.generation &&
        lhs.pair_id == rhs.pair_id;
}

StreamlineDlssEvaluateSnapshot* acquire_streamline_dlss_evaluate_snapshot(
    uint32_t routed_eye) {
    if (!native_dlss_public_streamline_owner_active() || routed_eye > 1) {
        return nullptr;
    }
    EngineFrameTag route_tag{};
    if (!current_puredark_afw_direct_route_tag(routed_eye, route_tag)) {
        return nullptr;
    }
    auto& snapshot = g_streamline_dlss_evaluate_snapshot;
    if (!snapshot.route_valid ||
        !same_streamline_dlss_callback_identity(
            snapshot.route_tag, route_tag)) {
        snapshot = {};
        snapshot.route_tag = route_tag;
        snapshot.route_valid = true;
    }
    return &snapshot;
}

bool streamline_dlss_evaluate_snapshot_matches_current(
    uint32_t routed_eye) {
    const auto& snapshot = g_streamline_dlss_evaluate_snapshot;
    return snapshot.route_valid && g_streamline_dlss_route_tag_valid &&
        routed_eye <= 1 &&
        same_streamline_dlss_callback_identity(
            snapshot.route_tag, g_streamline_dlss_route_tag) &&
        snapshot.route_tag.eye == routed_eye &&
        snapshot.route_tag.generation ==
            g_streamline_capture_generation.load(std::memory_order_acquire);
}

void capture_streamline_dlss_callback_resource(
    const void* resource,
    uint32_t tag,
    uint32_t routed_eye) {
    if (tag != 0 && tag != 1 && tag != 4) {
        return;
    }
    auto* snapshot = acquire_streamline_dlss_evaluate_snapshot(routed_eye);
    if (snapshot == nullptr) {
        return;
    }
    ID3D12Resource* native{};
    uint32_t state = static_cast<uint32_t>(
        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    if (resource != nullptr) {
        memcpy(&native, static_cast<const uint8_t*>(resource) + 8,
            sizeof(native));
        memcpy(&state, static_cast<const uint8_t*>(resource) + 32,
            sizeof(state));
    }
    if (tag == 0) {
        snapshot->depth = native;
        snapshot->depth_state = static_cast<D3D12_RESOURCE_STATES>(state);
        snapshot->depth_valid = native != nullptr;
    } else if (tag == 1) {
        snapshot->motion_vectors = native;
        snapshot->motion_state = static_cast<D3D12_RESOURCE_STATES>(state);
        snapshot->motion_vectors_valid = native != nullptr;
    } else {
        snapshot->output = native;
        snapshot->output_valid = native != nullptr;
    }
}

void prepare_streamline_dlss_callback_constants(
    void* constants,
    uint32_t routed_eye) {
    if (constants == nullptr) {
        return;
    }
    auto* snapshot = acquire_streamline_dlss_evaluate_snapshot(routed_eye);
    if (snapshot == nullptr) {
        return;
    }
    auto* values = static_cast<float*>(constants);
    snapshot->motion_scale_x = values[82];
    snapshot->motion_scale_y = values[83];
    snapshot->motion_scale_valid =
        std::isfinite(snapshot->motion_scale_x) &&
        std::isfinite(snapshot->motion_scale_y);
    snapshot->jitter = {};
    snapshot->jitter_applied_to_streamline = false;
}

// [FIX:AER-AFW-EXACT-NATIVE-PROJECTION V1350 1/4] Full-frame native pixels and
// AFW must use the same two frozen tangent spaces. Streamline exposes the
// larger shared-envelope projection here. Rebuild the real eye's complete
// focal scale and optical centre, then derive the peer from that exact source.
// This is camera metadata only: no color resize, crop, shader or image pass.
bool rebuild_puredark_afw_native_projection_pair(
    const std::array<XrView, 2>& render_views,
    uint32_t source_eye,
    w3vr::puredark_afw::CameraData& camera,
    w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor&
        source_projection,
    w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor&
        destination_projection,
    std::wstring& error) {
    if (source_eye > 1) {
        error = L"AFW native source eye is invalid";
        return false;
    }
    const uint32_t destination_eye = 1u - source_eye;
    if (!w3vr::openxr_eye_geometry::derive_asymmetric_projection_descriptor(
            render_views[source_eye].fov, 1, 1, source_projection) ||
        !w3vr::openxr_eye_geometry::derive_asymmetric_projection_descriptor(
            render_views[destination_eye].fov, 1, 1,
            destination_projection) ||
        !w3vr::puredark_afw::apply_exact_source_eye_projection(
            {
                source_projection.horizontal_tangent_span,
                source_projection.vertical_tangent_span,
                source_projection.center_ndc_x,
                source_projection.center_ndc_y},
            camera, error) ||
        !w3vr::puredark_afw::retarget_destination_eye_projection(
            {
                source_projection.horizontal_tangent_span,
                source_projection.vertical_tangent_span,
                source_projection.center_ndc_x,
                source_projection.center_ndc_y},
            {
                destination_projection.horizontal_tangent_span,
                destination_projection.vertical_tangent_span,
                destination_projection.center_ndc_x,
                destination_projection.center_ndc_y},
            camera, error)) {
        if (error.empty()) {
            error = L"AFW native pair projection is invalid";
        }
        return false;
    }
    error.clear();
    return true;
}

void capture_puredark_afw_camera(
    const void* constants,
    uint32_t routed_eye) {
    if (!puredark_afw_dlss_route_active() || constants == nullptr ||
        routed_eye > 1) {
        return;
    }
    EngineFrameTag route_tag{};
    if (!current_puredark_afw_direct_route_tag(
            routed_eye, route_tag)) {
        return;
    }

    float baseline =
        g_runtime_eye_baseline_m.load(std::memory_order_relaxed);
    if (!std::isfinite(baseline) || baseline < 0.04f || baseline > 0.10f) {
        baseline = std::fabs(g_config.engine_factory_stereo_offset);
    }
    PuredarkAfwCameraSnapshot captured{};
    std::array<XrView, 2> aer_reference_views{{
        {XR_TYPE_VIEW}, {XR_TYPE_VIEW}}};
    bool aer_reference_views_valid{};
    std::wstring error;
    if (!w3vr::puredark_afw::build_camera_data_from_streamline(
            static_cast<const float*>(constants), 102, routed_eye,
            baseline, captured.camera, error)) {
        log_puredark_afw_failure("camera", error);
        return;
    }
    memcpy(
        captured.streamline_constants.data(), constants,
        sizeof(captured.streamline_constants));
    captured.streamline_constants_valid = true;
    Mode3AfwPixelProjectionAuthority projection_authority{};
    if (!resolve_mode3_afw_pixel_projection(
            route_tag.pair_id, route_tag.generation, routed_eye,
            route_tag.pixel_projection, route_tag.render_view.fov,
            projection_authority)) {
        log_puredark_afw_failure(
            "camera_pixel_projection",
            L"exact AFW producer has no valid pixel-projection authority");
        return;
    }
    // [FIX:PUREDARK-AFW-AER-DIRECT-PEER-FOV V12080 1/1]
    // `capture_puredark_afw_dlss_inputs` consumes this exact route-tagged
    // camera producer. Mode-3 AER has no same-tick Stereo pair ledger, so use
    // the immutable recentered peer-eye poses and both FOVs frozen with the
    // exact native-asymmetric producer pair. Depth, MVec, scale and command
    // ordering remain the exact NGX inputs.
    if (puredark_afw_mode3_aer_dlss_route_configured() &&
        projection_authority.encoding ==
            w3vr::mode3_transport::AfwPixelProjection::NativeAsymmetric) {
        const uint32_t destination_eye = 1u - routed_eye;
        const XrFovf source_fov = projection_authority.fovs[routed_eye];
        const XrFovf destination_fov =
            projection_authority.fovs[destination_eye];
        bool aer_reference_poses_valid{};
        {
            std::scoped_lock pose_lock{g_hmd_pose_snapshot_mutex};
            if (g_hmd_center_valid.load(std::memory_order_acquire) &&
                g_hmd_pose_valid.load(std::memory_order_acquire)) {
                aer_reference_views[0].pose = g_hmd_center_views[0].pose;
                aer_reference_views[1].pose = g_hmd_center_views[1].pose;
                aer_reference_poses_valid = true;
            }
        }
        if (aer_reference_poses_valid) {
            aer_reference_views[routed_eye].fov = source_fov;
            aer_reference_views[destination_eye].fov = destination_fov;
            aer_reference_views_valid = true;
        }
        w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor
            source_projection{};
        w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor
            destination_projection{};
        const bool raw_asymmetric_projection_valid =
            aer_reference_views_valid &&
            rebuild_puredark_afw_native_projection_pair(
                aer_reference_views, routed_eye, captured.camera,
                source_projection, destination_projection, error);
        if (!aer_reference_views_valid ||
            !raw_asymmetric_projection_valid) {
            log_puredark_afw_failure(
                "direct_dlss_destination_projection", error.empty()
                    ? L"no valid AER source/peer-eye FOV for PureDark"
                    : error);
            return;
        }
        if (g_config.runtime_diagnostics) {
            static std::atomic<uint32_t> projection_logs{};
            if (take_bounded_log_slot(projection_logs, 32)) {
                log_line(
                    "V1350 AFW DLSS exact native camera pair=%llu source_eye=%u destination_eye=%u source_span=%.9g,%.9g source_scale_center=%.9g,%.9g,%.9g,%.9g destination_span=%.9g,%.9g destination_scale_center=%.9g,%.9g,%.9g,%.9g baseline=%.9g authority=full_frame_frozen_pair",
                    static_cast<unsigned long long>(route_tag.pair_id),
                    routed_eye, destination_eye,
                    source_projection.horizontal_tangent_span,
                    source_projection.vertical_tangent_span,
                    captured.camera.source_view_to_clip.values[0],
                    captured.camera.source_view_to_clip.values[5],
                    source_projection.center_ndc_x,
                    source_projection.center_ndc_y,
                    destination_projection.horizontal_tangent_span,
                    destination_projection.vertical_tangent_span,
                    captured.camera.destination_view_to_clip.values[0],
                    captured.camera.destination_view_to_clip.values[5],
                    destination_projection.center_ndc_x,
                    destination_projection.center_ndc_y,
                    baseline);
            }
        }
    }
    captured.pair_id = route_tag.pair_id;
    captured.generation = route_tag.generation;
    captured.eye = routed_eye;
    captured.capture_present =
        g_present_count.load(std::memory_order_relaxed);
    captured.exact_render_view = route_tag.render_view;
    captured.exact_render_view.fov =
        projection_authority.fovs[routed_eye];
    captured.exact_render_view_valid = true;
    if (aer_reference_views_valid) {
        captured.render_views = aer_reference_views;
        captured.render_views_valid = true;
    } else if (g_xr_views.size() >= 2 && g_hmd_pose_valid.load(
            std::memory_order_acquire)) {
        captured.render_views = {g_xr_views[0], g_xr_views[1]};
        captured.render_views_valid = true;
    }
    if (!captured.render_views_valid) {
        return;
    }
    captured.render_views[0].fov = projection_authority.fovs[0];
    captured.render_views[1].fov = projection_authority.fovs[1];
    captured.pixel_projection = projection_authority.encoding;
    captured.valid = true;
    {
        std::scoped_lock lock{g_puredark_afw_mutex};
        // V12015 kept only one camera per eye, so a duplicate/faster producer
        // could overwrite the exact camera before NGX consumed it. Preserve a
        // cheap immutable history and join by generation/eye/pair instead.
        g_puredark_afw_camera_history.push_back(captured);
        while (g_puredark_afw_camera_history.size() >
                kPuredarkAfwCameraHistorySize) {
            g_puredark_afw_camera_history.pop_front();
        }
    }
    if (take_bounded_log_slot(g_puredark_afw_camera_logs, 8)) {
        log_line(
            "PureDark AFW direct camera pair=%llu eye=%u generation=%u baseline=%.6f views=%u exact_view=%u",
            static_cast<unsigned long long>(route_tag.pair_id), routed_eye,
            route_tag.generation, baseline,
            captured.render_views_valid ? 1u : 0u,
            captured.exact_render_view_valid ? 1u : 0u);
    }
}

bool hydrate_streamline_dlss_callback_constants(
    uint32_t frame_token,
    uint32_t routed_eye,
    StreamlineDlssCallbackConstantsSlot* hydrated) {
    if (!native_dlss_public_streamline_owner_active() || routed_eye > 1) {
        return false;
    }
    StreamlineDlssCallbackConstantsSlot cached{};
    {
        std::scoped_lock lock{g_streamline_dlss_callback_constants_mutex};
        cached = g_streamline_dlss_callback_constants[
            streamline_dlss_callback_constants_slot(frame_token, routed_eye)];
    }
    if (!cached.valid || cached.frame_token != frame_token ||
        cached.eye != routed_eye) {
        if (take_bounded_log_slot(
                g_streamline_dlss_callback_constants_logs, 32)) {
            log_line(
                "V1416 native DLSS Streamline constants miss token=%u "
                "eye=%u cached_token=%u cached_valid=%u",
                frame_token, routed_eye, cached.frame_token,
                cached.valid ? 1u : 0u);
        }
        return false;
    }
    if (hydrated != nullptr) {
        *hydrated = cached;
    }
    auto* snapshot = acquire_streamline_dlss_evaluate_snapshot(routed_eye);
    if (snapshot == nullptr) {
        return false;
    }
    const auto* values = cached.constants.data();
    snapshot->motion_scale_x = values[82];
    snapshot->motion_scale_y = values[83];
    snapshot->motion_scale_valid =
        std::isfinite(snapshot->motion_scale_x) &&
        std::isfinite(snapshot->motion_scale_y);
    capture_puredark_afw_camera(cached.constants.data(), routed_eye);
    return snapshot->motion_scale_valid;
}

bool resubmit_streamline_native_asymmetric_dlss_jitter(
    const StreamlineDlssCallbackConstantsSlot& cached,
    uint32_t frame_token,
    uint32_t routed_viewport,
    uint32_t routed_eye) {
    auto& snapshot = g_streamline_dlss_evaluate_snapshot;
    if (!cached.valid || cached.frame_token != frame_token ||
        cached.eye != routed_eye || !snapshot.route_valid ||
        !snapshot.motion_vectors_valid || g_sl_set_constants == nullptr) {
        return false;
    }

    auto corrected = cached.constants;
    auto* values = corrected.data();
    const auto motion_desc = snapshot.motion_vectors->GetDesc();
    float pixel_scale_x = values[82];
    float pixel_scale_y = values[83];
    if (std::fabs(pixel_scale_x) <= 4.0f && motion_desc.Width > 0) {
        pixel_scale_x *= static_cast<float>(motion_desc.Width);
    }
    if (std::fabs(pixel_scale_y) <= 4.0f && motion_desc.Height > 0) {
        pixel_scale_y *= static_cast<float>(motion_desc.Height);
    }

    NativeAsymmetricDlssJitterOverride jitter{};
    if (!prepare_native_asymmetric_dlss_jitter_override_values(
            values[80], values[81], pixel_scale_x, pixel_scale_y,
            static_cast<unsigned>(motion_desc.Width), motion_desc.Height,
            snapshot.route_tag.pair_id, routed_eye, jitter)) {
        snapshot.jitter = jitter;
        return false;
    }

    values[80] = jitter.pure_x;
    values[81] = jitter.pure_y;
    const int constants_result = g_sl_set_constants(
        corrected.data(), frame_token, routed_viewport);
    jitter.applied = true;
    snapshot.jitter = jitter;
    snapshot.jitter_applied_to_streamline = true;
    if (g_config.runtime_diagnostics) {
        static std::atomic<uint32_t> jitter_logs{};
        const uint32_t log_index = jitter_logs.fetch_add(
            1, std::memory_order_relaxed);
        if (log_index < 64) {
            log_line(
                "V1416 native DLSS public jitter sample=%u token=%u "
                "viewport=%u eye=%u pair=%llu raw=%.6f,%.6f "
                "pure=%.6f,%.6f extent=%llux%u sl_constants=%d",
                log_index, frame_token, routed_viewport, routed_eye,
                static_cast<unsigned long long>(snapshot.route_tag.pair_id),
                jitter.original_x, jitter.original_y,
                jitter.pure_x, jitter.pure_y,
                static_cast<unsigned long long>(motion_desc.Width),
                motion_desc.Height, constants_result);
        }
    }
    return true;
}

int32_t capture_puredark_afw_dlss_inputs_from_resources(
    ID3D12GraphicsCommandList* command_list,
    ID3D12Resource* depth,
    D3D12_RESOURCE_STATES depth_state,
    ID3D12Resource* motion_vectors,
    D3D12_RESOURCE_STATES motion_state,
    ID3D12Resource* output,
    float motion_scale_x,
    float motion_scale_y,
    uint32_t routed_eye) {
    const bool route_active = puredark_afw_dlss_route_active();
    const int menu_state =
        g_engine_menu_state.load(std::memory_order_relaxed);
    const bool cinema_active =
        g_cinema_mode_active.load(std::memory_order_relaxed);
    const bool loading_video_active =
        g_engine_loading_screen_video_active.load(std::memory_order_acquire);
    const bool automatic_full_vr_active =
        !g_force_mono_cinema.load(std::memory_order_relaxed) &&
        g_config.cinema_full_vr &&
        g_automatic_full_vr_camera_active.load(std::memory_order_acquire);
    const bool gameplay_capture_allowed =
        w3vr::mode3_transport::afw_gameplay_capture_allowed(
            route_active, menu_state, cinema_active,
            loading_video_active, automatic_full_vr_active);
    if (!gameplay_capture_allowed || command_list == nullptr ||
        routed_eye > 1) {
        static std::atomic<uint32_t> capture_gate_reject_logs{};
        if (g_config.runtime_diagnostics &&
            capture_gate_reject_logs.fetch_add(
                1, std::memory_order_relaxed) < 32) {
            log_line(
                "V12099 AFW DLSS capture gate reject route=%u command_list=%p "
                "eye=%u menu=%d cinema=%u loading=%u full_vr=%u "
                "openxr=%u mode=%d aer=%u backend=%s afw=%u freelook=%u "
                "stereo_offset=%.6f",
                route_active ? 1u : 0u, command_list, routed_eye,
                menu_state, cinema_active ? 1u : 0u,
                loading_video_active ? 1u : 0u,
                automatic_full_vr_active ? 1u : 0u,
                g_config.openxr_enabled ? 1u : 0u, g_config.openxr_mode,
                mode3_aer_presentation_active() ? 1u : 0u,
                temporal_backend_name(),
                g_config.puredark_afw_enabled ? 1u : 0u,
                g_config.hmd_freelook ? 1u : 0u,
                g_config.engine_factory_stereo_offset);
        }
        return -1;
    }
    EngineFrameTag route_tag{};
    if (!current_puredark_afw_direct_route_tag(
            routed_eye, route_tag)) {
        static std::atomic<uint32_t> capture_tag_reject_logs{};
        if (g_config.runtime_diagnostics &&
            capture_tag_reject_logs.fetch_add(
                1, std::memory_order_relaxed) < 32) {
            const auto& tls_tag = g_streamline_dlss_route_tag;
            log_line(
                "V12099 AFW DLSS capture tag reject requested_eye=%u "
                "tls_valid=%u tls_eye=%u tls_pair=%llu tls_generation=%u "
                "tls_provenance=%u tls_view=%u engine_lookup=%u "
                "engine_eye=%d engine_pair=%llu engine_generation=%u "
                "capture_generation=%u",
                routed_eye, g_streamline_dlss_route_tag_valid ? 1u : 0u,
                tls_tag.eye,
                static_cast<unsigned long long>(tls_tag.pair_id),
                tls_tag.generation,
                tls_tag.task_provenance_valid ? 1u : 0u,
                tls_tag.render_view_valid ? 1u : 0u,
                g_engine_render_tag_frame_lookup_exact ? 1u : 0u,
                g_engine_render_eye,
                static_cast<unsigned long long>(g_engine_render_pair_id),
                g_engine_render_generation,
                g_streamline_capture_generation.load(
                    std::memory_order_acquire));
        }
        return -1;
    }

    if (depth == nullptr || motion_vectors == nullptr || output == nullptr ||
        !std::isfinite(motion_scale_x) || !std::isfinite(motion_scale_y)) {
        log_puredark_afw_failure(
            "dlss_inputs", L"DLSS Depth, MotionVectors, Output, or scale is invalid");
        return -1;
    }

    const auto depth_desc = depth->GetDesc();
    const auto motion_desc = motion_vectors->GetDesc();
    const auto output_desc = output->GetDesc();
    std::scoped_lock lock{g_puredark_afw_mutex};
    const auto camera_found = std::find_if(
        g_puredark_afw_camera_history.rbegin(),
        g_puredark_afw_camera_history.rend(),
        [&](const PuredarkAfwCameraSnapshot& camera) {
            return camera.valid && camera.eye == routed_eye &&
                camera.pair_id == route_tag.pair_id &&
                camera.generation == route_tag.generation &&
                camera.exact_render_view_valid;
        });
    if (camera_found == g_puredark_afw_camera_history.rend()) {
        log_puredark_afw_failure(
            "ngx_camera_match", L"no exact Streamline camera for DLSS eye/pair");
        return -1;
    }
    const auto& camera = *camera_found;
    const bool normalize_native_motion = camera.pixel_projection ==
        w3vr::mode3_transport::AfwPixelProjection::NativeAsymmetric;
    w3vr::puredark_afw::Matrix4x4 actual_clip_to_previous{};
    if (normalize_native_motion) {
        if (!camera.streamline_constants_valid) {
            log_puredark_afw_failure(
                "dlss_motion_projection",
                L"native AFW producer has no exact Streamline constants");
            return -1;
        }
        w3vr::puredark_afw::Matrix4x4 centered_projection{};
        w3vr::puredark_afw::Matrix4x4 centered_clip_to_previous{};
        memcpy(
            centered_projection.values,
            camera.streamline_constants.data(),
            sizeof(centered_projection.values));
        memcpy(
            centered_clip_to_previous.values,
            camera.streamline_constants.data() + 48,
            sizeof(centered_clip_to_previous.values));
        std::wstring projection_error;
        if (!w3vr::puredark_afw::rebase_clip_to_previous_projection(
                centered_projection, camera.camera.source_view_to_clip,
                centered_clip_to_previous, actual_clip_to_previous,
                projection_error)) {
            log_puredark_afw_failure(
                "dlss_motion_projection", projection_error);
            return -1;
        }
    }

    uint32_t bundle_slot = UINT32_MAX;
    const uint64_t completed_fence = g_xr_fence != nullptr
        ? g_xr_fence->GetCompletedValue()
        : 0;
    for (size_t attempt = 0; attempt < kPuredarkAfwBundleRingSize;
        ++attempt) {
        const uint32_t candidate = static_cast<uint32_t>(
            (g_puredark_afw_bundle_write_cursor + attempt) %
            kPuredarkAfwBundleRingSize);
        auto& slot = g_puredark_afw_bundle_ring[candidate];
        if (slot.state == PuredarkAfwBundleState::InFlight &&
            slot.retire_fence != 0 &&
            completed_fence >= slot.retire_fence) {
            slot.state = PuredarkAfwBundleState::Free;
            slot.input.valid = false;
            slot.submission_serial = 0;
            slot.ready_present = UINT64_MAX;
            slot.producer_queue_fence = nullptr;
            slot.producer_queue_fence_value = 0;
            slot.retire_fence = 0;
        }
        if (slot.state == PuredarkAfwBundleState::Free) {
            bundle_slot = candidate;
            g_puredark_afw_bundle_write_cursor =
                (candidate + 1) % kPuredarkAfwBundleRingSize;
            break;
        }
    }
    if (bundle_slot >= kPuredarkAfwBundleRingSize) {
        g_puredark_afw_slot_starvation.fetch_add(
            1, std::memory_order_relaxed);
        log_puredark_afw_failure(
            "producer_ring", L"no retired AFW producer bundle slot");
        return -1;
    }

    auto& slot = g_puredark_afw_bundle_ring[bundle_slot];
    slot.state = PuredarkAfwBundleState::Recording;
    slot.route_epoch =
        g_puredark_afw_route_epoch.load(std::memory_order_acquire);
    slot.submission_serial = 0;
    slot.ready_present = UINT64_MAX;
    slot.producer_queue_fence = nullptr;
    slot.producer_queue_fence_value = 0;
    slot.retire_fence = 0;
    auto retained_depth = slot.input.depth;
    auto retained_motion_vectors = slot.input.motion_vectors;
    slot.input = {};
    slot.input.depth = retained_depth;
    slot.input.motion_vectors = retained_motion_vectors;
    auto& captured = slot.input;
    captured.valid = false;
    std::wstring error;
    auto normalized_motion_desc = motion_desc;
    normalized_motion_desc.Format = DXGI_FORMAT_R16G16_FLOAT;
    if (normalize_native_motion &&
        motion_desc.Format != DXGI_FORMAT_R16G16_FLOAT) {
        slot.state = PuredarkAfwBundleState::Free;
        log_puredark_afw_failure(
            "dlss_motion_format",
            L"native AFW DLSS motion is not the proven RG16F contract");
        return -1;
    }
    if (!ensure_puredark_afw_device_locked(error) ||
        !ensure_puredark_afw_capture_texture_locked(
            depth_desc, captured.depth, error) ||
        !ensure_puredark_afw_capture_texture_locked(
            normalized_motion_desc, captured.motion_vectors, error) ||
        (normalize_native_motion &&
            !ensure_puredark_afw_capture_texture_locked(
                motion_desc, slot.motion_normalization_source, error))) {
        slot.state = PuredarkAfwBundleState::Free;
        log_puredark_afw_failure("ngx_resources", error);
        return -1;
    }

    w3vr::puredark_afw::TextureDesc depth_source{};
    depth_source.texture = depth;
    depth_source.initial_state = depth_state;
    w3vr::puredark_afw::TextureDesc motion_source{};
    motion_source.texture = motion_vectors;
    motion_source.initial_state = motion_state;
    const D3D12_BOX depth_box{
        0, 0, 0, static_cast<UINT>(depth_desc.Width),
        depth_desc.Height, 1};
    const D3D12_BOX motion_box{
        0, 0, 0, static_cast<UINT>(motion_desc.Width),
        motion_desc.Height, 1};
    auto& motion_copy_destination = normalize_native_motion
        ? slot.motion_normalization_source
        : captured.motion_vectors;
    if (!g_puredark_afw_bridge->copy_texture(
            command_list, captured.depth, depth_source,
            depth_box, 0, 0, error) ||
        !g_puredark_afw_bridge->copy_texture(
            command_list, motion_copy_destination, motion_source,
            motion_box, 0, 0, error)) {
        slot.state = PuredarkAfwBundleState::Free;
        log_puredark_afw_failure("dlss_copy", error);
        return -1;
    }
    if (normalize_native_motion) {
        const auto depth_srv_format = [](DXGI_FORMAT format) {
            if (format == DXGI_FORMAT_R32G8X24_TYPELESS) {
                return DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS;
            }
            if (format == DXGI_FORMAT_R32_TYPELESS ||
                format == DXGI_FORMAT_D32_FLOAT) {
                return DXGI_FORMAT_R32_FLOAT;
            }
            return format;
        }(depth_desc.Format);
        // [FIX:AFW-NATIVE-MOTION-CONTRACT V1352 3/4] DLSS already contains
        // correct native/object vectors wherever depth is valid. Its exact
        // depth-zero population is centered camera motion, so the common
        // normalizer replaces only that population in a private RG16F input.
        if (!record_puredark_afw_motion_normalization_locked(
                command_list, bundle_slot, nullptr,
                captured.depth.texture, depth_srv_format,
                slot.motion_normalization_source.texture,
                motion_desc.Format, false, actual_clip_to_previous, 1,
                captured.motion_vectors, error)) {
            slot.state = PuredarkAfwBundleState::Free;
            log_puredark_afw_failure(
                "dlss_motion_contract", error);
            return -1;
        }
    }

    captured.camera = camera.camera;
    captured.render_views = camera.render_views;
    captured.render_views_valid = camera.render_views_valid;
    captured.exact_render_view = camera.exact_render_view;
    captured.exact_render_view_valid = camera.exact_render_view_valid;
    captured.pixel_projection = camera.pixel_projection;
    captured.streamline_constants = camera.streamline_constants;
    captured.streamline_constants_valid =
        camera.streamline_constants_valid;
    captured.motion_scale[0] = motion_scale_x *
        static_cast<float>(output_desc.Width) /
        static_cast<float>(motion_desc.Width);
    captured.motion_scale[1] = motion_scale_y *
        static_cast<float>(output_desc.Height) /
        static_cast<float>(motion_desc.Height);
    captured.pair_id = route_tag.pair_id;
    captured.generation = route_tag.generation;
    captured.eye = routed_eye;
    captured.valid = true;
    g_puredark_afw_recorded_candidates.fetch_add(
        1, std::memory_order_relaxed);
    if (take_bounded_log_slot(g_puredark_afw_capture_logs, 12)) {
        log_line(
            "V1352 PureDark AFW direct inputs pair=%llu eye=%u generation=%u depth=%llux%u:%u mvec=%llux%u:%u output=%llux%u:%u scale=%.6f,%.6f native_motion_normalized=%u",
            static_cast<unsigned long long>(route_tag.pair_id), routed_eye,
            route_tag.generation,
            static_cast<unsigned long long>(depth_desc.Width),
            depth_desc.Height, static_cast<unsigned>(depth_desc.Format),
            static_cast<unsigned long long>(motion_desc.Width),
            motion_desc.Height, static_cast<unsigned>(motion_desc.Format),
            static_cast<unsigned long long>(output_desc.Width),
            output_desc.Height, static_cast<unsigned>(output_desc.Format),
            captured.motion_scale[0], captured.motion_scale[1],
            normalize_native_motion ? 1u : 0u);
    }
    return static_cast<int32_t>(bundle_slot);
}

int32_t capture_puredark_afw_dlss_inputs(
    ID3D12GraphicsCommandList* command_list,
    const NVSDK_NGX_Parameter* parameters,
    uint32_t routed_eye) {
    if (parameters == nullptr) {
        return -1;
    }
    ID3D12Resource* depth{};
    ID3D12Resource* motion_vectors{};
    ID3D12Resource* output{};
    float motion_scale_x{};
    float motion_scale_y{};
    parameters->Get(NVSDK_NGX_Parameter_Depth, &depth);
    parameters->Get(
        NVSDK_NGX_Parameter_MotionVectors, &motion_vectors);
    parameters->Get(NVSDK_NGX_Parameter_Output, &output);
    parameters->Get(NVSDK_NGX_Parameter_MV_Scale_X, &motion_scale_x);
    parameters->Get(NVSDK_NGX_Parameter_MV_Scale_Y, &motion_scale_y);
    const auto tracked_state = [](uint32_t input_index) {
        const uint32_t state = g_ngx_input_states[input_index].load(
            std::memory_order_acquire);
        return state != UINT32_MAX
            ? static_cast<D3D12_RESOURCE_STATES>(state)
            : D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    };
    return capture_puredark_afw_dlss_inputs_from_resources(
        command_list,
        depth, tracked_state(1),
        motion_vectors, tracked_state(2),
        output, motion_scale_x, motion_scale_y, routed_eye);
}

bool initialize_puredark_afw_motion_pipeline() {
    std::call_once(g_puredark_afw_motion_pipeline_once, []() {
        if (g_d3d12_device == nullptr || !initialize_dxc()) {
            return;
        }
        // [FIX:AFW-NATIVE-MOTION-CONTRACT V1352 1/4] Both temporal backends
        // feed AFW the same previous-minus-current RG16F contract. TAAU's
        // RGBA16F sentinel pixels and DLSS's depth-zero/far-plane pixels still
        // carry centered camera motion even when geometry is native-ASym.
        // Preserve every valid geometry/object vector and reconstruct only
        // that population from the exact rebased temporal matrix.
        static constexpr char kShaderSource[] = R"(
Texture2D<float4> native_mvec : register(t0);
Texture2D<float> depth_texture : register(t1);
RWTexture2D<float2> normalized_mvec : register(u0);
cbuffer Parameters : register(b0) {
    row_major float4x4 actual_clip_to_previous;
    float2 inverse_extent;
    uint input_kind;
    uint reserved;
};
[numthreads(8, 8, 1)]
void main(uint3 dispatch_id : SV_DispatchThreadID) {
    uint width, height;
    native_mvec.GetDimensions(width, height);
    if (dispatch_id.x >= width || dispatch_id.y >= height) return;

    float4 native_motion = native_mvec.Load(int3(dispatch_id.xy, 0));
    float2 source_uv = (float2(dispatch_id.xy) + 0.5) * inverse_extent;
    float depth = depth_texture.Load(int3(dispatch_id.xy, 0));
    bool motion_finite = all(isfinite(native_motion.xy));
    if (input_kind == 0) {
        bool taau_native_valid = motion_finite &&
            native_motion.x < 2.0 && native_motion.y < 2.0;
        if (taau_native_valid) {
            // V12121: REDengine TAAU is current-minus-previous.
            normalized_mvec[dispatch_id.xy] = -native_motion.xy;
            return;
        }
    } else if (motion_finite && depth > 1e-7) {
        // DLSS already owns the validated previous-minus-current direction.
        // Depth-valid geometry includes object/skinning motion; never replace
        // it with camera-only reprojection.
        normalized_mvec[dispatch_id.xy] = native_motion.xy;
        return;
    }

    float4 clip = float4(
        source_uv.x * 2.0 - 1.0,
        1.0 - source_uv.y * 2.0,
        depth, 1.0);
    float4 previous = mul(clip, actual_clip_to_previous);
    if (!all(isfinite(previous)) || abs(previous.w) < 1e-6) {
        normalized_mvec[dispatch_id.xy] = 0.0;
        return;
    }
    float3 previous_ndc = previous.xyz / previous.w;
    float2 previous_uv = float2(
        previous_ndc.x * 0.5 + 0.5,
        previous_ndc.y * -0.5 + 0.5);
    normalized_mvec[dispatch_id.xy] = previous_uv - source_uv;
}
)";
        DxcBuffer source{kShaderSource, sizeof(kShaderSource) - 1, DXC_CP_UTF8};
        LPCWSTR arguments[] = {L"-E", L"main", L"-T", L"cs_6_0", L"-O3"};
        IDxcResult* result{};
        if (FAILED(g_dxc_compiler->Compile(
                &source, arguments, static_cast<UINT32>(std::size(arguments)),
                nullptr, IID_PPV_ARGS(&result))) || result == nullptr) {
            return;
        }
        HRESULT status{};
        result->GetStatus(&status);
        if (FAILED(status)) {
            IDxcBlobUtf8* errors{};
            result->GetOutput(DXC_OUT_ERRORS, IID_PPV_ARGS(&errors), nullptr);
            log_line(
                "V1352 AFW motion shader compile failed: %s",
                errors != nullptr ? errors->GetStringPointer() : "unknown");
            if (errors != nullptr) errors->Release();
            result->Release();
            return;
        }
        IDxcBlob* shader{};
        if (FAILED(result->GetOutput(
                DXC_OUT_OBJECT, IID_PPV_ARGS(&shader), nullptr)) ||
            shader == nullptr) {
            result->Release();
            return;
        }

        D3D12_DESCRIPTOR_RANGE ranges[2]{};
        ranges[0].RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        ranges[0].NumDescriptors = 2;
        ranges[0].BaseShaderRegister = 0;
        ranges[0].OffsetInDescriptorsFromTableStart =
            D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;
        ranges[1].RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_UAV;
        ranges[1].NumDescriptors = 1;
        ranges[1].BaseShaderRegister = 0;
        ranges[1].OffsetInDescriptorsFromTableStart =
            D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;
        D3D12_ROOT_PARAMETER parameters[3]{};
        parameters[0].ParameterType =
            D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        parameters[0].DescriptorTable = {1, &ranges[0]};
        parameters[0].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;
        parameters[1].ParameterType =
            D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        parameters[1].DescriptorTable = {1, &ranges[1]};
        parameters[1].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;
        parameters[2].ParameterType =
            D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
        parameters[2].Constants.ShaderRegister = 0;
        parameters[2].Constants.Num32BitValues = 20;
        parameters[2].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;
        D3D12_ROOT_SIGNATURE_DESC root_desc{};
        root_desc.NumParameters = static_cast<UINT>(std::size(parameters));
        root_desc.pParameters = parameters;
        ID3DBlob* serialized{};
        ID3DBlob* errors{};
        if (FAILED(D3D12SerializeRootSignature(
                &root_desc, D3D_ROOT_SIGNATURE_VERSION_1,
                &serialized, &errors))) {
            if (errors != nullptr) errors->Release();
            shader->Release();
            result->Release();
            return;
        }
        if (FAILED(g_d3d12_device->CreateRootSignature(
                0, serialized->GetBufferPointer(), serialized->GetBufferSize(),
                IID_PPV_ARGS(&g_puredark_afw_motion_root_signature)))) {
            serialized->Release();
            shader->Release();
            result->Release();
            return;
        }
        serialized->Release();
        D3D12_COMPUTE_PIPELINE_STATE_DESC pipeline_desc{};
        pipeline_desc.pRootSignature =
            g_puredark_afw_motion_root_signature;
        pipeline_desc.CS = {
            shader->GetBufferPointer(), shader->GetBufferSize()};
        const HRESULT pipeline_result =
            g_d3d12_device->CreateComputePipelineState(
                &pipeline_desc,
                IID_PPV_ARGS(&g_puredark_afw_motion_pipeline));
        shader->Release();
        result->Release();
        if (FAILED(pipeline_result)) {
            return;
        }
        g_puredark_afw_motion_descriptor_increment =
            g_d3d12_device->GetDescriptorHandleIncrementSize(
                D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
        log_line(
            "V1352 AFW exact-projection RG16F motion pipeline initialized");
    });
    return g_puredark_afw_motion_root_signature != nullptr &&
        g_puredark_afw_motion_pipeline != nullptr &&
        g_puredark_afw_motion_descriptor_increment != 0;
}

bool record_puredark_afw_motion_normalization_locked(
    ID3D12GraphicsCommandList* command_list,
    uint32_t bundle_slot,
    const TaauComputeBindingSnapshot* restore_snapshot,
    ID3D12Resource* depth,
    DXGI_FORMAT depth_format,
    ID3D12Resource* motion_vectors,
    DXGI_FORMAT motion_format,
    bool transition_motion_from_common,
    const w3vr::puredark_afw::Matrix4x4& actual_clip_to_previous,
    uint32_t input_kind,
    w3vr::puredark_afw::TextureDesc& destination,
    std::wstring& error) {
    // [FIX:STREAMLINE-AFW-NATIVE-RECORDING V1365 1/3]
    // [FIX:RENDERDOC-COMMAND-LIST-ENDPOINT V1544 1/3] Every operation in this
    // function is recorded through the trampoline belonging to the active
    // ExecuteCommandLists interception layer. That endpoint is native D3D12
    // normally and RenderDoc's D3D12 wrapper during capture. Public Streamline
    // and ReShade wrappers remain invalid recording targets.
    if (!command_list_is_recording_endpoint(command_list)) {
        error = L"AFW motion normalization requires a D3D12 recording endpoint";
        return false;
    }
    if (bundle_slot >= kPuredarkAfwBundleRingSize ||
        depth == nullptr || motion_vectors == nullptr ||
        destination.texture == nullptr ||
        (motion_format != DXGI_FORMAT_R16G16_FLOAT &&
            motion_format != DXGI_FORMAT_R16G16B16A16_FLOAT) ||
        depth_format == DXGI_FORMAT_UNKNOWN || input_kind > 1 ||
        (restore_snapshot != nullptr &&
            (restore_snapshot->cbv_srv_uav_heap == nullptr ||
                restore_snapshot->sampler_heap == nullptr ||
                restore_snapshot->compute_root_signature == nullptr ||
                restore_snapshot->pipeline_state == nullptr)) ||
        g_set_descriptor_heaps == nullptr ||
        g_set_compute_root_signature == nullptr ||
        g_set_pipeline_state == nullptr ||
        g_set_compute_root_descriptor_table == nullptr ||
        g_set_compute_root_32bit_constants == nullptr ||
        !initialize_puredark_afw_motion_pipeline()) {
        error = L"AFW normalized motion prerequisites are unavailable";
        return false;
    }

    const auto motion_desc = motion_vectors->GetDesc();
    const auto depth_desc = depth->GetDesc();
    const auto destination_desc = destination.texture->GetDesc();
    if (motion_desc.Width == 0 || motion_desc.Height == 0 ||
        depth_desc.Width != motion_desc.Width ||
        depth_desc.Height != motion_desc.Height ||
        destination_desc.Width != motion_desc.Width ||
        destination_desc.Height != motion_desc.Height ||
        destination_desc.Format != DXGI_FORMAT_R16G16_FLOAT) {
        error = L"AFW normalized motion extents or destination format differ";
        return false;
    }
    for (float value : actual_clip_to_previous.values) {
        if (!std::isfinite(value)) {
            error = L"AFW normalized temporal transform is non-finite";
            return false;
        }
    }

    auto& slot = g_puredark_afw_bundle_ring[bundle_slot];
    if (slot.motion_normalization_heap == nullptr) {
        D3D12_DESCRIPTOR_HEAP_DESC heap_desc{};
        heap_desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
        heap_desc.NumDescriptors = 3;
        heap_desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
        if (FAILED(g_d3d12_device->CreateDescriptorHeap(
                &heap_desc,
                IID_PPV_ARGS(&slot.motion_normalization_heap)))) {
            error = L"AFW normalized motion descriptor heap failed";
            return false;
        }
    }

    auto cpu = slot.motion_normalization_heap->GetCPUDescriptorHandleForHeapStart();
    D3D12_SHADER_RESOURCE_VIEW_DESC motion_srv{};
    motion_srv.Format = motion_format;
    motion_srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
    motion_srv.Shader4ComponentMapping =
        D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    motion_srv.Texture2D.MipLevels = 1;
    g_d3d12_device->CreateShaderResourceView(
        motion_vectors, &motion_srv, cpu);
    cpu.ptr += g_puredark_afw_motion_descriptor_increment;
    D3D12_SHADER_RESOURCE_VIEW_DESC depth_srv{};
    depth_srv.Format = depth_format;
    depth_srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
    depth_srv.Shader4ComponentMapping =
        D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    depth_srv.Texture2D.MipLevels = 1;
    g_d3d12_device->CreateShaderResourceView(depth, &depth_srv, cpu);
    cpu.ptr += g_puredark_afw_motion_descriptor_increment;
    D3D12_UNORDERED_ACCESS_VIEW_DESC output_uav{};
    output_uav.Format = DXGI_FORMAT_R16G16_FLOAT;
    output_uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
    g_d3d12_device->CreateUnorderedAccessView(
        destination.texture, nullptr, &output_uav, cpu);

    D3D12_RESOURCE_BARRIER to_compute[2]{};
    UINT barrier_count{};
    if (transition_motion_from_common) {
        auto& source_barrier = to_compute[barrier_count++];
        source_barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
        source_barrier.Transition.pResource = motion_vectors;
        source_barrier.Transition.Subresource =
            D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
        source_barrier.Transition.StateBefore = D3D12_RESOURCE_STATE_COMMON;
        source_barrier.Transition.StateAfter =
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    }
    auto& destination_barrier = to_compute[barrier_count++];
    destination_barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    destination_barrier.Transition.pResource = destination.texture;
    destination_barrier.Transition.Subresource =
        D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    destination_barrier.Transition.StateBefore =
        D3D12_RESOURCE_STATE_ALL_SHADER_RESOURCE;
    destination_barrier.Transition.StateAfter =
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
    command_list->ResourceBarrier(barrier_count, to_compute);

    std::array<uint32_t, 20> constants{};
    memcpy(
        constants.data(), actual_clip_to_previous.values,
        sizeof(actual_clip_to_previous.values));
    const float inverse_extent[2]{
        1.0f / static_cast<float>(motion_desc.Width),
        1.0f / static_cast<float>(motion_desc.Height)};
    memcpy(constants.data() + 16, inverse_extent, sizeof(inverse_extent));
    constants[18] = input_kind;
    ID3D12DescriptorHeap* normalization_heaps[]{
        slot.motion_normalization_heap};
    g_set_descriptor_heaps(command_list, 1, normalization_heaps);
    g_set_compute_root_signature(
        command_list, g_puredark_afw_motion_root_signature);
    g_set_pipeline_state(command_list, g_puredark_afw_motion_pipeline);
    auto gpu =
        slot.motion_normalization_heap->GetGPUDescriptorHandleForHeapStart();
    g_set_compute_root_descriptor_table(command_list, 0, gpu);
    gpu.ptr += static_cast<UINT64>(2) *
        g_puredark_afw_motion_descriptor_increment;
    g_set_compute_root_descriptor_table(command_list, 1, gpu);
    g_set_compute_root_32bit_constants(
        command_list, 2, static_cast<UINT>(constants.size()),
        constants.data(), 0);
    g_dispatch(
        command_list,
        static_cast<UINT>((motion_desc.Width + 7) / 8),
        static_cast<UINT>((motion_desc.Height + 7) / 8), 1);

    D3D12_RESOURCE_BARRIER uav_barrier{};
    uav_barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
    uav_barrier.UAV.pResource = destination.texture;
    command_list->ResourceBarrier(1, &uav_barrier);
    for (UINT index = 0; index < barrier_count; ++index) {
        std::swap(
            to_compute[index].Transition.StateBefore,
            to_compute[index].Transition.StateAfter);
    }
    command_list->ResourceBarrier(barrier_count, to_compute);

    if (restore_snapshot != nullptr) {
        ID3D12DescriptorHeap* original_heaps[]{
            restore_snapshot->cbv_srv_uav_heap,
            restore_snapshot->sampler_heap};
        g_set_descriptor_heaps(
            command_list, static_cast<UINT>(std::size(original_heaps)),
            original_heaps);
        g_set_compute_root_signature(
            command_list, restore_snapshot->compute_root_signature);
        g_set_pipeline_state(command_list, restore_snapshot->pipeline_state);
        for (UINT root = 0;
             root < restore_snapshot->compute_tables.size(); ++root) {
            g_set_compute_root_descriptor_table(
                command_list, root,
                restore_snapshot->compute_tables[root]);
        }
    }
    error.clear();
    return true;
}

// [FEATURE:PUREDARK-AFW-MODE3-TAAU V12055 2/8] Freeze TAAU's exact depth
// and normalized motion input on this resolve command list. ExecuteCommandLists
// remains the immutable publication boundary.
bool capture_puredark_afw_mode3_taau_inputs(
    ID3D12GraphicsCommandList* command_list,
    const TaauComputeBindingSnapshot& snapshot,
    const ResourceDescriptorInfo& depth,
    const ResourceDescriptorInfo& motion_vectors,
    const std::array<uint8_t, kTaauPrivateCb10Bytes>& cb_data,
    const D3D12_RESOURCE_DESC& output_desc,
    uint32_t generation,
    uint32_t eye,
    uint64_t pair_id,
    const std::array<XrView, 2>& exact_render_views,
    bool exact_render_views_valid,
    w3vr::mode3_transport::AfwPixelProjection pixel_projection) {
    RouteFlightOutcomeScope route_flight{
        w3vr::route_flight::EventCode::AfwCapture,
        static_cast<int32_t>(eye), pair_id, generation, 1u};
    const bool route_configured =
        puredark_afw_mode3_aer_taau_route_configured();
    const uint32_t current_generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    const int menu_state =
        g_engine_menu_state.load(std::memory_order_relaxed);
    const bool cinema_active =
        g_cinema_mode_active.load(std::memory_order_relaxed);
    const bool loading_active =
        g_engine_loading_screen_video_active.load(
            std::memory_order_acquire);
    const bool automatic_full_vr_active =
        !g_force_mono_cinema.load(std::memory_order_relaxed) &&
        g_config.cinema_full_vr &&
        g_automatic_full_vr_camera_active.load(std::memory_order_acquire);
    const bool gameplay_capture_allowed =
        w3vr::mode3_transport::afw_gameplay_capture_allowed(
            route_configured, menu_state, cinema_active,
            loading_active, automatic_full_vr_active);
    if (!gameplay_capture_allowed || command_list == nullptr ||
        depth.resource == nullptr || motion_vectors.resource == nullptr ||
        eye > 1 || pair_id == 0 || pair_id == UINT64_MAX ||
        generation != current_generation || !exact_render_views_valid ||
        pixel_projection ==
            w3vr::mode3_transport::AfwPixelProjection::Invalid) {
        return false;
    }
    route_flight.advance(
        2, (exact_render_views_valid ? 0x02u : 0u) |
            (gameplay_capture_allowed ? 0x04u : 0u),
        current_generation, static_cast<uint32_t>(menu_state),
        (cinema_active ? 0x01u : 0u) |
            (loading_active ? 0x02u : 0u));

    const auto depth_desc = depth.resource->GetDesc();
    const auto motion_desc = motion_vectors.resource->GetDesc();
    if (depth_desc.Width == 0 || depth_desc.Height == 0 ||
        motion_desc.Width == 0 || motion_desc.Height == 0 ||
        output_desc.Width == 0 || output_desc.Height == 0) {
        log_puredark_afw_failure(
            "taau_producer_extent", L"TAAU producer extent is invalid");
        return false;
    }

    std::scoped_lock lock{g_puredark_afw_mutex};

    // A replay of the same resolve must not consume another camera producer,
    // allocate another slot or replace its already submitted authority.
    for (const auto& existing : g_puredark_afw_bundle_ring) {
        if (existing.state != PuredarkAfwBundleState::Free &&
            existing.input.valid && existing.input.eye == eye &&
            existing.input.pair_id == pair_id &&
            existing.input.generation == generation) {
            route_flight.succeed(3, 0x08u);
            return true;
        }
    }

    // [FIX:PUREDARK-AFW-TAAU-STRICT-CAMERA-FIFO V1298 2/3] Consume exactly
    // the oldest raw producer. The resolve matrix validates that ordered join;
    // it never selects another entry from the queue.
    PuredarkAfwStreamlineCameraSnapshot raw_camera{};
    bool raw_available{};
    if (!g_puredark_afw_streamline_camera_history.empty()) {
        raw_camera = g_puredark_afw_streamline_camera_history.front();
        raw_available = true;
    }
    constexpr float kMaximumRawCameraMatrixError = 0.05f;
    const auto* resolve_matrix = reinterpret_cast<const float*>(
        cb_data.data() + 6 * 16);
    float matrix_error{};
    if (raw_available) {
        for (size_t index = 0; index < 16; ++index) {
            matrix_error += fabsf(raw_camera.constants[48 + index] -
                resolve_matrix[index]);
        }
    }
    const bool matrix_valid = raw_available &&
        std::isfinite(matrix_error) &&
        matrix_error <= kMaximumRawCameraMatrixError;
    const auto fifo_action =
        w3vr::taau_submission::decide_strict_raw_camera_fifo_action(
            generation, eye, raw_available, raw_camera.valid,
            raw_camera.generation, raw_camera.eye, matrix_valid);
    // F3 route-flight event-specific flag: the V1321 phase barrier retained
    // an otherwise-valid opposite-eye front for the next alternating resolve.
    constexpr uint32_t kRouteFlightTaauAfwPhaseWait = 0x100u;
    const bool fifo_phase_wait = fifo_action ==
        w3vr::taau_submission::StrictRawCameraFifoAction::Wait;
    const bool fifo_identity_valid = fifo_action ==
        w3vr::taau_submission::StrictRawCameraFifoAction::Consume;

    PuredarkAfwCameraSnapshot recovered_camera{};
    std::wstring recovery_error;
    float baseline =
        g_runtime_eye_baseline_m.load(std::memory_order_relaxed);
    if (!std::isfinite(baseline) || baseline < 0.04f ||
        baseline > 0.10f) {
        baseline = std::fabs(g_config.engine_factory_stereo_offset);
    }
    bool recovered = fifo_identity_valid && exact_render_views_valid &&
        w3vr::puredark_afw::build_camera_data_from_streamline(
            raw_camera.constants.data(), raw_camera.constants.size(), eye,
            baseline, recovered_camera.camera, recovery_error);
    w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor
        source_projection{};
    w3vr::openxr_eye_geometry::AsymmetricProjectionDescriptor
        destination_projection{};
    if (recovered && pixel_projection ==
            w3vr::mode3_transport::AfwPixelProjection::NativeAsymmetric) {
        // [FIX:AER-AFW-EXACT-NATIVE-PROJECTION V1350 2/4] TAAU's strict
        // raw-camera FIFO carries the shared-envelope Streamline projection.
        // Its exact resolve join owns both frozen native FOVs, so rebuild the
        // complete evaluator projection before publishing the immutable
        // bundle. Symmetric producers remain byte-for-byte unchanged.
        recovered = rebuild_puredark_afw_native_projection_pair(
            exact_render_views, eye, recovered_camera.camera,
            source_projection, destination_projection, recovery_error);
        if (recovered && g_config.runtime_diagnostics) {
            static std::atomic<uint32_t> projection_logs{};
            if (take_bounded_log_slot(projection_logs, 32)) {
                log_line(
                    "V1350 AFW TAAU exact native camera pair=%llu source_eye=%u destination_eye=%u source_span=%.9g,%.9g source_scale_center=%.9g,%.9g,%.9g,%.9g destination_span=%.9g,%.9g destination_scale_center=%.9g,%.9g,%.9g,%.9g baseline=%.9g authority=full_frame_frozen_pair",
                    static_cast<unsigned long long>(pair_id), eye, 1u - eye,
                    source_projection.horizontal_tangent_span,
                    source_projection.vertical_tangent_span,
                    recovered_camera.camera.source_view_to_clip.values[0],
                    recovered_camera.camera.source_view_to_clip.values[5],
                    source_projection.center_ndc_x,
                    source_projection.center_ndc_y,
                    destination_projection.horizontal_tangent_span,
                    destination_projection.vertical_tangent_span,
                    recovered_camera.camera.destination_view_to_clip.values[0],
                    recovered_camera.camera.destination_view_to_clip.values[5],
                    destination_projection.center_ndc_x,
                    destination_projection.center_ndc_y,
                    baseline);
            }
        }
    }
    w3vr::puredark_afw::Matrix4x4 actual_clip_to_previous{};
    memcpy(
        actual_clip_to_previous.values, cb_data.data() + 6 * 16,
        sizeof(actual_clip_to_previous.values));
    if (recovered && pixel_projection ==
            w3vr::mode3_transport::AfwPixelProjection::NativeAsymmetric) {
        w3vr::puredark_afw::Matrix4x4 centered_projection{};
        memcpy(
            centered_projection.values, raw_camera.constants.data(),
            sizeof(centered_projection.values));
        w3vr::puredark_afw::Matrix4x4 centered_clip_to_previous =
            actual_clip_to_previous;
        // [FIX:AFW-NATIVE-MOTION-CONTRACT V1352 2/4] The CB10 transform owns
        // the centered temporal coordinate system. Express that same time
        // delta in the actual source-eye tangent space before reconstructing
        // only TAAU's sentinel population.
        recovered = w3vr::puredark_afw::rebase_clip_to_previous_projection(
            centered_projection,
            recovered_camera.camera.source_view_to_clip,
            centered_clip_to_previous, actual_clip_to_previous,
            recovery_error);
    }
    route_flight.set_previous(raw_camera.capture_present);
    route_flight.advance(
        4, (raw_available ? 0x02u : 0u) |
            (fifo_identity_valid ? 0x04u : 0u) |
            (recovered ? 0x08u : 0u) |
            (fifo_phase_wait ? kRouteFlightTaauAfwPhaseWait : 0u),
        raw_camera.eye, raw_camera.generation,
        static_cast<uint32_t>(
            g_puredark_afw_streamline_camera_history.size()));
    if (fifo_phase_wait) {
        return false;
    }
    if (!recovered) {
        // A same-eye invalid matrix, stale generation or malformed payload can
        // never become valid later. Only those hard failures revoke the queue;
        // opposite-eye phase waits returned above without consuming the front.
        g_puredark_afw_streamline_camera_history.clear();
        static std::atomic<uint64_t> fifo_failure_count{};
        const uint64_t count = fifo_failure_count.fetch_add(
            1, std::memory_order_relaxed) + 1;
        if (g_config.runtime_diagnostics &&
            (count <= 16 || count % 120 == 0)) {
            log_line(
                "V1298 AFW TAAU strict camera FIFO rejected count=%llu present=%llu pair=%llu expected_eye=%u raw=%u raw_eye=%u expected_generation=%u raw_generation=%u sequence=%llu token=%u viewport=%u matrix_error=%.7f views=%u detail=%ls",
                static_cast<unsigned long long>(count),
                static_cast<unsigned long long>(
                    g_present_count.load(std::memory_order_relaxed)),
                static_cast<unsigned long long>(pair_id), eye,
                raw_available ? 1u : 0u, raw_camera.eye,
                generation, raw_camera.generation,
                static_cast<unsigned long long>(
                    raw_camera.sequence),
                raw_camera.frame_token, raw_camera.viewport, matrix_error,
                exact_render_views_valid ? 1u : 0u,
                recovery_error.c_str());
        }
        return false;
    }
    // Validation succeeded while the mutex still protects the same front.
    // This is the only point at which that producer leaves the FIFO.
    g_puredark_afw_streamline_camera_history.pop_front();
    recovered_camera.render_views = exact_render_views;
    recovered_camera.render_views_valid = true;
    recovered_camera.exact_render_view = exact_render_views[eye];
    recovered_camera.exact_render_view_valid = true;
    recovered_camera.capture_present = raw_camera.capture_present;
    recovered_camera.pair_id = pair_id;
    recovered_camera.generation = generation;
    recovered_camera.eye = eye;
    recovered_camera.pixel_projection = pixel_projection;
    recovered_camera.valid = true;
    const PuredarkAfwCameraSnapshot* camera_authority = &recovered_camera;

    static std::atomic<uint64_t> fifo_join_count{};
    const uint64_t fifo_count = fifo_join_count.fetch_add(
        1, std::memory_order_relaxed) + 1;
    if (g_config.runtime_diagnostics &&
        (fifo_count <= 16 || fifo_count % 240 == 0)) {
        const uint64_t present =
            g_present_count.load(std::memory_order_relaxed);
        const uint64_t age = raw_camera.capture_present <= present
            ? present - raw_camera.capture_present
            : UINT64_MAX;
        log_line(
            "V1298 AFW TAAU strict camera FIFO joined count=%llu present=%llu pair=%llu eye=%u sequence=%llu token=%u viewport=%u raw_present=%llu age=%llu matrix_error=%.7f remaining=%zu",
            static_cast<unsigned long long>(fifo_count),
            static_cast<unsigned long long>(present),
            static_cast<unsigned long long>(pair_id), eye,
            static_cast<unsigned long long>(raw_camera.sequence),
            raw_camera.frame_token, raw_camera.viewport,
            static_cast<unsigned long long>(raw_camera.capture_present),
            static_cast<unsigned long long>(age), matrix_error,
            g_puredark_afw_streamline_camera_history.size());
    }

    uint32_t bundle_slot = UINT32_MAX;
    const uint64_t completed_fence = g_xr_fence != nullptr
        ? g_xr_fence->GetCompletedValue()
        : 0;
    for (size_t attempt = 0; attempt < kPuredarkAfwBundleRingSize;
         ++attempt) {
        const uint32_t candidate = static_cast<uint32_t>(
            (g_puredark_afw_bundle_write_cursor + attempt) %
            kPuredarkAfwBundleRingSize);
        auto& candidate_slot = g_puredark_afw_bundle_ring[candidate];
        if (candidate_slot.state == PuredarkAfwBundleState::InFlight &&
            candidate_slot.retire_fence != 0 &&
            completed_fence >= candidate_slot.retire_fence) {
            candidate_slot.state = PuredarkAfwBundleState::Free;
            candidate_slot.input.valid = false;
            candidate_slot.submission_serial = 0;
            candidate_slot.ready_present = UINT64_MAX;
            candidate_slot.producer_queue_fence = nullptr;
            candidate_slot.producer_queue_fence_value = 0;
            candidate_slot.retire_fence = 0;
        }
        if (candidate_slot.state == PuredarkAfwBundleState::Free) {
            bundle_slot = candidate;
            g_puredark_afw_bundle_write_cursor =
                (candidate + 1) % kPuredarkAfwBundleRingSize;
            break;
        }
    }
    if (bundle_slot >= kPuredarkAfwBundleRingSize) {
        g_puredark_afw_slot_starvation.fetch_add(
            1, std::memory_order_relaxed);
        log_puredark_afw_failure(
            "taau_producer_ring", L"no retired TAAU producer bundle slot");
        return false;
    }
    route_flight.advance(
        5, 0, bundle_slot, static_cast<uint32_t>(completed_fence),
        static_cast<uint32_t>(g_puredark_afw_bundle_write_cursor));

    auto& slot = g_puredark_afw_bundle_ring[bundle_slot];
    auto retained_depth = slot.input.depth;
    auto retained_motion_vectors = slot.input.motion_vectors;
    slot.input = {};
    slot.input.depth = retained_depth;
    slot.input.motion_vectors = retained_motion_vectors;
    slot.state = PuredarkAfwBundleState::Recording;
    slot.route_epoch =
        g_puredark_afw_route_epoch.load(std::memory_order_acquire);
    slot.submission_serial = 0;
    slot.ready_present = UINT64_MAX;
    slot.producer_queue_fence = nullptr;
    slot.producer_queue_fence_value = 0;
    slot.retire_fence = 0;
    auto& captured = slot.input;
    std::wstring error;
    // [FIX:PUREDARK-AFW-TAAU-RG16F-ALLOCATION V12112 1/1] V12111 built the
    // intended RG16F UAV descriptor over an accidentally retained RGBA16F
    // resource because this format override landed in the dormant No-AA
    // producer. Allocate the private TAAU AFW surface with its real view format.
    auto normalized_motion_desc = motion_desc;
    normalized_motion_desc.Format = DXGI_FORMAT_R16G16_FLOAT;
    if (!ensure_puredark_afw_device_locked(error) ||
        !ensure_puredark_afw_capture_texture_locked(
            depth_desc, captured.depth, error) ||
        !ensure_puredark_afw_capture_texture_locked(
            normalized_motion_desc, captured.motion_vectors, error)) {
        slot.state = PuredarkAfwBundleState::Free;
        log_puredark_afw_failure("taau_producer_resources", error);
        return false;
    }
    route_flight.advance(
        6, 0, bundle_slot, static_cast<uint32_t>(depth_desc.Width),
        depth_desc.Height);

    w3vr::puredark_afw::TextureDesc depth_source{};
    depth_source.texture = depth.resource;
    depth_source.initial_state =
        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    const D3D12_BOX depth_box{
        0, 0, 0, static_cast<UINT>(depth_desc.Width),
        depth_desc.Height, 1};
    if (!g_puredark_afw_bridge->copy_texture(
            command_list, captured.depth, depth_source,
            depth_box, 0, 0, error)) {
        slot.state = PuredarkAfwBundleState::Free;
        log_puredark_afw_failure("taau_producer_copy", error);
        return false;
    }
    if (!record_puredark_afw_motion_normalization_locked(
            command_list, bundle_slot, &snapshot,
            captured.depth.texture, depth.format,
            motion_vectors.resource, motion_vectors.format, true,
            actual_clip_to_previous, 0,
            captured.motion_vectors, error)) {
        slot.state = PuredarkAfwBundleState::Free;
        log_puredark_afw_failure(
            "taau_producer_motion_contract", error);
        return false;
    }
    route_flight.advance(
        7, 0, bundle_slot, static_cast<uint32_t>(motion_desc.Width),
        motion_desc.Height);

    captured.camera = camera_authority->camera;
    captured.render_views = camera_authority->render_views;
    captured.render_views_valid = true;
    captured.exact_render_view = camera_authority->exact_render_view;
    captured.exact_render_view_valid = true;
    captured.streamline_constants = raw_camera.constants;
    captured.streamline_constants_valid = raw_camera.valid;
    // PureDark beta.5's official non-DLSS path scales normalized motion by
    // final output pixels. TAAU's Streamline constants carry 1,1 because NGX
    // is absent; propagating those values made valid motion effectively zero.
    captured.motion_scale[0] = static_cast<float>(output_desc.Width);
    captured.motion_scale[1] = static_cast<float>(output_desc.Height);
    captured.pair_id = pair_id;
    captured.generation = generation;
    captured.eye = eye;
    captured.pixel_projection = camera_authority->pixel_projection;
    captured.valid = true;
    slot.state = PuredarkAfwBundleState::PendingSubmission;

    PuredarkAfwPendingSubmission submission{};
    submission.bundle_slot = bundle_slot;
    submission.generation = generation;
    submission.eye = eye;
    submission.pair_id = pair_id;
    submission.route_epoch = slot.route_epoch;
    submission.exact_identity = true;
    submission.bundle_ready = true;
    g_puredark_afw_pending_submissions[
        static_cast<ID3D12CommandList*>(command_list)].push_back(submission);
    g_puredark_afw_pending_submission_ready.store(
        true, std::memory_order_release);
    g_puredark_afw_recorded_candidates.fetch_add(
        1, std::memory_order_relaxed);
    if (take_bounded_log_slot(g_puredark_afw_capture_logs, 24)) {
        log_line(
            "V12114 AFW TAAU producer bundle slot=%u pair=%llu eye=%u generation=%u depth=%llux%u:%u:0x%X native_mvec=%llux%u:%u normalized_mvec=%u:0x%X output=%llux%u:%u scale=%.6f,%.6f present=%llu",
            bundle_slot, static_cast<unsigned long long>(pair_id), eye,
            generation,
            static_cast<unsigned long long>(depth_desc.Width),
            depth_desc.Height, static_cast<unsigned>(depth.format),
            static_cast<unsigned>(depth_source.initial_state),
            static_cast<unsigned long long>(motion_desc.Width),
            motion_desc.Height, static_cast<unsigned>(motion_vectors.format),
            static_cast<unsigned>(DXGI_FORMAT_R16G16_FLOAT),
            static_cast<unsigned>(captured.motion_vectors.initial_state),
            static_cast<unsigned long long>(output_desc.Width),
            output_desc.Height, static_cast<unsigned>(output_desc.Format),
            captured.motion_scale[0], captured.motion_scale[1],
            static_cast<unsigned long long>(
                g_present_count.load(std::memory_order_relaxed)));
    }
    route_flight.succeed(8, 0x40u);
    return true;
}

// [FIX:STREAMLINE-COMMAND-LIST-UNWRAP 1/3] Streamline's interposer can hand the
// application wrapper objects rather than the D3D12 runtime's own. When it
// does, slEvaluateFeature receives an sl.interposer.dll-owned command list while
// the real ID3D12CommandQueue::ExecuteCommandLists this proxy hooks receives the
// underlying D3D12Core.dll object. The AFW producer transport joins a producer
// to its presentation by exact command-list pointer, so on such a runtime the
// key registered at capture can never match the key seen at submission: every
// bundle strands in PendingSubmission and the six-slot ring starves for the rest
// of the session.
//
// Recover the underlying object instead of changing the transport contract.
// The scan is self-validating -- a candidate is accepted only if its own vtable
// belongs to the D3D12 runtime -- so it does not depend on a hardcoded
// Streamline struct layout, and a runtime that hands over unwrapped lists (or
// any layout this fails to decode) keeps exactly the present behaviour.
HMODULE module_owning_address(const void* address);

bool address_is_readable(const void* address, size_t bytes) {
    if (address == nullptr) {
        return false;
    }
    MEMORY_BASIC_INFORMATION info{};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 ||
        info.State != MEM_COMMIT) {
        return false;
    }
    constexpr DWORD readable =
        PAGE_READONLY | PAGE_READWRITE | PAGE_WRITECOPY |
        PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE |
        PAGE_EXECUTE_WRITECOPY;
    if ((info.Protect & readable) == 0 ||
        (info.Protect & PAGE_GUARD) != 0) {
        return false;
    }
    const auto* start = static_cast<const uint8_t*>(info.BaseAddress);
    const auto* end = start + info.RegionSize;
    const auto* want = static_cast<const uint8_t*>(address) + bytes;
    return want <= end;
}

bool module_base_name_is(HMODULE module, const wchar_t* expected) {
    if (module == nullptr) {
        return false;
    }
    wchar_t path[MAX_PATH]{};
    if (GetModuleFileNameW(module, path, MAX_PATH) == 0) {
        return false;
    }
    const wchar_t* slash = wcsrchr(path, 0x5C);
    const wchar_t* base = slash != nullptr ? slash + 1 : path;
    return _wcsicmp(base, expected) == 0;
}

HMODULE vtable_owner_of(const void* object) {
    if (!address_is_readable(object, sizeof(void*))) {
        return nullptr;
    }
    void* const* vtable = *reinterpret_cast<void* const* const*>(object);
    if (!address_is_readable(vtable, sizeof(void*))) {
        return nullptr;
    }
    return module_owning_address(vtable[0]);
}

bool command_list_is_recording_endpoint(const void* object) {
    const HMODULE owner = vtable_owner_of(object);
    return module_base_name_is(owner, L"D3D12Core.dll") ||
        module_base_name_is(owner, L"d3d12.dll") ||
        module_base_name_is(owner, L"renderdoc.dll");
}

w3vr::command_list_identity::Owner classify_command_list_owner(
    const IUnknown* object) {
    using w3vr::command_list_identity::Owner;
    const HMODULE owner = vtable_owner_of(object);
    if (module_base_name_is(owner, L"D3D12Core.dll") ||
        module_base_name_is(owner, L"d3d12.dll")) {
        return Owner::Native;
    }
    if (module_base_name_is(owner, L"sl.interposer.dll")) {
        return Owner::Streamline;
    }
    if (module_base_name_is(owner, L"ReShade64.dll")) {
        return Owner::ReShade;
    }
    if (module_base_name_is(owner, L"renderdoc.dll")) {
        return Owner::RenderDoc;
    }
    return Owner::Unknown;
}

// [FIX:NESTED-COMMAND-LIST-IDENTITY V1532 1/3]
// [FIX:RENDERDOC-COMMAND-LIST-ENDPOINT V1544 2/3]
ID3D12GraphicsCommandList* resolve_execution_command_list(
    ID3D12GraphicsCommandList* command_list) {
    using w3vr::command_list_identity::Owner;
    if (command_list == nullptr) {
        return nullptr;
    }
    const auto owner = classify_command_list_owner(command_list);
    // Native lists and unrelated integrations are outside the proxy rewrite.
    // Unknown objects encountered INSIDE a recognized chain are rejected.
    if (owner == Owner::Native || owner == Owner::RenderDoc ||
        owner == Owner::Unknown) {
        return command_list;
    }
    const auto resolved = w3vr::command_list_identity::resolve(
        command_list, classify_command_list_owner);
    if (resolved.endpoint == nullptr) {
        static std::atomic<uint32_t> failure_logs{};
        if (take_bounded_log_slot(failure_logs, 8)) {
            log_line("V1532 command-list identity rejected wrapper=%p depth=%u reason=%u",
                command_list, resolved.wrappers,
                static_cast<unsigned>(resolved.failure));
        }
        return nullptr;
    }
    // [FIX:RENDERDOC-COMMAND-LIST-ENDPOINT V1544 3/3] The Streamline
    // producer key must terminate at the same RenderDoc wrapper intercepted by
    // ExecuteCommandLists. Record this once without enabling broad logging.
    if (g_config.renderdoc_capture_enabled &&
        g_config.renderdoc_streamline_device_bridge &&
        classify_command_list_owner(resolved.endpoint) == Owner::RenderDoc) {
        static std::atomic<bool> renderdoc_endpoint_logged{};
        if (!renderdoc_endpoint_logged.exchange(true)) {
            w3vr::minimal_xr_log::write(
                "V1544_RENDERDOC_COMMAND_ENDPOINT",
                g_present_count.load(std::memory_order_relaxed),
                resolved.wrappers,
                reinterpret_cast<uintptr_t>(resolved.endpoint), 0);
        }
    }
    static std::atomic<uint32_t> success_logs{};
    if (take_bounded_log_slot(success_logs, 8)) {
        log_line("V1544 command-list identity resolved owner=%s wrapper=%p endpoint=%p depth=%u",
            owner == Owner::Streamline ? "Streamline" : "ReShade",
            command_list, resolved.endpoint, resolved.wrappers);
    }
    return resolved.endpoint;
}

void finalize_puredark_afw_dlss_submission(
    ID3D12GraphicsCommandList* wrapped_command_list,
    int32_t bundle_slot,
    NVSDK_NGX_Result result) {
    // [FIX:STREAMLINE-COMMAND-LIST-UNWRAP 3/3] The producer must be registered
    // under the pointer ExecuteCommandLists will actually present, not the
    // interposer wrapper the temporal callback was handed. Native D3D12 and
    // RenderDoc endpoints remain unchanged; only outer wrappers are resolved.
    ID3D12GraphicsCommandList* const command_list =
        resolve_execution_command_list(wrapped_command_list);
    if (!puredark_afw_dlss_route_active() || command_list == nullptr) {
        return;
    }

    EngineFrameTag route_tag{};
    const uint32_t routed_eye = g_streamline_dlss_route_tag_valid
        ? g_streamline_dlss_route_tag.eye
        : (g_engine_render_eye >= 0 && g_engine_render_eye <= 1
            ? static_cast<uint32_t>(g_engine_render_eye)
            : UINT32_MAX);
    const bool exact_identity = routed_eye <= 1 &&
        current_puredark_afw_direct_route_tag(routed_eye, route_tag);
    const uint64_t route_epoch =
        g_puredark_afw_route_epoch.load(std::memory_order_acquire);
    RouteFlightOutcomeScope route_flight{
        w3vr::route_flight::EventCode::AfwFinalize,
        static_cast<int32_t>(routed_eye),
        exact_identity ? route_tag.pair_id : 0,
        exact_identity ? route_tag.generation
                       : g_streamline_capture_generation.load(
                             std::memory_order_relaxed),
        static_cast<uint32_t>(bundle_slot)};
    std::scoped_lock lock{g_puredark_afw_mutex};
    PuredarkAfwPendingSubmission submission{};
    submission.exact_identity = exact_identity;
    submission.generation = exact_identity ? route_tag.generation : 0;
    submission.eye = exact_identity ? route_tag.eye : UINT32_MAX;
    submission.pair_id = exact_identity ? route_tag.pair_id : 0;
    submission.route_epoch = route_epoch;

    bool bundle_matches{};
    if (bundle_slot >= 0 && static_cast<size_t>(bundle_slot) <
            kPuredarkAfwBundleRingSize) {
        auto& slot = g_puredark_afw_bundle_ring[
            static_cast<size_t>(bundle_slot)];
        // V1224: NGX Output is an intermediate render target, not the final
        // REDengine color presented by DXGI. Keep the exact identity/depth/MV/
        // camera ticket, but do not transition or copy that intermediate.
        // Present supplies the final backbuffer after this slot's producer
        // submission has been ordered by the queue/fence contract.
        bundle_matches =
            result == NVSDK_NGX_Result_Success && exact_identity &&
            slot.state == PuredarkAfwBundleState::Recording &&
            slot.input.valid &&
            slot.input.eye == route_tag.eye &&
            slot.input.pair_id == route_tag.pair_id &&
            slot.input.generation == route_tag.generation &&
            slot.route_epoch == submission.route_epoch;
        if (bundle_matches) {
            slot.state = PuredarkAfwBundleState::PendingSubmission;
            submission.bundle_slot = static_cast<uint32_t>(bundle_slot);
            submission.bundle_ready = true;
        } else if (slot.state == PuredarkAfwBundleState::Recording) {
            slot.state = PuredarkAfwBundleState::Free;
            slot.input.valid = false;
        }
    }
    route_flight.advance(
        2, (exact_identity ? 0x02u : 0u) |
            (bundle_matches ? 0x04u : 0u),
        static_cast<uint32_t>(result), static_cast<uint32_t>(route_epoch),
        submission.bundle_ready ? 1u : 0u);

    if (result != NVSDK_NGX_Result_Success) {
        const uint32_t flags =
            (exact_identity ? 0x01u : 0u) |
            (bundle_matches ? 0x02u : 0u);
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwFinalize,
            submission.eye, submission.pair_id, 0,
            w3vr::rt_flight::RejectReason::Evaluate,
            flags, 0, 0,
            static_cast<uint32_t>(bundle_slot),
            static_cast<uint32_t>(result),
            submission.generation, route_epoch);
        return;
    }

    // V12099: the Mode-3 temporal FIFO is resource-backed. An NGX evaluation
    // that did not capture a real bundle must not create a UINT32_MAX pending
    // entry and cannot invalidate any older immutable FIFO element. Legacy
    // newest-only routes retain their historical invalidation event below.
    if (puredark_afw_mode3_aer_common_transport_configured() &&
        !submission.bundle_ready) {
        const uint32_t flags =
            (exact_identity ? 0x01u : 0u) |
            0x20u;
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwFinalize,
            submission.eye, submission.pair_id, 0,
            w3vr::rt_flight::RejectReason::Bundle,
            flags, 0, 0,
            static_cast<uint32_t>(bundle_slot),
            static_cast<uint32_t>(result),
            submission.generation, route_epoch);
        return;
    }

    // Record an invalid producer event as well. Once that command list is
    // submitted its newer pixels supersede any older ready tag, so Present
    // must hold the last complete AFW pair instead of evaluating stale inputs
    // against the new backbuffer.
    g_puredark_afw_pending_submissions[
        static_cast<ID3D12CommandList*>(command_list)].push_back(submission);
    g_puredark_afw_pending_submission_ready.store(
        true, std::memory_order_release);
    const uint32_t flags =
        (exact_identity ? 0x01u : 0u) |
        (bundle_matches ? 0x02u : 0u) |
        0x20u | 0x40u;
    record_rt_flight(
        w3vr::rt_flight::EventCode::AfwFinalize,
        submission.eye, submission.pair_id, 0,
        w3vr::rt_flight::RejectReason::None,
        flags, 0, 0,
        submission.bundle_slot, static_cast<uint32_t>(result),
        submission.generation, route_epoch);
    route_flight.succeed(3, 0x40u);
}

void finalize_dlss_cache_submission(
    ID3D12GraphicsCommandList* wrapped_command_list,
    NVSDK_NGX_Result result) {
    // [FIX:STREAMLINE-COMMAND-LIST-UNWRAP 6/6] This is the gate the Mode-3 AFW
    // consumer sits behind: peek_mode3_temporal_cache_submission must find the
    // cache entry under the submitted pointer or no producer is ever consumed.
    ID3D12GraphicsCommandList* const command_list =
        resolve_execution_command_list(wrapped_command_list);
    if (!dlss_submitted_cache_route_active() ||
        command_list == nullptr || result != NVSDK_NGX_Result_Success ||
        !g_streamline_dlss_route_tag_valid) {
        return;
    }

    const EngineFrameTag tag = g_streamline_dlss_route_tag;
    const uint32_t generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    if (!tag.task_provenance_valid || tag.eye > 1 || tag.pair_id == 0 ||
        tag.pair_id == UINT64_MAX || tag.generation != generation) {
        return;
    }

    std::scoped_lock lock{g_dlss_submission_mutex};
    g_dlss_pending_submissions[command_list].push_back(tag);
    g_dlss_pending_submission_ready.store(
        true, std::memory_order_release);
}

bool lookup_dlss_recording_producer(
    ID3D12GraphicsCommandList* command_list,
    EngineFrameTag& tag) {
    if (command_list == nullptr) {
        return false;
    }
    std::scoped_lock lock{g_dlss_submission_mutex};
    const auto found = g_dlss_pending_submissions.find(command_list);
    if (found == g_dlss_pending_submissions.end() ||
        found->second.empty()) {
        return false;
    }
    tag = found->second.back();
    return tag.task_provenance_valid && tag.eye <= 1 && tag.pair_id != 0 &&
        tag.pair_id != UINT64_MAX && tag.generation ==
            g_streamline_capture_generation.load(std::memory_order_acquire);
}

// [FIX:AER-TAAU-FULL-VR-HUD-COMMAND-TAG V1302 1/5] TAAU already freezes
// the exact matrix-resolved eye/pair on its recording command list before
// ExecuteCommandLists detaches the pending submission. Expose that immutable
// identity to the Cinema HUD selector just as DLSS exposes its recording
// producer tag; never substitute the previously completed render task.
bool lookup_taau_recording_producer(
    ID3D12GraphicsCommandList* command_list,
    EngineFrameTag& tag) {
    if (command_list == nullptr) {
        return false;
    }
    std::scoped_lock lock{g_taau_submission_mutex};
    const auto found = g_taau_pending_submissions.find(command_list);
    if (found == g_taau_pending_submissions.end() ||
        found->second.empty()) {
        return false;
    }
    tag = found->second.back();
    return tag.task_provenance_valid && tag.eye <= 1 && tag.pair_id != 0 &&
        tag.pair_id != UINT64_MAX && tag.generation ==
            g_streamline_capture_generation.load(std::memory_order_acquire);
}

bool valid_aer_cinema_exact_tag(const EngineFrameTag& tag) {
    return tag.task_provenance_valid && tag.eye <= 1 &&
        tag.pair_id != 0 && tag.pair_id != UINT64_MAX &&
        tag.generation == g_streamline_capture_generation.load(
            std::memory_order_acquire);
}

bool mode3_aer_cinema_exact_eye_contract_active() {
    const bool supported_backend =
        g_config.temporal_backend == TemporalBackend::None ||
        g_config.temporal_backend == TemporalBackend::Taau ||
        g_config.temporal_backend == TemporalBackend::Dlss;
    const bool automatic_full_vr =
        !g_force_mono_cinema.load(std::memory_order_relaxed) &&
        g_config.cinema_full_vr &&
        (g_cinema_mode_active.load(std::memory_order_relaxed) ||
            g_automatic_full_vr_camera_active.load(
                std::memory_order_acquire));
    return mode3_aer_presentation_active() && supported_backend &&
        (mode3_aer_cinema_sequential_present_source_active() ||
            automatic_full_vr) &&
        !g_engine_loading_screen_video_active.load(
            std::memory_order_acquire) &&
        g_engine_menu_state.load(std::memory_order_relaxed) == 0;
}

bool current_exact_engine_render_tag(EngineFrameTag& tag) {
    const uint32_t generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    if (!g_engine_render_tag_frame_lookup_exact ||
        g_engine_render_eye < 0 || g_engine_render_eye > 1 ||
        g_engine_render_pair_id == 0 ||
        g_engine_render_pair_id == UINT64_MAX ||
        g_engine_render_generation != generation) {
        return false;
    }
    tag = {};
    tag.eye = static_cast<uint32_t>(g_engine_render_eye);
    tag.generation = g_engine_render_generation;
    tag.pair_id = g_engine_render_pair_id;
    tag.render_view = g_engine_render_view;
    tag.render_view_valid = g_engine_render_view_valid;
    tag.pixel_projection = g_engine_render_pixel_projection;
    tag.hmd_pose = g_engine_render_hmd_pose;
    tag.task_provenance_valid = true;
    return true;
}

void record_aer_cinema_command_list_render_tag(
    ID3D12GraphicsCommandList* command_list,
    const EngineFrameTag& tag) {
    if (command_list == nullptr || !valid_aer_cinema_exact_tag(tag)) {
        return;
    }
    std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
    g_aer_cinema_command_list_render_tags[command_list] = tag;
}

bool resolve_aer_cinema_command_list_tag(
    ID3D12GraphicsCommandList* command_list,
    EngineFrameTag& tag) {
    if (current_exact_engine_render_tag(tag)) {
        record_aer_cinema_command_list_render_tag(command_list, tag);
        return true;
    }
    if (command_list != nullptr) {
        {
            std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
            const auto found =
                g_aer_cinema_command_list_render_tags.find(command_list);
            if (found != g_aer_cinema_command_list_render_tags.end()) {
                tag = found->second;
                if (valid_aer_cinema_exact_tag(tag)) {
                    return true;
                }
            }
        }
        if ((lookup_dlss_recording_producer(command_list, tag) ||
                lookup_taau_recording_producer(command_list, tag) ||
                lookup_streamline_command_list_route(command_list, tag)) &&
            valid_aer_cinema_exact_tag(tag)) {
            record_aer_cinema_command_list_render_tag(command_list, tag);
            return true;
        }
    }
    return false;
}

void record_aer_cinema_hud_draw_proof(
    ID3D12GraphicsCommandList* command_list) {
    if (!mode3_aer_cinema_exact_eye_contract_active()) {
        return;
    }
    EngineFrameTag tag{};
    const bool exact_tag =
        resolve_aer_cinema_command_list_tag(command_list, tag);
    const uint64_t producer_present =
        g_present_count.load(std::memory_order_relaxed);
    std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
    auto& proof = g_aer_cinema_hud_proofs[producer_present];
    proof.draw_seen = true;
    const bool resolved_exact_tag =
        exact_tag && valid_aer_cinema_exact_tag(tag);
    if (resolved_exact_tag) {
        // The final HUD draw in this producer interval owns the final
        // backbuffer. Deferred auxiliary draws may precede it, so retain the
        // newest exact tag instead of deriving a backend-specific phase.
        proof.tag = tag;
        proof.tag_valid = true;
    }
    for (auto it = g_aer_cinema_hud_proofs.begin();
         it != g_aer_cinema_hud_proofs.end();) {
        if (it->first + 8 < producer_present) {
            it = g_aer_cinema_hud_proofs.erase(it);
        } else {
            ++it;
        }
    }
}

void publish_aer_cinema_completed_frame(
    const EngineFrameTag& source_tag,
    uint64_t producer_present) {
    if (!mode3_aer_presentation_active() ||
        !valid_aer_cinema_exact_tag(source_tag)) {
        return;
    }
    AerCinemaCompletedFrame completed{};
    completed.tag = source_tag;
    completed.producer_present = producer_present;
    completed.serial = g_aer_cinema_completed_frame_serial.fetch_add(
        1, std::memory_order_relaxed) + 1;
    std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
    // [FIX:AER-CINEMA-DEFERRED-HUD-JOIN V1215 1/2] The final Cinema HUD draw
    // can occur after REDengine's task TLS has unwound on every AER route.
    // [FIX:AER-TAAU-FULL-VR-HUD-COMMAND-TAG V1302 2/5] Preserve a proof
    // already resolved from the exact recording command list. Only a draw
    // that genuinely lacked command-list identity may be joined to the
    // completed task here. Overwriting an exact TAAU proof used to conceal
    // the eye-0 PSO baked into an eye-1 HUD capture.
    const auto hud_proof =
        g_aer_cinema_hud_proofs.find(producer_present);
    if (hud_proof != g_aer_cinema_hud_proofs.end() &&
        hud_proof->second.draw_seen && !hud_proof->second.tag_valid) {
        hud_proof->second.tag = source_tag;
        hud_proof->second.tag_valid = true;
    }
    if (g_aer_cinema_completed_frames.size() >= 32) {
        g_aer_cinema_completed_frames.pop_front();
    }
    g_aer_cinema_completed_frames.push_back(completed);
}

bool latest_aer_cinema_completed_frame(
    AerCinemaCompletedFrame& completed) {
    std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
    for (auto it = g_aer_cinema_completed_frames.rbegin();
         it != g_aer_cinema_completed_frames.rend(); ++it) {
        if (valid_aer_cinema_exact_tag(it->tag)) {
            completed = *it;
            return true;
        }
    }
    return false;
}

bool select_aer_cinema_completed_frame(
    uint64_t current_present,
    uint64_t pair_floor,
    AerCinemaCompletedFrame& completed,
    AerCinemaHudProof& hud_proof,
    bool& hud_match) {
    if (current_present == 0) {
        return false;
    }
    const uint64_t producer_present = current_present - 1;
    bool found{};
    std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
    for (const auto& candidate : g_aer_cinema_completed_frames) {
        if (candidate.producer_present == producer_present &&
            candidate.serial > g_sequential_cinema_completed_serial &&
            candidate.tag.pair_id >= pair_floor &&
            valid_aer_cinema_exact_tag(candidate.tag) &&
            (!found || candidate.serial > completed.serial)) {
            completed = candidate;
            found = true;
        }
    }
    for (auto it = g_aer_cinema_completed_frames.begin();
         it != g_aer_cinema_completed_frames.end();) {
        if (it->producer_present + 8 < current_present) {
            it = g_aer_cinema_completed_frames.erase(it);
        } else {
            ++it;
        }
    }
    if (!found) {
        return false;
    }
    const auto proof = g_aer_cinema_hud_proofs.find(producer_present);
    hud_proof = proof != g_aer_cinema_hud_proofs.end()
        ? proof->second : AerCinemaHudProof{};
    hud_match = !hud_proof.draw_seen ||
        (hud_proof.tag_valid &&
            hud_proof.tag.eye == completed.tag.eye &&
            hud_proof.tag.pair_id == completed.tag.pair_id &&
            hud_proof.tag.generation == completed.tag.generation);
    return hud_match;
}

void reset_aer_cinema_exact_eye_contract() {
    std::scoped_lock lock{g_aer_cinema_exact_eye_mutex};
    g_aer_cinema_completed_frames.clear();
    g_aer_cinema_hud_proofs.clear();
    g_aer_cinema_command_list_render_tags.clear();
}

// Freeze the identity of REDengine's final HUD writer without joining it to
// scene cadence. Automatic Full VR requires the exact sequential task tag;
// AFW gameplay retains its established temporal producer fallback.

void record_mode3_aer_retained_hud_tag(
    ID3D12GraphicsCommandList* command_list,
    int hud_eye,
    uint64_t hud_pair_id = 0) {
    const bool sequential_full_vr =
        mode3_aer_sequential_full_vr_retained_hud_active();
    if (!mode3_aer_submitted_hud_join_active() ||
        command_list == nullptr) {
        return;
    }

    const uint32_t generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    EngineFrameTag tag{};
    // [FIX:AER-FULL-VR-RETAINED-HUD V1508 4/6] Full VR accepts only the exact
    // task tag already shared by its HUD PSO and final-backbuffer capture.
    // AFW gameplay preserves its established recording-producer chain and
    // natural-ordinal fallback.
    bool exact_tag = sequential_full_vr
        ? resolve_aer_cinema_command_list_tag(command_list, tag)
        : (lookup_dlss_recording_producer(command_list, tag) ||
            lookup_taau_recording_producer(command_list, tag) ||
            lookup_streamline_command_list_route(command_list, tag));
    exact_tag = exact_tag && tag.eye <= 1 && tag.pair_id != 0 &&
        tag.pair_id != UINT64_MAX && tag.generation == generation &&
        (hud_pair_id == 0 || tag.pair_id == hud_pair_id) &&
        (hud_eye < 0 || hud_eye > 1 ||
            tag.eye == static_cast<uint32_t>(hud_eye));

    if (!exact_tag) {
        if (sequential_full_vr) {
            return;
        }
        const uint64_t next_ordinal =
            g_mode3_afw_natural_render_ordinal.load(
                std::memory_order_acquire);
        if (next_ordinal == UINT64_MAX || next_ordinal == 0) {
            return;
        }
        uint64_t hud_ordinal = next_ordinal - 1;
        auto identity =
            w3vr::aer::identity_for_render_ordinal(hud_ordinal);
        if (hud_eye >= 0 && hud_eye <= 1 &&
            identity.eye != static_cast<uint32_t>(hud_eye)) {
            if (hud_ordinal == 0) {
                return;
            }
            --hud_ordinal;
            identity = w3vr::aer::identity_for_render_ordinal(
                hud_ordinal);
        }
        if (hud_eye >= 0 && hud_eye <= 1 &&
            identity.eye != static_cast<uint32_t>(hud_eye)) {
            return;
        }
        tag = make_aer_frame_tag(hud_ordinal);
    }

    if (tag.eye > 1 || tag.pair_id == 0 ||
        tag.pair_id == UINT64_MAX || tag.generation != generation) {
        return;
    }
    tag.task_provenance_valid = true;
    std::scoped_lock lock{g_mode3_aer_afw_hud_mutex};
    g_mode3_aer_afw_pending_hud_tags[command_list] = {
        tag, g_present_count.load(std::memory_order_relaxed)};
}

void queue_mode3_aer_afw_hud_present_boundary(
    ID3D12GraphicsCommandList* command_list,
    uint64_t present) {
    if (command_list == nullptr) {
        return;
    }
    std::scoped_lock lock{g_mode3_aer_afw_hud_mutex};
    g_mode3_aer_afw_pending_hud_presents[command_list] = {
        g_streamline_capture_generation.load(std::memory_order_acquire),
        present};
}

void reset_rt_temporal_lineage_for_route_epoch(uint64_t route_epoch) {
    // Menu/loading/Cinema can advance AFW's logical route without changing
    // the renderer generation. Keep the GPU allocations alive, but revoke all
    // exact AO/SIGMA/REBLUR history ownership under one lifecycle edge so the
    // first post-resume dispatch cannot accumulate a stale-eye texture.
    const uint32_t generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    record_rt_flight(
        w3vr::rt_flight::EventCode::RouteReset,
        UINT32_MAX, 0, 0, w3vr::rt_flight::RejectReason::None,
        0, static_cast<uint32_t>(rt_history_slot_count()), 0, 0, 0,
        generation, route_epoch);
    // [FIX:RT-COMMAND-LIST-IDENTITY-LATCH V1225 3/3] An epoch edge revokes
    // every in-flight CPU identity before new RTX transactions are admitted.
    g_rt_command_identity_latch.clear();
    {
        std::scoped_lock reset_lock{
            g_rt_shadow_history_mutex,
            g_rt_specular_history_mutex,
            g_rt_ao_history_mutex};
        g_rt_ao_history_generation = generation;
        g_rt_ao_history_pairs = {};
        g_rt_ao_history_transactions = {};
        g_rt_ao_camera_histories = {};

        g_rt_shadow_history_generation = generation;
        g_rt_shadow_history_pairs = {};
        g_rt_shadow_history_transactions = {};

        g_rt_specular_history_generation = generation;
        g_rt_specular_history_pairs = {};
        g_rt_specular_last_eye = UINT32_MAX;
        g_rt_specular_last_pair = 0;
        g_rt_specular_last_generation = generation;
        g_rt_specular_last_write_slot = kRtInvalidHistorySlot;

    }
    if (g_config.runtime_diagnostics) {
        log_line(
            "V1174 RT temporal lineage reset route_epoch=%llu generation=%u",
            static_cast<unsigned long long>(route_epoch), generation);
    }
}

void reset_puredark_afw_publication_state() {
    const uint64_t route_epoch =
        g_puredark_afw_route_epoch.fetch_add(
            1, std::memory_order_acq_rel) + 1;
    // [FIX:RT-RELEASE-METADATA-OWNERSHIP V1175 3/8] The AFW epoch remains
    // AER-owned. Touch RT lineage and its bounded diagnostic counters only
    // when the independent INI-controlled RT temporal route is enabled.
    if (rt_symmetric_dlss_per_eye_ao_history_active()) {
        reset_rt_temporal_lineage_for_route_epoch(route_epoch);
        // [DIAG:RT-LINEAGE-CENSUS V1165 5/5] Re-open the bounded census window
        // for the exact transition under test.
        g_rt_lineage_ao_reader_reject_logs.store(0, std::memory_order_relaxed);
        g_rt_lineage_ao_writer_logs.store(0, std::memory_order_relaxed);
        g_rt_lineage_ao_gap_join_logs.store(0, std::memory_order_relaxed);
    }
    g_puredark_afw_steady_active.store(false, std::memory_order_release);
    std::scoped_lock lock{g_puredark_afw_mutex};
    // [FIX:PUREDARK-AFW-MODE3-DLSS-INPUT-FIFO V12064 2/8] Revoke every
    // unconsumed ready producer at a logical route boundary. Recording and
    // submitted/in-flight slots retain their existing epoch/fence lifecycle.
    for (auto& ready : g_puredark_afw_bundle_ring) {
        if (ready.state != PuredarkAfwBundleState::Ready) {
            continue;
        }
        ready.state = PuredarkAfwBundleState::Free;
        ready.input.valid = false;
        ready.submission_serial = 0;
        ready.ready_present = UINT64_MAX;
        ready.producer_queue_fence = nullptr;
        ready.producer_queue_fence_value = 0;
    }
    g_puredark_afw_ready_bundle = UINT32_MAX;
    g_puredark_afw_mode3_common_ready_queue.clear();
    g_mode3_afw_selected_bundle_slot = UINT32_MAX;
    g_puredark_afw_camera_history.clear();
    g_puredark_afw_streamline_camera_history.clear();
    if (puredark_afw_mode3_aer_common_transport_configured()) {
        reset_mode3_afw_sequenced_pair_state(
            g_streamline_capture_generation.load(std::memory_order_acquire));
    }
}

void finish_puredark_afw_xr_bundle(
    bool submitted,
    uint64_t fence_value) {
    std::scoped_lock lock{g_puredark_afw_mutex};
    if (g_puredark_afw_consuming_bundle >=
            kPuredarkAfwBundleRingSize) {
        return;
    }
    auto& slot = g_puredark_afw_bundle_ring[
        g_puredark_afw_consuming_bundle];
    if (slot.state == PuredarkAfwBundleState::Consuming) {
        if (submitted && fence_value != 0) {
            slot.state = PuredarkAfwBundleState::InFlight;
            slot.retire_fence = fence_value;
        } else {
            slot.state = PuredarkAfwBundleState::Free;
            slot.input.valid = false;
            slot.submission_serial = 0;
            slot.ready_present = UINT64_MAX;
            slot.producer_queue_fence = nullptr;
            slot.producer_queue_fence_value = 0;
            slot.retire_fence = 0;
        }
    }
    g_puredark_afw_consuming_bundle = UINT32_MAX;
}

bool initialize_puredark_afw_frame_buffers_locked(
    const D3D12_RESOURCE_DESC& backbuffer_desc,
    std::wstring& error) {
    if (g_puredark_afw_width == backbuffer_desc.Width &&
        g_puredark_afw_height == backbuffer_desc.Height &&
        g_puredark_afw_format == backbuffer_desc.Format &&
        g_puredark_afw_eye_buffers.eye_frame_buffers[0].color.texture != nullptr &&
        g_puredark_afw_eye_buffers.eye_frame_buffers[1].color.texture != nullptr) {
        error.clear();
        return true;
    }
    if (backbuffer_desc.Width == 0 || backbuffer_desc.Width > INT_MAX ||
        backbuffer_desc.Height == 0 || backbuffer_desc.Height > INT_MAX ||
        backbuffer_desc.SampleDesc.Count != 1 ||
        backbuffer_desc.Format == DXGI_FORMAT_UNKNOWN) {
        error = L"AER backbuffer descriptor is unsupported by AFW";
        return false;
    }

    w3vr::puredark_afw::FrameWarpInitParams init{};
    init.hmd_width = static_cast<int>(backbuffer_desc.Width);
    init.hmd_height = static_cast<int>(backbuffer_desc.Height);
    init.eye_format = backbuffer_desc.Format;
    init.backbuffer_format = backbuffer_desc.Format;
    w3vr::puredark_afw::EyeFrameBuffers eye_buffers{};
    if (!g_puredark_afw_bridge->initialize_frame_warp(
            init, eye_buffers, error)) {
        return false;
    }
    for (uint32_t eye = 0; eye < 2; ++eye) {
        const auto desc =
            eye_buffers.eye_frame_buffers[eye].color.texture->GetDesc();
        if (desc.Width != backbuffer_desc.Width ||
            desc.Height != backbuffer_desc.Height ||
            desc.Format != backbuffer_desc.Format) {
            error = L"PureDark eye framebuffer does not match AER backbuffer";
            return false;
        }
    }
    g_puredark_afw_eye_buffers = eye_buffers;
    g_puredark_afw_width = static_cast<UINT>(backbuffer_desc.Width);
    g_puredark_afw_height = backbuffer_desc.Height;
    g_puredark_afw_format = backbuffer_desc.Format;
    error.clear();
    return true;
}

// [REFACTOR:PUREDARK-AFW-COMMON-TRANSPORT V12104 3/8] DLSS and TAAU use the
// same transaction after their producer freezes an exact immutable bundle:
// color copy, EvaluateFrameWarp and peer publication remain on the XR list.
// Backend-specific discovery never leaks into this consumer.
bool evaluate_puredark_afw_mode3_common(
    ID3D12GraphicsCommandList* command_list,
    ID3D12Resource* source_color,
    const D3D12_RESOURCE_DESC& source_desc,
    uint32_t generation,
    uint32_t real_eye,
    uint64_t pair_id,
    uint64_t present_count,
    PuredarkAfwPresentResult& result) {
    w3vr::pipeline_flight::CpuScope flight_cpu{
        w3vr::pipeline_flight::Phase::Afw};
    result = {};
    RouteFlightOutcomeScope route_flight{
        w3vr::route_flight::EventCode::AfwEvaluate,
        static_cast<int32_t>(real_eye), pair_id, generation,
        static_cast<uint32_t>(source_desc.Width)};
    record_rt_flight(
        w3vr::rt_flight::EventCode::AfwEvaluateBegin,
        real_eye, pair_id, 0, w3vr::rt_flight::RejectReason::None,
        0, static_cast<uint32_t>(source_desc.Width), source_desc.Height,
        static_cast<uint32_t>(source_desc.Format),
        static_cast<uint32_t>(present_count), generation);
    if (!puredark_afw_mode3_aer_common_transport_configured() ||
        command_list == nullptr || source_color == nullptr ||
        real_eye > 1 || pair_id == 0 || pair_id == UINT64_MAX ||
         generation != g_streamline_capture_generation.load(
             std::memory_order_acquire)) {
        const uint32_t flags =
            (puredark_afw_mode3_aer_common_transport_configured() ? 0x01u : 0u) |
            (command_list != nullptr ? 0x02u : 0u) |
            (source_color != nullptr ? 0x04u : 0u) |
            (real_eye <= 1 ? 0x08u : 0u) |
            (pair_id != 0 && pair_id != UINT64_MAX ? 0x10u : 0u) |
            (generation == g_streamline_capture_generation.load(
                std::memory_order_relaxed) ? 0x20u : 0u);
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Identity, flags,
            static_cast<uint32_t>(source_desc.Width), source_desc.Height,
            static_cast<uint32_t>(source_desc.Format), 0, generation);
        return false;
    }
    route_flight.advance(
        2, 0x02u, source_desc.Height,
        static_cast<uint32_t>(source_desc.Format),
        static_cast<uint32_t>(present_count));
    const float cant_degrees =
        g_runtime_eye_cant_degrees.load(std::memory_order_relaxed);
    if (std::isfinite(cant_degrees) && std::fabs(cant_degrees) > 0.25f) {
        log_puredark_afw_failure(
            "mode3_common_runtime_cant",
            L"canted-eye AFW camera is not implemented");
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Camera, 0,
            static_cast<uint32_t>(std::fabs(cant_degrees) * 1000.0f),
            0, 0, 0, generation);
        return false;
    }

    std::scoped_lock lock{g_puredark_afw_mutex};
    if (g_mode3_afw_selected_bundle_slot >=
            kPuredarkAfwBundleRingSize ||
        g_puredark_afw_consuming_bundle < kPuredarkAfwBundleRingSize) {
        log_puredark_afw_failure(
            "mode3_common_producer_ready",
            L"no exact queued Mode-3 AFW bundle is selected");
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Fifo, 0,
            g_mode3_afw_selected_bundle_slot,
            g_puredark_afw_consuming_bundle,
            static_cast<uint32_t>(
                g_puredark_afw_mode3_common_ready_queue.size()),
            0, generation);
        return false;
    }
    const uint32_t bundle_slot = g_mode3_afw_selected_bundle_slot;
    auto& slot = g_puredark_afw_bundle_ring[bundle_slot];
    auto& captured = slot.input;
    if (slot.state != PuredarkAfwBundleState::Ready ||
        !captured.valid || captured.eye != real_eye ||
        captured.pair_id != pair_id || captured.generation != generation ||
        !captured.render_views_valid ||
        !captured.exact_render_view_valid ||
        slot.submission_serial == 0 ||
        captured.depth.texture == nullptr ||
        captured.motion_vectors.texture == nullptr) {
        log_puredark_afw_failure(
            "mode3_common_producer_identity",
            L"submitted AFW bundle does not match the promoted eye/pair");
        const uint32_t flags =
            (slot.state == PuredarkAfwBundleState::Ready ? 0x01u : 0u) |
            (captured.valid ? 0x02u : 0u) |
            (captured.eye == real_eye ? 0x04u : 0u) |
            (captured.pair_id == pair_id ? 0x08u : 0u) |
            (captured.generation == generation ? 0x10u : 0u) |
            (captured.render_views_valid ? 0x20u : 0u) |
            (captured.exact_render_view_valid ? 0x40u : 0u) |
            (captured.depth.texture != nullptr ? 0x80u : 0u) |
            (captured.motion_vectors.texture != nullptr ? 0x100u : 0u);
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, captured.pair_id,
            w3vr::rt_flight::RejectReason::Bundle, flags,
            bundle_slot, static_cast<uint32_t>(slot.state),
            captured.eye, captured.generation, generation);
        return false;
    }
    route_flight.advance(
        3, 0x04u, bundle_slot,
        static_cast<uint32_t>(slot.submission_serial),
        static_cast<uint32_t>(
            g_puredark_afw_mode3_common_ready_queue.size()));

    // V1224: the final DXGI backbuffer is the color authority. The immutable
    // producer ticket supplies identity, depth, motion, camera, and ordering;
    // the raw NGX Output is intentionally not used as a presented image.
    auto* const exact_source_color = source_color;
    const auto exact_source_desc = source_desc;

    std::wstring error;
    if (!ensure_puredark_afw_device_locked(error) ||
        !initialize_puredark_afw_frame_buffers_locked(
            exact_source_desc, error)) {
        log_puredark_afw_failure("mode3_common_resources", error);
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Resource, 0,
            bundle_slot, static_cast<uint32_t>(exact_source_desc.Width),
            exact_source_desc.Height,
            static_cast<uint32_t>(exact_source_desc.Format),
            generation);
        return false;
    }
    route_flight.advance(4, 0x08u, bundle_slot);

    const auto queued = std::find(
        g_puredark_afw_mode3_common_ready_queue.begin(),
        g_puredark_afw_mode3_common_ready_queue.end(), bundle_slot);
    if (queued == g_puredark_afw_mode3_common_ready_queue.end()) {
        log_puredark_afw_failure(
            "mode3_common_producer_ready",
            L"selected Mode-3 AFW bundle left the input FIFO");
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Fifo, 0,
            bundle_slot,
            static_cast<uint32_t>(
                g_puredark_afw_mode3_common_ready_queue.size()),
            0, 0, generation);
        return false;
    }
    // [FIX:PUREDARK-AFW-CROSS-QUEUE-PUBLICATION V12099 3/6] A non-zero
    // producer fence means NGX submitted this immutable bundle on another
    // DIRECT queue. Queue the GPU wait before the XR list which copies the
    // color and calls EvaluateFrameWarp. No CPU stall and no timing window are
    // introduced; the bundle remains selectable if the wait cannot be queued.
    if (slot.producer_queue_fence != nullptr &&
        slot.producer_queue_fence_value != 0) {
        if (g_command_queue == nullptr) {
            log_puredark_afw_failure(
                "mode3_common_cross_queue_wait",
                L"cross-queue producer fence is unavailable");
            record_rt_flight(
                w3vr::rt_flight::EventCode::AfwEvaluateRejected,
                real_eye, pair_id, 0,
                w3vr::rt_flight::RejectReason::CrossQueue, 0,
                bundle_slot,
                static_cast<uint32_t>(slot.producer_queue_fence_value),
                0, 0, generation);
            return false;
        }
        const HRESULT wait_result = g_command_queue->Wait(
            slot.producer_queue_fence,
            slot.producer_queue_fence_value);
        if (FAILED(wait_result)) {
            log_line(
                "V12099 AFW cross-queue wait failed primary=%p value=%llu "
                "hr=0x%08X",
                g_command_queue,
                static_cast<unsigned long long>(
                    slot.producer_queue_fence_value),
                static_cast<unsigned>(wait_result));
            record_rt_flight(
                w3vr::rt_flight::EventCode::AfwEvaluateRejected,
                real_eye, pair_id, 0,
                w3vr::rt_flight::RejectReason::CrossQueue, 0,
                bundle_slot, static_cast<uint32_t>(wait_result),
                static_cast<uint32_t>(slot.producer_queue_fence_value),
                0, generation);
            return false;
        }
        const uint64_t wait_count =
            g_puredark_afw_cross_queue_waits.fetch_add(
                1, std::memory_order_relaxed) + 1;
        if (wait_count <= 32 || (wait_count % 240) == 0) {
            log_line(
                "V12099 AFW cross-queue consumer wait count=%llu "
                "primary=%p value=%llu slot=%u pair=%llu eye=%u",
                static_cast<unsigned long long>(wait_count),
                g_command_queue,
                static_cast<unsigned long long>(
                    slot.producer_queue_fence_value),
                bundle_slot,
                static_cast<unsigned long long>(pair_id), real_eye);
        }
    }
    g_puredark_afw_mode3_common_ready_queue.erase(queued);
    g_mode3_afw_selected_bundle_slot = UINT32_MAX;
    slot.state = PuredarkAfwBundleState::Consuming;
    g_puredark_afw_consuming_bundle = bundle_slot;
    route_flight.advance(
        5, 0x10u, bundle_slot,
        static_cast<uint32_t>(
            g_puredark_afw_mode3_common_ready_queue.size()),
        static_cast<uint32_t>(present_count - slot.ready_present));
    const uint64_t selected_count = g_mode3_afw_fifo_selected.fetch_add(
        1, std::memory_order_relaxed) + 1;
    if (g_config.runtime_diagnostics &&
        (selected_count <= 32 || (selected_count % 240) == 0)) {
        log_line(
            "V12065 AFW input FIFO consumed count=%llu present=%llu slot=%u eye=%u pair=%llu generation=%u remaining=%zu ready_present=%llu age=%llu",
            static_cast<unsigned long long>(selected_count),
            static_cast<unsigned long long>(present_count), bundle_slot,
            real_eye, static_cast<unsigned long long>(pair_id), generation,
            g_puredark_afw_mode3_common_ready_queue.size(),
            static_cast<unsigned long long>(slot.ready_present),
            static_cast<unsigned long long>(
                present_count - slot.ready_present));
    }
    const auto depth_desc = captured.depth.texture->GetDesc();
    const auto motion_desc = captured.motion_vectors.texture->GetDesc();
    w3vr::pipeline_flight::GpuScope flight_gpu{
        w3vr::pipeline_flight::Phase::Afw, command_list};
    auto input = g_puredark_afw_eye_buffers.eye_frame_buffers[real_eye];
    w3vr::puredark_afw::TextureDesc color_source{};
    color_source.texture = exact_source_color;
    color_source.initial_state = D3D12_RESOURCE_STATE_COPY_SOURCE;
    const D3D12_BOX color_box{
        0, 0, 0, static_cast<UINT>(exact_source_desc.Width),
        exact_source_desc.Height, 1};
    if (!g_puredark_afw_bridge->copy_texture(
            command_list, input.color, color_source,
            color_box, 0, 0, error)) {
        log_puredark_afw_failure("mode3_common_color_copy", error);
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::ColorCopy, 0,
            bundle_slot, 0, 0, 0, generation);
        return false;
    }
    input.depth = captured.depth;
    input.motion_vectors = captured.motion_vectors;

    auto camera = captured.camera;
    w3vr::puredark_afw::FrameWarpEvaluateParams evaluate{};
    evaluate.command_list = command_list;
    evaluate.input_eye_frame_buffer = &input;
    evaluate.motion_scale[0] = captured.motion_scale[0];
    evaluate.motion_scale[1] = captured.motion_scale[1];
    // [FIX:PUREDARK-AFW-MODE3-DLSS-COMBINED-WARPING V12062 1/2]
    // beta.5 defaults to CombinedWarping. Its previous-frame component is the
    // one isolated parameter intended to stabilize temporal/head-rotation
    // reprojection in addition to generating the spatial peer eye.
    evaluate.mode = w3vr::puredark_afw::CombinedWarping;
    evaluate.eye_index = static_cast<w3vr::puredark_afw::EyeIndex>(real_eye);
    evaluate.camera_data = &camera;
    evaluate.clear_before_warping = false;
    evaluate.ignore_motion_threshold = 2.5f;
    evaluate.is_hudless_color = true;
    evaluate.motion_vectors_type = w3vr::puredark_afw::Normal;
    evaluate.debug = g_puredark_afw_visual_debug.load(
        std::memory_order_relaxed);
    evaluate.use_uint64 = false;
    if (!g_puredark_afw_bridge->evaluate(evaluate, error)) {
        log_puredark_afw_failure("mode3_common_evaluate", error);
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Evaluate, 0,
            bundle_slot, 0, 0, 0, generation);
        return false;
    }
    route_flight.advance(6, 0x20u, bundle_slot);
    if (evaluate.output_eye_frame_buffer == nullptr ||
        evaluate.output_eye_frame_buffer->color.texture == nullptr) {
        log_puredark_afw_failure(
            "mode3_common_output", L"PureDark returned no synthesized texture");
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Output, 0,
            bundle_slot, 0, 0, 0, generation);
        return false;
    }

    const auto synthesized = evaluate.output_eye_frame_buffer->color;
    const auto synthesized_desc = synthesized.texture->GetDesc();
    if (synthesized_desc.Width != exact_source_desc.Width ||
        synthesized_desc.Height != exact_source_desc.Height ||
        synthesized_desc.Format != exact_source_desc.Format) {
        log_puredark_afw_failure(
            "mode3_common_output",
            L"synthesized texture does not match Mode-3 eye cache");
        record_rt_flight(
            w3vr::rt_flight::EventCode::AfwEvaluateRejected,
            real_eye, pair_id, 0,
            w3vr::rt_flight::RejectReason::Output, 0,
            bundle_slot, static_cast<uint32_t>(synthesized_desc.Width),
            synthesized_desc.Height,
            static_cast<uint32_t>(synthesized_desc.Format), generation);
        return false;
    }

    result.real_color = color_source;
    result.synthesized_color = synthesized;
    result.render_views = captured.render_views;
    result.render_views_valid = captured.render_views_valid;
    result.exact_render_view = captured.exact_render_view;
    result.exact_render_view_valid = captured.exact_render_view_valid;
    result.pixel_projection = captured.pixel_projection;
    result.pair_id = pair_id;
    result.generation = generation;
    result.real_eye = real_eye;
    result.synthesized_eye = 1u - real_eye;
    result.bundle_slot = bundle_slot;
    result.submission_serial = slot.submission_serial;
    result.valid = true;

    g_puredark_afw_consumed_candidates.fetch_add(
        1, std::memory_order_relaxed);
    record_rt_flight(
        w3vr::rt_flight::EventCode::AfwEvaluated,
        real_eye, pair_id, 0, w3vr::rt_flight::RejectReason::None,
        0, bundle_slot,
        static_cast<uint32_t>(slot.submission_serial),
        static_cast<uint32_t>(
            g_puredark_afw_mode3_common_ready_queue.size()),
        static_cast<uint32_t>(present_count - slot.ready_present),
        generation);
    if (take_bounded_log_slot(g_puredark_afw_present_logs, 32)) {
        log_line(
            "V12104 AFW Mode-3 common evaluated backend=%s submitted_bundle=%u present=%llu pair=%llu real_eye=%u synthesized_eye=%u depth=%llux%u:%u mvec=%llux%u:%u scale=%.6f,%.6f",
            temporal_backend_name(), bundle_slot,
            static_cast<unsigned long long>(present_count),
            static_cast<unsigned long long>(pair_id), real_eye,
            result.synthesized_eye,
            static_cast<unsigned long long>(depth_desc.Width),
            depth_desc.Height, static_cast<unsigned>(depth_desc.Format),
            static_cast<unsigned long long>(motion_desc.Width),
            motion_desc.Height, static_cast<unsigned>(motion_desc.Format),
            captured.motion_scale[0], captured.motion_scale[1]);
    }
    route_flight.succeed(7, 0x40u);
    return true;
}

bool publish_puredark_afw_mode3_common(
    ID3D12GraphicsCommandList* command_list,
    const PuredarkAfwPresentResult& result) {
    RouteFlightOutcomeScope route_flight{
        w3vr::route_flight::EventCode::AfwPublish,
        static_cast<int32_t>(result.real_eye), result.pair_id,
        result.generation, result.bundle_slot};
    const bool route_configured =
        puredark_afw_mode3_aer_common_transport_configured();
    const bool real_eye_valid = result.real_eye <= 1;
    const bool synthesized_eye_valid = result.synthesized_eye <= 1;
    const uint64_t visible_real_pair = real_eye_valid
        ? g_packed_eye_version[result.real_eye]
        : UINT64_MAX;
    const bool identity_valid = real_eye_valid && synthesized_eye_valid &&
        result.real_eye != result.synthesized_eye && result.pair_id != 0;
    const bool generation_valid =
        result.generation == g_mode3_aer_presentation_generation;
    const bool real_color_valid =
        real_eye_valid && visible_real_pair == result.pair_id;
    const bool destination_valid = synthesized_eye_valid &&
        g_packed_present_cache[result.synthesized_eye] != nullptr;
    const bool output_valid = result.synthesized_color.texture != nullptr;
    const bool projection_pair_valid = result.render_views_valid &&
        result.pixel_projection !=
            w3vr::mode3_transport::AfwPixelProjection::Invalid;
    const bool native_asymmetric = result.pixel_projection ==
        w3vr::mode3_transport::AfwPixelProjection::NativeAsymmetric;
    if (!route_configured || command_list == nullptr || !result.valid ||
        !identity_valid || !generation_valid || !real_color_valid ||
        !destination_valid || !output_valid || !projection_pair_valid) {
        return false;
    }
    route_flight.advance(
        2, 0x02u, result.synthesized_eye,
        static_cast<uint32_t>(visible_real_pair),
        static_cast<uint32_t>(g_mode3_aer_presentation_generation));

    auto* destination = g_packed_present_cache[result.synthesized_eye];
    auto* synthesized = result.synthesized_color.texture;
    const auto destination_desc = destination->GetDesc();
    const auto synthesized_desc = synthesized->GetDesc();
    if (destination_desc.Dimension != synthesized_desc.Dimension ||
        destination_desc.Width != synthesized_desc.Width ||
        destination_desc.Height != synthesized_desc.Height ||
        destination_desc.Format != synthesized_desc.Format ||
        destination_desc.SampleDesc.Count != synthesized_desc.SampleDesc.Count ||
        destination_desc.SampleDesc.Quality !=
            synthesized_desc.SampleDesc.Quality) {
        log_puredark_afw_failure(
            "mode3_common_publish",
            L"generated output does not match the destination eye cache");
        return false;
    }
    route_flight.advance(
        3, 0x04u, static_cast<uint32_t>(destination_desc.Width),
        destination_desc.Height,
        static_cast<uint32_t>(destination_desc.Format));

    const bool transition_synthesized =
        result.synthesized_color.initial_state !=
            D3D12_RESOURCE_STATE_COPY_SOURCE;
    D3D12_RESOURCE_BARRIER barriers[2]{};
    UINT barrier_count{};
    if (transition_synthesized) {
        auto& barrier = barriers[barrier_count++];
        barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
        barrier.Transition.pResource = synthesized;
        barrier.Transition.StateBefore =
            result.synthesized_color.initial_state;
        barrier.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_SOURCE;
        barrier.Transition.Subresource =
            D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    }
    auto& destination_to_copy = barriers[barrier_count++];
    destination_to_copy.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    destination_to_copy.Transition.pResource = destination;
    destination_to_copy.Transition.StateBefore =
        D3D12_RESOURCE_STATE_COPY_SOURCE;
    destination_to_copy.Transition.StateAfter =
        D3D12_RESOURCE_STATE_COPY_DEST;
    destination_to_copy.Transition.Subresource =
        D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    command_list->ResourceBarrier(barrier_count, barriers);
    command_list->CopyResource(destination, synthesized);
    for (UINT index = 0; index < barrier_count; ++index) {
        std::swap(
            barriers[index].Transition.StateBefore,
            barriers[index].Transition.StateAfter);
    }
    command_list->ResourceBarrier(barrier_count, barriers);

    const uint32_t synthesized_eye = result.synthesized_eye;
    g_packed_eye_version[synthesized_eye] = result.pair_id;
    g_packed_present_cache_views[synthesized_eye] =
        result.render_views[synthesized_eye];
    g_packed_present_cache_view_valid[synthesized_eye] =
        result.render_views_valid;
    g_mode3_aer_packed_eye_valid[synthesized_eye] = true;
    g_mode3_aer_packed_eye_generated[synthesized_eye] = true;
    g_mode3_aer_packed_native_eye[0] = native_asymmetric;
    g_mode3_aer_packed_native_eye[1] = native_asymmetric;
    g_packed_present_cache_native_asymmetric =
        native_asymmetric;
    g_packed_present_cache_valid = true;
    g_packed_last_accepted_present =
        g_present_count.load(std::memory_order_relaxed);
    g_packed_runtime_ready.store(true, std::memory_order_release);
    if (g_config.runtime_diagnostics) {
        static std::atomic<uint32_t> publication_logs{};
        if (take_bounded_log_slot(publication_logs, 64)) {
            log_line(
                "V12104 AFW Mode-3 common published backend=%s pair=%llu real_eye=%u synthesized_eye=%u visible=%llu/%llu present=%llu",
            temporal_backend_name(),
            static_cast<unsigned long long>(result.pair_id),
                result.real_eye, result.synthesized_eye,
                static_cast<unsigned long long>(g_packed_eye_version[0]),
                static_cast<unsigned long long>(g_packed_eye_version[1]),
                static_cast<unsigned long long>(
                    g_present_count.load(std::memory_order_relaxed)));
        }
    }
    route_flight.succeed(4, 0x40u);
    return true;
}

// [FIX:PUREDARK-AFW-PRODUCER-PUBLICATION V12016 4/8] The submitted producer
// bundle is the image authority. Rebase its peer view without comparing it to
// the unrelated DXGI Present parity.
bool apply_puredark_afw_producer_view_authority(
    PuredarkAfwPresentResult& result) {
    if (!result.valid || result.real_eye > 1 ||
        result.synthesized_eye > 1 || !result.render_views_valid ||
        !result.exact_render_view_valid) {
        return false;
    }
    const uint32_t capture_generation =
        g_streamline_capture_generation.load(std::memory_order_acquire);
    if (result.generation != capture_generation ||
        result.pair_id == 0 || result.submission_serial == 0 ||
        result.bundle_slot >= kPuredarkAfwBundleRingSize) {
        log_puredark_afw_failure(
            "direct_view_identity",
            L"submitted producer view has invalid generation/eye/pair");
        return false;
    }

    const XrView exact_source = result.exact_render_view;

    const auto to_parallel_pose = [](const XrPosef& pose) {
        w3vr::puredark_afw::ParallelEyePose converted{};
        converted.orientation[0] = pose.orientation.x;
        converted.orientation[1] = pose.orientation.y;
        converted.orientation[2] = pose.orientation.z;
        converted.orientation[3] = pose.orientation.w;
        converted.position[0] = pose.position.x;
        converted.position[1] = pose.position.y;
        converted.position[2] = pose.position.z;
        return converted;
    };
    const auto& captured_source =
        result.render_views[result.real_eye];
    auto& rebased_destination =
        result.render_views[result.synthesized_eye];
    w3vr::puredark_afw::ParallelEyePose exact_destination{};
    std::wstring error;
    if (!w3vr::puredark_afw::rebase_parallel_eye_pose(
            to_parallel_pose(captured_source.pose),
            to_parallel_pose(rebased_destination.pose),
            to_parallel_pose(exact_source.pose),
            exact_destination, error)) {
        log_puredark_afw_failure("direct_view_rebase", error);
        return false;
    }

    result.render_views[result.real_eye] = exact_source;
    rebased_destination.pose.orientation = {
        exact_destination.orientation[0],
        exact_destination.orientation[1],
        exact_destination.orientation[2],
        exact_destination.orientation[3]};
    rebased_destination.pose.position = {
        exact_destination.position[0],
        exact_destination.position[1],
        exact_destination.position[2]};
    if (g_config.runtime_diagnostics) {
        g_sync_cache_update_count.fetch_add(1, std::memory_order_relaxed);
    }
    if (take_bounded_log_slot(g_puredark_afw_pose_logs, 16)) {
        log_line(
            "PureDark AFW direct-view authority present=%llu pair=%llu generation=%u real_eye=%u synthesized_eye=%u source_q=%.6f,%.6f,%.6f,%.6f target_p=%.6f,%.6f,%.6f",
            static_cast<unsigned long long>(
                g_present_count.load(std::memory_order_relaxed)),
            static_cast<unsigned long long>(result.pair_id),
            result.generation, result.real_eye, result.synthesized_eye,
            exact_source.pose.orientation.x,
            exact_source.pose.orientation.y,
            exact_source.pose.orientation.z,
            exact_source.pose.orientation.w,
            rebased_destination.pose.position.x,
            rebased_destination.pose.position.y,
            rebased_destination.pose.position.z);
    }
    return true;
}

void reset_asymmetric_authority_audit() {
    if (!asymmetric_authority_audit_active()) {
        return;
    }
    g_asymmetric_authority_audit_lines.store(0, std::memory_order_relaxed);
    g_asymmetric_authority_audit_flushed.store(0, std::memory_order_relaxed);
    for (auto& line : g_asymmetric_authority_audit_queue) {
        line.text[0] = '\0';
        line.ready.store(false, std::memory_order_relaxed);
    }
    std::scoped_lock lock{g_log_mutex};
    char path[MAX_PATH]{};
    GetModuleFileNameA(nullptr, path, sizeof(path));
    char* slash = strrchr(path, '\\');
    if (slash != nullptr) {
        slash[1] = '\0';
    }
    strcat_s(path, "witcher3vr-asymmetric-authority-audit.log");
    FILE* file{};
    if (fopen_s(&file, path, "w") == 0 && file != nullptr) {
        fprintf(file,
            "V1081 automatic_focus_shaders base=V1080 structural_family=1 immutable_eye_gs=1 b1_b12_read_only_gate=1 persistent_registry=1 real_smoke_owner=world_up_specialized diagnostics_required=0 shared_writes=0\n");
        fprintf(file,
            "contract span=(right-left,up-down) center_ndc=(-(right+left)/spanX,-(up+down)/spanY) optical_cartesian_px=center_ndc*(W,H)/2 redengine_px=(+optical_x,+optical_y); texture_y_down=-optical_y\n");
        fclose(file);
    }
}

void write_asymmetric_authority_audit(const char* fmt, ...) {
    if (!asymmetric_authority_audit_active() || fmt == nullptr) {
        return;
    }
    const uint32_t line_index =
        g_asymmetric_authority_audit_lines.fetch_add(
            1, std::memory_order_relaxed);
    if (line_index >= kAsymmetricAuthorityAuditMaximumLines) {
        return;
    }
    auto& line = g_asymmetric_authority_audit_queue[line_index];
    LARGE_INTEGER qpc{};
    QueryPerformanceCounter(&qpc);
    const int prefix_length = _snprintf_s(
        line.text.data(), line.text.size(), _TRUNCATE,
        "event=%u qpc=%lld ", line_index + 1,
        static_cast<long long>(qpc.QuadPart));
    const size_t used = prefix_length > 0
        ? static_cast<size_t>(prefix_length)
        : 0;
    va_list args{};
    va_start(args, fmt);
    const int formatted = _vsnprintf_s(
        line.text.data() + used, line.text.size() - used,
        _TRUNCATE, fmt, args);
    va_end(args);
    if (formatted < 0) {
        static constexpr char kTruncated[] = " [TRUNCATED]";
        constexpr size_t marker_size = sizeof(kTruncated);
        memcpy(
            line.text.data() + line.text.size() - marker_size,
            kTruncated, marker_size);
    }
    line.ready.store(true, std::memory_order_release);
}

// The producer hooks above run on REDengine, Streamline, NGX and culling
// threads. They only reserve and format one bounded in-memory slot. Disk I/O is
// deliberately deferred until DXGI Present has returned, so this observation
// build cannot delay the packed-eye handshake or either factory call.
void flush_asymmetric_authority_audit() {
    if (!asymmetric_authority_audit_active()) {
        return;
    }
    const uint32_t reserved = std::min(
        g_asymmetric_authority_audit_lines.load(std::memory_order_acquire),
        kAsymmetricAuthorityAuditMaximumLines);
    uint32_t flushed = g_asymmetric_authority_audit_flushed.load(
        std::memory_order_relaxed);
    if (flushed >= reserved) {
        return;
    }
    const uint64_t present =
        g_present_count.load(std::memory_order_relaxed);
    if (reserved < kAsymmetricAuthorityAuditMaximumLines &&
        present % 30 != 0) {
        return;
    }
    std::scoped_lock flush_lock{g_asymmetric_authority_audit_flush_mutex};
    flushed = g_asymmetric_authority_audit_flushed.load(
        std::memory_order_relaxed);
    if (flushed >= reserved) {
        return;
    }
    char path[MAX_PATH]{};
    GetModuleFileNameA(nullptr, path, sizeof(path));
    char* slash = strrchr(path, '\\');
    if (slash != nullptr) {
        slash[1] = '\0';
    }
    strcat_s(path, "witcher3vr-asymmetric-authority-audit.log");
    FILE* file{};
    if (fopen_s(&file, path, "a") != 0 || file == nullptr) {
        return;
    }
    while (flushed < reserved) {
        auto& line = g_asymmetric_authority_audit_queue[flushed];
        if (!line.ready.load(std::memory_order_acquire)) {
            break;
        }
        fputs(line.text.data(), file);
        fputc('\n', file);
        ++flushed;
    }
    fclose(file);
    g_asymmetric_authority_audit_flushed.store(
        flushed, std::memory_order_release);
}

bool safe_copy_asymmetric_authority(
    const void* source, void* destination, size_t bytes) {
    if (source == nullptr || destination == nullptr || bytes == 0) {
        return false;
    }
    __try {
        memcpy(destination, source, bytes);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

